    /**
     * submission/ajax중 에러가 발생한 경우 에러 처리 함수
     *
     * @date 2022.03.14
     * @private
     * @param {Object}
     *            resObj responseData 객체
     * @memberOf
     * @author InswaveSystems
     */
    _sbm_comErrorHandler: function(resObj) {
        //console.log("@@@ _sbm_comErrorHandler resObj-->", resObj)
        // server 오류 경우 - statusCode가 200이 아닌 경우
        if (resObj.responseStatusCode != 200) {
        	var errorMsg;
			try{
				var json = JSON.parse(resObj.responseBody);
				errorMsg = json.errors.errorMessage;
				if (resObj.responseStatusCode == 550){ // biz Exception 경우 공통 메시지창으로 표시
					errorMsg = errorMsg.replace("\\n","\n")
					scutilo.showMsg(scglblo.MSG.ERROR, errorMsg);
				}
				else{
					var msg = resObj.responseStatusCode + " Error\n요청경로 : ";
					if (json.errors.hostNm) msg += "[" + json.errors.hostNm + "] ";
					msg += json.errors.referedUrl + "\n" + errorMsg;
					scutilo.showMsg(scglblo.MSG.ERROR, msg);

					// 401인 경우 로그인 페이지로 이동
					if(resObj.responseStatusCode === 401) {
						window.location.href = "/";
					}
				}
			}catch(ex){
				errorMsg = resObj.responseStatusCode
					+ " Error\n요청경로 : " + resObj.resourceUri;
	            alert(errorMsg);
			}
            return false;
        }

        // 성공인 경우 하단 toast 메시지 출력
        var rsJSON = resObj.responseJSON || null;
        var message = rsJSON && rsJSON.message ? rsJSON.message : '';
        if (message && resObj.responseStatusCode === 200) {
        	com.win.showToastMessage(gcm.MESSAGE_CODE.STATUS_SUCCESS, message);
        }
    },
