	bindComponentData: function(_cfg) {
        var sc = $p.getComponentById(_cfg.scopeId);
        if(! sc) {
            throw new Error("@@@ gcm.bindComponentData error - scopeId 값을 추가해주세요. _cfg-->", _cfg)
        }
        else {
            if(! _cfg.compId) {
                throw new Error("@@@ gcm.bindComponentData error - compId 값을 추가해주세요. _cfg-->", _cfg);
            }
            else {
                var compArr = (_cfg.compId).replaceAll(" ", "").split(",");
                for(var idx in compArr) {
                    //컴포넌트 ID
                    var aTmpCompId = compArr[idx].split(':');
