/**
 * statusFlag값에 따라 message를 출력한다.
 *
 * @private
 * @date 2016.08.09
 * @param {Object}
 *            resultData 상태코드값 및 메시지가 담긴 JSON.
 * @param {String}
 *            resultData.message 메시지
 * @param {String}
 *            resultData.statusFlag 상태코드값
 * @memberOf com
 * @author InswaveSystems
 */
com.resultMsg = function(resultData) {
//    console.log("===>resultData", resultData);
    resultData.message = resultData.message || "";
    var msgCode = gcm.MESSAGE_CODE;

    // TODO : 에러 메시지 재정의 필요함.
    switch (resultData.statusFlag) {
    case msgCode.STATUS_ERROR:
        if (resultData.errorCode == "E0001") {
            com.win.alert(resultData.message + " 로그인 화면으로 이동하겠습니다.", "com.win.goHome");
        } else if (resultData.errorCode == "E9998") { // HTTP ERROR
            resultData.message = resultData.errorCode + " : " + resultData.message;
            com.win.alert(resultData.message);
        } else if (resultData.errorCode == "E9999") { // business logic error
            resultData.message = resultData.message;
        }
        break;
    case "N":
        resultData.statusFlag = msgCode.STATUS_ERROR;
        resultData.message = "서버가 정지된 상태입니다. 자세한 내용은 관리자에게 문의하시기 바랍니다.";
        break;
    default:
    }

    if (typeof $p.top().scwin.setResultMessage == "function") {
        $p.top().scwin.setResultMessage(resultData);
    }
};

