com.win.setTabTitleOnChange = function(tabComp, inx) {

    if ( typeof tabComp  === "string" ) {
    	tabComp = $p.getComponentById(tabComp);
    }

    if(!tabComp) return;

    if(!(tabComp.getPluginName && tabComp.getPluginName() === 'tabControl')) return

    var tabArr = tabComp.tabArr;

    function setTabTitle(tabID, titleVal) {
    	var tag = $p.$("#"+tabID+" a");
    	if(tag.length !== 1) return;
    	tag[0].setAttribute('title', titleVal);
    }

    tabArr.forEach(function(elm, inx){
    	setTabTitle(elm.tabID, elm.tabLabel);
    });

    setTabTitle(tabArr[inx].tabID, tabArr[inx].tabLabel+' 선택됨');
};

