            }
            htmlStr.push("<ul id='" + this.id + "_ul' class='w2multiselect_acc_ul' role='listbox' " + (this.options.accessibility ? " " + tabIndexStr + " " + titleStr + " " + ariaLabelStr : "") + ">");
            for (var i = 0; i < this.itemArr.length; i++) {
