                htmlStr.push("<div style='overflow:visible;position:relative;height:0px'>"); //IE6 7에서 div아래에 table width:100%가 있으면 div의 스크롤까지 table이 들어감 따라서 tabled을 div로 한번더 감싸줌
            }
            htmlStr.push("<table id='" + this.id + "_table' class='w2multiselect_table' role='listbox' " + paddingStr + ">");
