};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * gridView adaptive="crosstab" 적용 후 세로 정렬시 scope row/col 자동 변경 WESD-1764
 */
WebSquare.uiplugin.gridView.prototype.addAdaptive = function() {
    try {
        var adaptive = this.options.adaptive;
        var adaptiveClass;
        if (adaptive == "crosstab") {
            adaptiveClass = this.hasFooter ? "w2grid_adaptive_crosstab w2grid_adaptive_crosstab_footer" : "w2grid_adaptive_crosstab";
        }
        for (var keys in this.hideThresholdObj) {
            var hideThreshold = parseInt(this.hideThresholdObj[keys]);
            if (hideThreshold >= WebSquare.util._getBrowserWidth()) {
                this.setColumnVisible(keys, false);
            } else {
                this.setColumnVisible(keys, true);
            }
        }
        if (!this.hasClass(adaptiveClass)) {
            this.oldOptions["visibleRowNum"] = this.options.visibleRowNum;
            this.options.visibleRowNum = "all";
            this.adjustDraw(this.lastIndex);
            this.addClass(adaptiveClass);
            this.setAdaptiveGridBodyHeight();
            this.setAdaptiveGridHeaderHeight();
            if (this.hasSubtotal) {
                this.setAdaptiveGridSubtotalHeight();
            }
            if (this.options.autoScope) {
                this._setScope(true);
            }
            for (var i = this.defaultColCnt; i < this.hiddenList.length; i++) {
                if (this.hiddenList[i] == true) {
                    this.setAdaptiveColumnVisible(i, false);
                }
            }
            if (!this.event.hasEvent(this.id + "_body_tbody", "onscroll")) {
                this.event.addListener(this.getElementById(this.id + "_body_tbody"), "onscroll", this.event.bindAsEventListener(this, this.tbodyMoveXScroll));
            }
        }
        if (this.options.adaptiveSlideHeader) {
            var headTable = this.getElementById(this.id + "_head_table");
            var bodyTable = this.getElementById(this.id + "_body_tbody");
            if (!this.slideHeadObj) {
                this.slideHeadObj = {};
                this.slideHeadObj.render = headTable;
                this.slideHeadObj.headTableWidth = headTable.offsetWidth;
                this.slideHeadObj.hidden = false;
            }
            if (this.slideHeadObj.render.style.position != "absolute") { 
                if (bodyTable.scrollWidth > bodyTable.clientWidth + this.slideHeadObj.headTableWidth) { 
                    this.slideHeadObj.render.style.position = "absolute";
                    if (!this.options.adaptiveSlideHeaderOnScroll) {
                        $(this.slideHeadObj.render.firstChild).animate({
                            width: "hide"
                        });
                        this.slideHeadObj.hidden = true;
                    }
                }
            } else { 
                if (bodyTable.scrollWidth == bodyTable.clientWidth) {
                    WebSquare.util.clearTimeout(this.id + "_adaptiveSlideHeader");
                    this.slideHeadObj.render.style.position = "";
                    this.slideHeadObj.render.firstChild.style.display = "";
                    this.slideHeadObj.hidden = false;
                }
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * gridView adaptive="crosstab" 적용 후 세로 정렬시 scope row/col 자동 변경 WESD-1764
 */
WebSquare.uiplugin.gridView.prototype.removeAdaptive = function() {
    try {
        var adaptive = this.options.adaptive;
        var adaptiveClass;
        if (adaptive == "crosstab") {
            adaptiveClass = this.hasFooter ? "w2grid_adaptive_crosstab w2grid_adaptive_crosstab_footer" : "w2grid_adaptive_crosstab";
        }
        if (this.options.adaptiveSlideHeader) { 
            if (this.slideHeadObj) {
                this.slideHeadObj.render.style.position = "";
                this.slideHeadObj.render.firstChild.style.display = "";
                this.slideHeadObj.hidden = false;
            }
        }
        if (this.hasClass(adaptiveClass)) {
            this.options.visibleRowNum = this.oldOptions["visibleRowNum"];
            for (var i = this.defaultColCnt; i < this.hiddenList.length; i++) {
                if (this.hiddenList[i] == true) {
                    this.setAdaptiveColumnVisible(i, true);
                }
            }
            this.removeClass(adaptiveClass);
            this.removeAdaptiveGridBodyHeight();
            this.removeAdaptiveGridHeaderHeight();
            if (this.hasSubtotal) {
                this.removeAdaptiveGridSubtotalHeight();
            }
            if (this.options.autoScope) {
                this._setScope(false);
            }
            if (this.options.visibleRowNum != "") {
                this.focusedCell = []; 
                this.initializeDrawController();
                this.dataRowList = [];
                this.drawedRowLength = 0;
                this.lastDisplayedRow = -1;
                var bodyTbody = this.getElementById(this.id + "_body_tbody");
                while (bodyTbody.firstChild) {
                    bodyTbody.removeChild(bodyTbody.firstChild);
                }
                if (this.options.senseReader) {
                    for (var i = 0; i < this.adaptiveEmbeddedInputIdList.length; i++) {
                        delete this.dom[this.adaptiveEmbeddedInputIdList[i]];
                    }
                    this.adaptiveEmbeddedInputIdList = [];
                }
                this.drawDataTable(0);
            }
            this.event.removeEvent(this.id + "_body_tbody", "onscroll");
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * gridView adaptive="crosstab" 적용 후 세로 정렬시 scope row/col 자동 변경 WESD-1764
 */
WebSquare.uiplugin.gridView.prototype._setScope = function(isAdaptive) {
    try {
        var headerElements = document.getElementById(this.id).getElementsByClassName(this.options.headerTdClass);
        for (var i = 0; i < headerElements.length; i++) {
            var headerElement = headerElements[i];
            var scope = headerElement.getAttribute("scope");
            if (isAdaptive && scope === "col") { 
                headerElement.setAttribute("scope", "row");
            } else if (!isAdaptive && scope == "row") { 
                headerElement.setAttribute("scope", "col");
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 그리드뷰 포커스 이동 문제 수정 WESD-1767
 */
WebSquare.uiplugin.gridView.prototype.getLeftMostFocusableColIndex = function(rowIndex) {
    var colIndexArr = this.colIndexInfo.body.colInfo.colIndexArr;
    var targetCol = null;
    if (rowIndex >= this.dataList.getRowCount() || rowIndex < 0) {
        return targetCol;
    }

    for (var i = 0; i < colIndexArr.length - this.defaultColCnt; i++) {
        var isNonEditable = false;
        var cellInfo = this.getCellInfo(i);

        if (this.options.readOnlyTabIgnore) {
            isNonEditable = this.___getEditReadOnly(rowIndex, i);
        }
        if (this.options.ignoreNonEditableCell || this.options.senseReader) {
            isNonEditable = this.___getEditReadOnly(rowIndex, i) || this._getEditDisabled(rowIndex, i);
        }

        if (this.options.senseReader && cellInfo.options.inputType == "radio" && this.getCellData(rowIndex, i) != cellInfo.options.trueValue) {
            var checkedArr = this.getCheckedIndex(cellInfo.colID);
            if (checkedArr) {
                if(checkedArr[0] === rowIndex) {
                    isNonEditable = false;
                } else {
                    isNonEditable = true;
                }
            } else {
                if (0 != rowIndex) {
                    isNonEditable = true;
                }
            }
        }
        var customCellInfo;
        if (cellInfo.options.inputType == "custom") {
            customCellInfo = cellInfo.cellManagerHashByRowIndex[this.dataList.getRealRowIndex(rowIndex)];
        }
        if (this.options.senseReader && this.___getEditReadOnly(rowIndex, i) || this._getEditDisabled(rowIndex, i)) {
            if (cellInfo.options.inputType == "user" || cellInfo.options.inputType == "link" || (customCellInfo && customCellInfo.options.inputType == "link")) {
                var targetTd = this.data_td_list[i + ((rowIndex - this.rowIndex) * this.oneRowDataLength)];
                if (targetTd) {
                    var link = targetTd.getElementsByTagName("a");
                    if (link.length == 0) {
                        link = targetTd.getElementsByTagName("input");
                    }
                    if (link.length != 0) {
                        isNonEditable = false;
                    }
                } else {
                    isNonEditable = false;
                }
            }
        }
        if (this.isColMerge && this.cellInfoHash[this.tdIdList[i]].options.colMerge) {
            var beforeValue = this.dataList.getCellData(rowIndex - 1, i);
            var upperCheck = this.upperGroupingTest(rowIndex, i);
            var nowValue = this.dataList.getCellData(rowIndex, i);
            if (beforeValue == nowValue && upperCheck) {
                isNonEditable = true;
            }
        }

        if (this.hiddenRowObj.length > 0 && !this._getRowVisible(rowIndex)) {
            isNonEditable = true;
        }

        if (this.getMerged(rowIndex, i) && !this.cellMergeInfo[rowIndex + "_" + i]) {
            isNonEditable = true;
        }
        if (!this.hiddenList[i] && !isNonEditable) {
            targetCol = i;
            break;
        }
    }
    return targetCol;
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 그리드뷰 포커스 이동 문제 수정 WESD-1767
