 *   아이템요소 li의 text-align: 를 text-align:center로 변경
 *   아이템테이블 div aria-expanded 제거
 */
WebSquare.uiplugin.autoComplete.prototype._openSubLayer = function(obj) {
    try {
        if (!obj) {
            obj = {};
        }
        var select = (obj.select === undefined) ? true : obj.select;
        this.setSubLayer();

        if (!this.isOpen) {
            if (this.itemArr.length == 0) {
                return;
            }
            this.itemTable.show();
            this.addClass("w2autoComplete_open");

            if (this.options.renderType === "native" || this.options.renderType == "input") {
                var ariaControlInput = this.dom.input;
                if (ariaControlInput) {
                    ariaControlInput.setAttribute("aria-expanded", "true");
                }
                var ariaControlArrow = this.dom.imgArrow;
                if (ariaControlArrow) {
                    ariaControlArrow.setAttribute("aria-expanded", "true");
                }
            }
            if (this.options.renderType == "input" && this.itemTable.render.firstChild) {
                this.itemTable.render.firstChild.setAttribute("aria-label", "자동완성");
            }
            if (this.options.renderType != "input") {
                this.itemTable.render.setAttribute("aria-expanded", "true");
            }            
            this.setItemTable();
            if (this.options.wmode == true) {
                WebSquare.getBody().showWModeFrame(this.getPluginName(), this.itemTable.render);
            }

            if (!WebSquare.util.isMobile() && (!this.options.editable || this.options.disableEdit || (!this.editmode && this.options.findItemFirstKey))) {
                this.itemTable.focus();
            }

            if (this.selectedIndex != -1 && select) {
                var checkIndex = this.selectedIndex;
                if (checkIndex == 0 && (this.itemTable._getCellDisabled(checkIndex) || this.itemTable._getCellHidden(checkIndex))) {
                    checkIndex++;
                }
                this.itemTable.setSelectedIndex(checkIndex);
            }

            if (this.options.animation != "") {
                var direction = "down";
                var top = WebSquare.style.getAbsoluteTop(this.render);
                var scrollTop = document.body.scrollTop;      
                if (scrollTop < document.documentElement.scrollTop) {
                    scrollTop = document.documentElement.scrollTop;
                }
                var upSpace = top - scrollTop;
                var downSpace = document.documentElement.clientHeight - (upSpace + this.render.offsetHeight);
                var subHeight = this.itemTable.render.offsetHeight;
                if (downSpace < subHeight && upSpace > subHeight) {
                    direction = "up";
                }

                if (this.options.animation.toLowerCase() == "show") {
                    $("#" + this.itemTable.id).hide().show("fast");
                } else if (this.options.animation.toLowerCase() == "fadein") {
                    $("#" + this.itemTable.id).hide().fadeIn("slow");
                } else if (this.options.animation.toLowerCase() == "slidedown") {
                    if (direction == "down") {
                        $("#" + this.itemTable.id).hide().slideDown("fast");
                    } 
                }
            }

            if (this.editmode) {
                if (typeof this.dom.input != "undefined" && this.dom.input != null) {
                    this.setfFocus();
                }
            } 
            this.isOpen = true;

            if (typeof this.customLabelFormatter === 'function') {
                this._setLabel(this.selectedIndex);
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

