/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * autoComplete talkback 에서 읽기 WESD-1783
 */
WebSquare.uiplugin.autoComplete.prototype.setItemTable = function() {
    try {
        var trs;
        var tds;
        if (this.options.renderType === "native" || this.options.renderType == "input") {
            trs = this.itemTable.render.getElementsByTagName("li");
            tds = this.itemTable.render.getElementsByTagName("li");
        } else {
            trs = this.itemTable.render.getElementsByTagName("tr");
            tds = this.itemTable.render.getElementsByTagName("td");
        }

        if (trs.length !== this.itemArr.length 
            || this.viewArr.length !== this.itemArr.length
            || this._itemTableRedraw
            ) {
            this._itemTableRedraw = false;
            this.itemTable.setItemArr(this.viewArr);    
        }

        var offsetWidth = this.render.offsetWidth;
        var tdHeight;

        if (tds && tds.length > 0) {
            tdHeight = tds[0].offsetHeight;    
            var itemCount = this.editmode ? this._getVisibleItemCountViewArr() : this.getVisibleItemCount();
            var rows = Math.min(itemCount, this.options.visibleRowNum);           

            if (WebSquare.core.browserCheck.moz && tdHeight < 34 && rows == 1) {
                tdHeight = 34;
            }

            tdHeight = rows * tdHeight;    

            if (this.options.visibleColumn) { 
                for (var i = 0; i < rows; i++) {
                    var height = tds[i].offsetHeight;
                    if (height > 0) {
                        break;
                    }
                }
                tdHeight = rows * height;
            }

            this.itemTable.setStyle("height", tdHeight + "px");      
        }

        if (this.options.submenuSize == "fixed" || parseInt(offsetWidth) >= parseInt(this.itemTable.render.offsetWidth)) {
            this.itemTable.setStyle("width", (offsetWidth - 2) + "px");    
            if (this.itemTable.render.offsetHeight >= this.itemTable.render.scrollHeight) {
                this.itemTable.render.firstChild.style.width = (offsetWidth) + "px";
            } else {
                this.itemTable.render.firstChild.style.width = (offsetWidth - 17) + "px";
            }
        } else { 
            if (this.itemTable.render.scrollHeight - this.itemTable.render.offsetHeight > 1) { 
                this.itemTable.setStyle("width", (this.itemTable.render.firstChild.offsetWidth + 17) + "px");
            } else { 
                if (this.itemTable.render.firstChild.offsetWidth > offsetWidth) {
                    this.itemTable.setStyle("width", (this.itemTable.render.firstChild.offsetWidth) + "px");
                } else {
                    this.itemTable.render.firstChild.style.width = (offsetWidth) + "px";
                    this.itemTable.setStyle("width", (offsetWidth - 2) + "px"); 
                }
            }
        }

        var direction = this.options.direction;

        if (direction == "auto") {
            var scrollTop = document.body.scrollTop;     
            if (scrollTop < document.documentElement.scrollTop) {
                scrollTop = document.documentElement.scrollTop;
            }
            var upSpace = WebSquare.style.getAbsoluteTop(this.render) - scrollTop;
            var downSpace = document.documentElement.clientHeight - (upSpace + this.render.offsetHeight); 
            var subHeight = this.itemTable.render.offsetHeight; 
            var emptySpace = Math.max(downSpace, upSpace); 

            if (emptySpace < subHeight && tds && tds.length > 0) {
                var newHeight = 0;
                for (var i = 0; i < tds.length; i++) {
                    if (newHeight + tds[i].offsetHeight + 2 > emptySpace) {
                        break;
                    }
                    newHeight += tds[i].offsetHeight;
                }
                this.itemTable.rowCount = i;
                this.itemTable.setStyle("height", newHeight + "px");
                if (emptySpace !== downSpace) {
                    direction = "up";
                }
            } else if (downSpace < subHeight && upSpace > subHeight) {
                direction = "up";
            }
        }
        if (this._itemTableRenderPosition == "component") {
            this._setItemTableComponent(direction, tdHeight);
        } else {
            this._setItemTableBody(direction, tdHeight);
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * autoComplete talkback 에서 읽기 WESD-1783
 */
WebSquare.uiplugin.autoComplete.prototype._setItemTableCommon = function(direction, left, top, tdHeight) {
    try {
        var documentWidth = document.documentElement.clientWidth || document.body.clientWidth || 0;
        var leftAb = WebSquare.style.getAbsoluteLeft(this.render);
        if (documentWidth < (leftAb + this.itemTable.render.offsetWidth)) { 
            var leftAbOver = leftAb + this.render.offsetWidth - this.itemTable.render.offsetWidth;
            if (this._itemTableRenderPosition == "body") {
                left = left + this.render.offsetWidth - this.itemTable.render.offsetWidth;
            }
            if (leftAbOver < 0) {
                if (this._itemTableRenderPosition == "body") {
                    left = WebSquare.style.getAbsoluteLeft(this.render);
                }
                var tableWidth = document.body.offsetWidth - 17 - WebSquare.style.getAbsoluteLeft(this.render);
                this.itemTable.setStyle("width", tableWidth + "px");
                if (this.itemTable.getStyle("overflow-x") != "auto") {
                    tdHeight += 20;
                }
                this.itemTable.setStyle("height", tdHeight + "px");    
                this.itemTable.setStyle("overflow-x", "auto");
            } else {
                this.itemTable.setStyle("overflow-x", "hidden");
            }
        } else {
            var tableWidth = this.itemTable.render.firstChild.offsetWidth; 
            var itemWidth = this.itemTable.render.clientWidth;   
            if ((leftAb + tableWidth) < documentWidth && this.itemTable.getStyle("overflow-x") == "auto") {
                var width = (tableWidth > itemWidth) ? tableWidth : itemWidth;
                tdHeight -= 20;
                this.itemTable.setStyle("height", tdHeight + "px");
                this.itemTable.setStyle("width", width + "px");
                this.itemTable.setStyle("overflow-x", "hidden");
            }
        }

        this.itemTableDirection = direction;      
        this.itemTable.render.style.left = left + "px";
        this.itemTable.render.style.top = top + "px";
        WebSquare.style.adjustZIndex(this.uuid, this.itemTable.uuid, "itemTable");
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

