WebSquare.uiplugin.autoComplete.prototype.handleMousedownEvent = function(e) {
    try {
        if (this.options.editModeEvent === "onfocus") {
            var it = this.event.getTargetIterator(e, this.render);
            while (it.next()) {
                if (it.match("w2autoComplete_col_button")) {
                    if (this.isOpen === true) {
                        this._bOpen = true;
                    }
                    this._skipFind = true;
                    it.stop();
                }
            }
        }
        WebSquare.event.stopPropagation(e);
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

