                                this.setScrollLeft(scrollLeft - (headerOrgWidth - headerWidth));
                            }
                        }
                    }                    
                }
                WebSquare.util.requestAnimationFrame(function() {
                    targetBtn.focus();
                });
                if (this.options.senseReader == true) {
                    this.addGridScroll(0 - this.rowIndex);
                }
            }
        }
    }
    this.noevent = false;
};

