WebSquare.uiplugin.autoComplete.prototype.initialize = function( /*optional*/ element) {
    try {
        this._setSetting = false;
        this.itemTable = null;
        this.gridOptions = {};
        this.gridViewOptions = {};
        this.isOpen = false;
        this.statusSubLayer = false;
        this._itemTableRedraw = true;
        this.supportAutocomplete = false;
        if (this.options.accessibility === true) {
            this.options.renderType = "input";
        }
        if (this.options.emptyItem) {
            this.options.noResult = "clear";
            this.noResult = "clear";
        } else {
            this.noResult = (this.options.noResult === "previous" || this.options.noResult === "clear" || this.options.noResult === "noEnd" || this.options.noResult === "useData" || this.options.noResult === "first") ? this.options.noResult : "previous";
        }

        if (this.options.tooltip && this.options.tooltipDisplay) {
            this.options.tooltip = "";
        }

        //input selectbox
        this.editable = this.options.editable;
        this.search = this.options.search;
        this.orgSearchArr = [];

        this.selectedItem = {
            text: "",
            value: "",
            orgLabel: ""
        };
        this.selectedGridRowObj = {};
        this.selectedGridViewRowObj = {};

        this.viewArr = [];
        this.itemArr = [];
        this.dummyItemArr = []; 
        this.dummyGridItemArr = [];
        this.mytime = null;
        this.hideTime = null;

        this.tooltip = null; // tooltip
        this.timeShowTooltip = null;
        this.timeHideTooltip = null;

        this.editmode = this.options.editmode;
        this.findkeymode = false;

        //mozilla
        this.mozTrickBuffer = "";
        this.trickBuffer = "";
        this.findStop = false;

        this.skipMatch = false;
        this.defaultAllOptionLabel = WebSquare.language.getMessage("AutoComplete_all");
        if (element && element.getAttribute("chooseOptionLabel") == "$blank") {
            this.defaultChooseOptionLabel = "";
        } else {
            this.defaultChooseOptionLabel = WebSquare.language.getMessage("AutoComplete_choose");
        }

        this._initDisplayMode();
        this.dataurl = this.options.dataurl;

        this.dataurl = this.options.dataurl;
        this.selectedIndex = -1;
        this.selectedAllIndex = -1;
        this.cursorIndex = -1;
        this.showRowIndex = 0;
        this.displayCount = 0;

        if (this.options.interactionMode && !(this.options.submission || this.options.submissionFunc)) {
            this.options.interactionMode = false;
        }

        this._showItemTableByFocus = false;
        if (this.options.editModeEvent === "onfocus" && this.options.showItemTableByFocus) {
            this._showItemTableByFocus = true;
        }

        this.interactionMode = this.options.interactionMode;

        if (element) {
            var choices = WebSquare.xml.findNode(element, "*['" + "choices" + "'=local-name()]['" + WebSquare.core._XML_NAMESPACE.W2 + "'=namespace-uri()]");
            if (choices) {
                // itemset
                //var itemsetNode = WebSquare.xml.findNode(choices, "w2:gridItemset");
                var itemsetNode = WebSquare.xml.findNode(choices, "*['" + "gridItemset" + "'=local-name()]['" + WebSquare.core._XML_NAMESPACE.W2 + "'=namespace-uri()]");
                if (itemsetNode == null) {
                    itemsetNode = WebSquare.xml.findNode(choices, "*['" + "gridViewItemset" + "'=local-name()]['" + WebSquare.core._XML_NAMESPACE.W2 + "'=namespace-uri()]");
                }

                if (itemsetNode && itemsetNode.nodeName == "w2:gridItemset") {
                    this.itemTableMode = "grid";
                } else if (itemsetNode && itemsetNode.nodeName == "w2:gridViewItemset") {
                    this.itemTableMode = "gridView";
                }
            } else if (this.options.itemTableType == "gridViewItemset") {
                this.itemTableMode = "gridView";
            }

            if (this.itemTableMode == "grid") {
                this.initializeGridItemArr(element);
            } else if (this.itemTableMode == "gridView") {
                this.initializeGridViewItemArr(element);
            } else {
                this.initializeItemArr(element);
            }
            this.autoFinder = element.nodeName == "w2:autoFinder" ? true : false;

            if (this.autoFinder) {
                this.display_path = this.options.display_path;
                if (typeof this.display_path != "undefined") {
                    this.display_path = this.display_path.replace(/^\s\s*/, '').replace(/\s\s*$/, '');
                    var path = this.display_path.split(" ");
                    var nodeset = path[0];
                    var label = path[1];
                    var value = path[2];
                    this.setItemSet(nodeset, label, value);
                    this.buildItemArr();
                }
            } else {
                if (this.itemTableMode != "grid" && this.itemTableMode != "gridView") {
                    this.itemsetObj = WebSquare.WebSquareparser.parseItemset(element);
                }
            }
        }
        this.validator = new WebSquare.validator.validateInvoker(this.id, this.options);
        this.displayFormatter = null;
        this.onchangeFlag = false;
        this.otherClicked = false;
        if (this.options.autocomplete) {
            if (WebSquare.uiplugin.autoComplete.autocomplete) {
                this.supportAutocomplete = true;
            }
        }
        if (this.options.customLabelFormatter) {
            this.customLabelFormatter = WebSquare.util.getGlobalFunction(this.options.customLabelFormatter, this.scope_id);
