WebSquare.uiplugin.itemTable.prototype.setSelectedIndex = function(idx, options) {
    if (!this.dom.tds || this.dom.tds.length === 0) return;
    var options = options || {};
    idx = (idx < 0) ? 0 : (idx >= this.dom.tds.length) ? this.dom.tds.length - 1 : idx;
    this.removeClass(this.selectedCell, this.options.w2table_col_over);
    if (this.options.parentPluginName === "autoComplete_input" && this.selectedCell) {
        this.selectedCell.setAttribute("aria-selected","false");
    }
    this.selectedCell = this.dom.tds[idx];
    this.addClass(this.selectedCell, this.options.w2table_col_over);
    if (this.options.parentPluginName === "autoComplete_input") {
        this.selectedCell.setAttribute("aria-selected","true");
    }
    if (this.options.tableRender == "ul" && (this.options.parentPluginName !== "checkcombobox" && this.options.parentPluginName !== "autoComplete_input")) {
        if (this.selectedCell.childNodes[0]) {
            this.selectedCell.childNodes[0].focus();
        }
    }
    if (this.selectedCell.offsetTop > this.render.offsetHeight / 2) {
        var rowCount = Math.min(this.getItemCount(), this.rowCount);
        var topPositionedCell = this.dom.tds[idx - parseInt(rowCount / 2)];
        this.render.scrollTop = topPositionedCell.offsetTop;
    } else {
        this.render.scrollTop = 0;
    }
    if (this.onchangeFunc && options.noChangeFunc !== true) {
        this.onchangeFunc(idx);
    }
};
