                var downSpace = document.documentElement.clientHeight - (upSpace + this.render.offsetHeight);
                var subHeight = this.itemTable.render.offsetHeight;
                if (downSpace < subHeight && upSpace > subHeight) {
                    direction = "up";
                }

                if (this.options.animation.toLowerCase() == "show") {
                    $("#" + this.itemTable.id).hide().show("fast");
                } else if (this.options.animation.toLowerCase() == "fadein") {
                    $("#" + this.itemTable.id).hide().fadeIn("slow");
                } else if (this.options.animation.toLowerCase() == "slidedown") {
                    if (direction == "down") {
                        $("#" + this.itemTable.id).hide().slideDown("fast");
                    } 
                }
            }

            if (this.editmode) {
                if (typeof this.dom.input != "undefined" && this.dom.input != null) {
                    this.setfFocus();
                }
            } 
            this.isOpen = true;

            if (typeof this.customLabelFormatter === 'function') {
                this._setLabel(this.selectedIndex);
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
WebSquare.uiplugin.autoComplete.prototype._closeSubLayer = function() {
    try {
        if (this.isOpen && this.itemTable != null) {
            this.itemTable.hide();
            this.removeClass("w2autoComplete_open");
            if (this.options.renderType != "input") {
                this.itemTable.render.setAttribute("aria-expanded", "false");
            }

            if (this.options.renderType === "native" || this.options.renderType == "input") {
                var ariaControlInput = this.dom.input;
                if (ariaControlInput) {
                    ariaControlInput.setAttribute("aria-expanded", "false");
                }
                var ariaControlArrow = this.dom.imgArrow;
                if (ariaControlArrow) {
                    ariaControlArrow.setAttribute("aria-expanded", "false");
                }                
            }
            if (this.options.wmode == true) {
                WebSquare.getBody().hideWModeFrame(this.getPluginName(), this.itemTable.id);
            }

            this.isOpen = false;
            if (typeof this.customLabelFormatter === 'function') {
                this._setLabel(this.selectedIndex);
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
