//WESD-1789 [대법원]웹표준_gridView
WebSquare.uiplugin.gridView.prototype.applyCellStyleOptions = function(rowIndex, colIndex, removedFocusedCell, ignoreFocusMode) {
    try {
        var trIndex = this._getTrIndex(rowIndex);
        var td = this._getTdElem(rowIndex, colIndex);
        if (td) {
            var styleArr = [];
            var isFocusedCell = false;

            var col_index;
            var col_id;
            if (typeof colIndex == "number") {
                col_index = colIndex;
                col_id = this.cellIdList[colIndex];
            } else {
