                            WebSquare.event.preventDefault(e);
                        } else {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    }
                } else {
                    if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["nextTabID"] != null) {
                        if (this.options.nextTabByKeyDown == "true") {
                            var tabObj = WebSquare.util.getNextTabbableComp(this.id);
                            if (tabObj) {
                                this.tabOrderMoveStart = false;
