                            }
                            WebSquare.event.preventDefault(e);
                        } else {
                            this.tabOrderMoveStart = true;
                            WebSquare.event.preventDefault(e);
                        }
                    }
                }
            }
        } else if (keyCode == 8) {
            var android5 = false;
            android5 = WebSquare.core.browserCheck.android && WebSquare.core.browserVersion() >= 5.0;
            if (this.options.applyFormat == "all") {
                if (!android5) {
                    var value = this.render.value;
                    var pos = WebSquare.text.getCaretPos(this.render);
                    var removedChar = value.substring(pos - 1, pos);
                    var selection = WebSquare.text.getSelection(this.render);
                    if ((this.options.dataType === "float"
                            || (this.options.dataType === "bigDecimal" && this.useBigDecimalFloat)
                            || this.options.dataType === "euro"
                            || this.options.dataType === "tenge"
                            || this.options.dataType === "rupee"
                        ) 
                        && removedChar === this.options.decimalDelimiter) {
                        WebSquare.event.preventDefault(e);
                        this.render.value = value.slice(0, pos - 1) + value.slice(pos, value.length);
                        WebSquare.text.setCaretPos(this.render, this.render.value.length + 1);
                    } else if (isNaN(Number(removedChar)) && selection.start == selection.end) {
                        var prevRemovedChar = value.substring(pos - 2, pos - 1);
                        if ((!isNaN(Number(prevRemovedChar)) && prevRemovedChar != ""
                            || this._getMaskFormat() && this.options.dataType == "text"  && prevRemovedChar != ""
                            && (new RegExp("[" + this.options.allowChar + "]")).test(prevRemovedChar))
                            && (new RegExp("[^" + this.options.allowChar + "]")).test(removedChar)) {
                            this.render.value = value.slice(0, pos - 2) + value.slice(pos - 1, value.length);
                            WebSquare.text.setCaretPos(this.render, pos - 1);
                        }
                    }
                }
            }
        } else {
            if (this.options.preventCopyPaste && WebSquare.util.isOpera()) {
                if (e.ctrlKey && (e.keyCode === 88 || e.keyCode === 67 || e.keyCode === 86)) {
                    WebSquare.event.stopEvent(e);
                    return;
                }
            } else if (this.options.autoFocus) {
                this._keyDownStart = true;
            }
        }
        if (this.options.adjustMaxLength && this.options.dataType == "number" && /* guard option */ !this.options.useMaxLength) {
            var pos = WebSquare.text.getCaretPos(this.render);
            var curValue = this._getValue();
            this.adjustMaxLength(this.render.value);
            if (pos == 0 && curValue.length == this.options.maxlength) {
                if (keyCode == 189 || keyCode == 109) { // - key
                    this.render.value = "-" + curValue;
                } else if ((keyCode == 187 && e.shiftKey) || keyCode == 107) {
