        if (WebSquare.util.isOpera()) {
            this.checkMaxByteLength({
                "skipFireEvent" : true
            });
        }
        this.beforeEditValue = this._getValue();
        if (this.options.maxByteLength && this.options.checkMaxByteOnInput) {
            var selection = WebSquare.text.getSelection(this.render);
            this.inputTextInfo.prevSelectionStart = selection.start;
            this.inputTextInfo.prevValue = this.render.value;
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

// setCellClass 로 clsss 적용시 ,그리드 소트를 하면 class 는 현위치에 머물러있는 버그 패치 2024.12.03
WebSquare.uiplugin.gridView.prototype.completiveDrawData = function(startPoint, options) {
    try {
        if (!this.autofitDone && this.options.autoFit) {
            this._setAutoFit();
        }
        var dataLen = this.getDataLength();
        var startPoint = startPoint || 0;
        if (this.hiddenRowObj.init === true) {
            startPoint = 0;
        }
        var rowIndex = this.rowIndex;
        var lastIndex = startPoint - 1;
        var dataLayerHeight = this.dataLayerHeight;
        var bCellHidden = this.hiddenCellObj.length > 0;
        if (dataLen > 0) {
            if (this.hiddenRowObj.init === true) {
                this._applyRowVisible({
                    "applyStyle" : true,
                    "drawRow" : true
                });
                lastIndex = this.lastIndex;
            } else {
                var isFixedHeight = this.options.initFixedHeightByRowNum > -1;
                if (startPoint == 0 && rowIndex != this.lastTopRowIndex && this.options.visibleRowNum === "") {
                    this.drawSubtotalRow(0, rowIndex - 1);
                }
                var visibleRowLength = this.drawedRowLength;
                if (this._dynamicVisibleRowNum > 0) {
                    visibleRowLength = this._dynamicVisibleRowNum;
                }
                if (isFixedHeight && this.hasSubtotal && this.drawedSubtotal) {
                    visibleRowLength -= this.drawedSubtotal.drawedRowLength;
                }

                var drawOptions;
                if (isFixedHeight) {
                    drawOptions = {
                        "skipSubtotal" : true
                    };
                }
                for (var i = startPoint; i < visibleRowLength && (i + rowIndex) < dataLen; i++) {
                    var subtotalCnt = 0;
                    var drawRowIndex = i + this.rowIndex;
                    if (this.options.fixedRow > 0 && this.options.fixedRow > i) {
                        this.fastDrawRowData(i, i, drawOptions);
                    } else {
                        this.fastDrawRowData(i, drawRowIndex, drawOptions);
                    }
                    lastIndex = i;
                    if (isFixedHeight && this.hasSubtotal && i < visibleRowLength - 1) {
                        var subtotalCnt = this.drawSubtotalRow(i + 1, drawRowIndex, {
                            "maxCount" : visibleRowLength - i - 1
                        });
                        visibleRowLength -= subtotalCnt;
                    }
                }
                if (isFixedHeight && this.hasSubtotal && visibleRowLength > lastIndex + 1) {
                    visibleRowLength -= this.drawSubtotalRow(0, rowIndex - 1, {
                        "maxCount" : visibleRowLength - lastIndex - 1
                    });
                }
                if (this.options.rowResize && this.rowResized) {
                    var headerHeight = this.getElementById(this.id + "_head_table").offsetHeight;
                    var tbodyHeight = dataLayerHeight - headerHeight;
                    var rowsHeight = 0;
                    for (var i = 0; i < this.dataRowList.length; i++) {
                        if (rowsHeight < tbodyHeight) {
                            rowsHeight += this.dataRowList[i].offsetHeight;
                        } else {
                            lastIndex = i;
                            break;
                        }
                    }
                }
                if (this.options.drawType == "native" && startPoint != 0) {
                    lastIndex = this.getDataLength() - 1;
                }
                if (bCellHidden) {
                    for (var i = lastIndex + 1; i < this.drawedRowLength + this.hiddenRowObj.extraRow; i++) {
                        this._setRowDisplay(i, "none");
                    }
                    for (var i = 0; i <= lastIndex; i++) {
                        this._setRowDisplay(i, "");
                    }
                } else {
                    for (var i = lastIndex + 1; i <= this.lastDisplayedRow + this.hiddenRowObj.extraRow; i++) {
                        this._setRowDisplay(i, "none");
                    }
                    for (var i = this.lastDisplayedRow + 1; i <= lastIndex; i++) {
                        this._setRowDisplay(i, "");
                    }
                }
                var applyStyle = bCellHidden || (this.options.visibleRowNum === "" && this.options.initFixedHeightByRowNum == -1) || this.options.accessibility;
                if (applyStyle) {
                    var styleIndex = 0;
                    var backgroundColorMode = this.options.backgroundColorMode.toLowerCase();
                    if (backgroundColorMode === "always" || backgroundColorMode === "full") {
                        styleIndex = startPoint;
                    }
                    if (this.defaultColCnt) {
                        for (var i = 0; i < this.dataRowList.length; i++) {
                            this.removeRowOverStyle(this.dataRowList[i], true);
                        }
                    }
                    for (var i = styleIndex; i <= lastIndex; i++) {
                        if (this.options.fixedRow > 0 && this.options.fixedRow > i) {
                            this.applyRowStyleOptions(i);
                        } else {
                            this.applyRowStyleOptions(rowIndex + i);
                        }
                    }
                    if (this.options.autoResizeEmbeddedInput && this.firstEmbeddedInputResize) {
                        this.setAutoResizeEmbeddedInput();
                        this.firstEmbeddedInputResize = false;
                    }
                }
                this.lastDisplayedRow = lastIndex;
                if (applyStyle && this.options.visibleRowNum !== "all" && this.options.drawType !== "native") {
                    lastIndex = this.cutGridBottom(lastIndex, options);
                }
                if (this.options.drawType === "native") {
                    this.lastIndex = lastIndex;
                }
            }

            for (var i = 0; i <= lastIndex; i++) {
                if (this.options.fixedRow > 0 && this.options.fixedRow > i) {
                    this.setEvenOddBackground(i, i);
                } else {
                    this.setEvenOddBackground(i, rowIndex + i);
                }
            }

            if (this.options.lastFixedRow > 0) {
                for (var i = 0; i < this.options.lastFixedRow; i++) {
                    if (this.options.lastFixedRowStartIndex > 0) {
                        this.fastDrawRowData(lastIndex - i, this.options.lastFixedRowStartIndex + 1 - i);
                        if (applyStyle) {
                            this.applyRowStyleOptions(lastIndex - i);
                        }
                        this.setEvenOddBackground(lastIndex - i, this.options.lastFixedRowStartIndex + 1 - i);
                    } else {
                        this.fastDrawRowData(lastIndex - i, dataLen - 1 - i);
                        if (applyStyle) {
                            this.applyRowStyleOptions(lastIndex - i);
                        }
                        this.setEvenOddBackground(lastIndex - i, dataLen - 1 - i);
                    }
                }
            }

            if (this.hiddenRowObj.init !== true && !bCellHidden) {
                var lastVisibleIndex = this._getVisibleLastIndex(lastIndex + 1);
                if (lastIndex + 1 < this.drawedRowLength) {
                    this._setRowDisplay(lastVisibleIndex, "");
                    this.setEvenOddBackground(lastVisibleIndex, rowIndex + lastVisibleIndex);
                    this.applyRowStyleOptions(rowIndex + lastVisibleIndex);
                    if (this.options.showLastRow && !this.hasSubtotal) {
                        if (this.getDataLength() <= rowIndex + lastVisibleIndex) {
                            this._setRowDisplay(lastVisibleIndex, "none");    
                        }
                    } else {
                        this._setRowDisplay(lastVisibleIndex, "none");
                    }
                }
            }

        } else {
            var delta = (this.options.showLastRow && !this.hasSubtotal) ? 1 : 0;
            var lastDisplayedRow = this.lastDisplayedRow + delta;
            if (this.hiddenRowObj.init === true) {
                lastDisplayedRow = this.drawedRowLength + this.hiddenRowObj.extraRow - 1;
            }
            for (var i = 0; i <= lastDisplayedRow; i++) {
                this._setRowDisplay(i, "none");
            }
            lastIndex = this.lastDisplayedRow = -1;
        }
        if (this.hideDataLayer) {
            this.hideDataLayer.style.display = "none";
        }

        if (this.focusedCell.length > 0 && !this.editedCell) {
            var targetRowIndex = this.focusedCell[this.focusedCell.length - 1].focusedRowIndex - this.rowIndex;
            var targetColIndex = this.focusedCell[this.focusedCell.length - 1].focusedColIndex;
            if (0 <= targetRowIndex && targetRowIndex <= lastIndex) {
                var td;
                if (this.options.focusDefaultColumn && targetColIndex < 0 && this.defaultColCnt && (this.options.focusMode === "row" || this.options.focusMode === "both")) {
                    td = this.all_data_td_list[this.defaultColCnt + targetColIndex + targetRowIndex * (this.oneRowDataLength + this.defaultColCnt)];
                } else {
                    td = this.data_td_list[targetColIndex + targetRowIndex * this.oneRowDataLength];
                }
                if (td) {
                    this.applyFocusedCellIn(td);
                }
            }
        }

        var isFullView1 = WebSquare.BootLoader.fullViewed || false;
        var isFullView2 = WebSquare.util.fullViewed || false;
        if (!isFullView1 && !isFullView2) {
            if (this.options.adaptive == "crosstab" && this.hasClass("w2grid_adaptive_crosstab")) {
                if (this.hasSubtotal) {
                    this.setAdaptiveGridSubtotalHeight();
                }

                for (var i = this.defaultColCnt; i < this.hiddenList.length; i++) {
                    if (this.hiddenList[i] == true) {
                        this.setAdaptiveColumnVisible(i, false);
                    }
                }
            }
        }

        return lastIndex;
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

