     * @param {String} cortCd(Options) - 법원코드
     * 
     * @return {Array} - 휴일 목록
     * </pre>
     */
    var loadHldyLst = function(cortCd) {
        var _self = this;

        var isExistsMain = scglblo.$_h._isExistsMainDataClct(scglblo.$_h._getHldyDataId());

        if(! isExistsMain) {
            com.executeAjax({
                action: scscrno.$_h._getSystmCtxtPathUrl('/scframe/lib/scdate/list.on'),
                requestData: JSON.stringify({
                    cortCd: cortCd,
                }),
                mode: "synchronous",
                mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
                success: function(_data) {
                    var list = _data.responseJSON.data.scDateList;
                    var dataLstFieldInf = [];
                    if(list.length > 0) {
                        dataLstFieldInf = Object.keys(list[0]);
                    }

                    var scopeId = scutilo.getSCMain().$p.top().$p.getFrameId();
                    var scopeObj = scutilo.getSCMain().$p.getComponentById(scopeId);
                    var dataLstId = scglblo.$_h._createDataLst.call(_self, {
                        scopeId: scopeObj,
                        dataId: scglblo.$_h._getHldyDataId(),
                        dataLstFieldInf: dataLstFieldInf,
                        getDataFunc: function() {
                            return list;
                        },
                    });
                },
            });
        }
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 시간 유형을 대법원 DB 저장 표준형식 'HHMM'으로 변환해서 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getDbTimeStr("1234");
     * scdateo.getDbTimeStr("12:34");
     * 
     * @param {String} tm - 시간문자열 : HH:MI 혹은 HHMI 포맷의 날짜
     * 
     * @return {String} - DB 시간문자열
     * </pre>
     */
    var getDbTimeStr = function(tm) {
      tm = scutilo.skipSpaces(tm);
      fmt1 = /^\d{2}:\d{2}$/;
      fmt2 = /^\d{4}$/;

      if (!((fmt1.test(tm)) || (fmt2.test(tm)))) return "";
      if (!((tm.length == 4) || (tm.length == 5))) return "";
      if (tm.length == 5) tm = tm.replace(/\:/gi, '');

      return tm;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 일자 유형을 대법원 DB 저장 표준형식 'YYYYMMDD'으로 변환해서 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getDbDateStr("20211023");
     * scdateo.getDbDateStr("2021.10.23");
     * 
     * @param {String} date - 날짜문자열 : YYYYMMDD 혹은 YYYY.MM.DD 포맷의 날짜
     * 
     * @return {String} - DB 날짜문자열
     * </pre>
     */
    var getDbDateStr = function(date) {
        var _self = this;
        var dateNum = _self.$_h._getDateNum(date);
        if (dateNum == "") return "";

        var fmt2 = /^\d{8}$/;
        if (! fmt2.test(dateNum)) return "";
        if (! dateNum.length == 8) return "";
        else return dateNum;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.12.19.   황훈         [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 일자를 지정한 구분자로 포맷팅한 일자로 변환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getFmtDate("20210123"); // 2021.01.23
     * scdateo.getFmtDate("20210123", "-"); // 2021-01-23
     * scdateo.getFmtDate("20210123", "/"); // 2021/01/23
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {String} delimiter - 구분자 : 년월일을 구분할 구분자
     * 
     * @return {String} - 포맷팅된 일자
     * </pre>
     */
    var getFmtDate = function(date, delimiter) {
        var _self = this;
        var dateNum = _self.$_h._getDateNum(date, false);
        if (scutilo.isEmpty(dateNum)) return date;
        if (scutilo.isEmpty(delimiter)) delimiter = _self.$_h.DELIMITER_DATE;
        return dateNum.substr(0,4) + delimiter 
              + dateNum.substr(4,2) + delimiter
              + dateNum.substr(6,2);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 일자를 출력용 일자로 변환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getPrintDate("20210123"); // 2021. 1. 23.
     * scdateo.getPrintDate("20210123", "."); // 2021.1.23.
     * scdateo.getPrintDate("2021/01/23", "."); // 2021.1.23.
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {String} delimiter - 구분자 : 년월일을 구분할 구분자
     * 
     * @return {String} - 출력용 일자
     * </pre>
     */
    var getPrintDate = function(date, delimiter) {
        var _self = this;
        var dateNum = _self.$_h._getDateNum(date);
        if (scutilo.isEmpty(dateNum)) return "";
        if (scutilo.isEmpty(delimiter)) delimiter = _self.$_h.DELIMITER_DATE + " ";
        return scutilo.getAllTrim(dateNum.substr(0,4) + delimiter 
              + parseInt(dateNum.substr(4,2), 10) + delimiter
              + parseInt(dateNum.substr(6,2), 10) + delimiter);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 일자를 YYMMDD 일자로 변환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getShortDate("20211023");
     * scdateo.getShortDate("2021.10.23");
     * scdateo.getShortDate("2021/10/23");
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * 
     * @return {String} - YYMMDD 일자
     * </pre>
     */
    var getShortDate = function(date) {
        var _self = this;
        var dateNum = _self.$_h._getDateNum(date);
        if (dateNum == "") return "";
        return dateNum.substr(2,2) + dateNum.substr(4,2) + dateNum.substr(6,2);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 일자의 토요일 여부를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.isSat("20211113");
     * scdateo.isSat("2021.11.13");
     * scdateo.isSat("2021/11/13");
     * scdateo.isSat("2021. 11. 13. ");
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * 
     * @return {boolean} - 토요일 여부
     * </pre>
     */
    var isSat = function(date) {
        var _self = this;
        var dateNum = _self.$_h._getDateNum(date);

        if (dateNum == "") return false;
        var dateObj = _self.getDateObj(dateNum);

        var weekIdx = dateObj.getDay();

        if (weekIdx == 6) return true;
        return false;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 날짜가 일요일을 포함한 공휴일 여부를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.isHldy("20211023");
     * scdateo.isHldy("2021.10.23");
     * scdateo.isHldy("2021/10/23");
     * scdateo.isHldy("2021. 10. 23. ");
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * 
     * @return {boolean} - 공휴일 여부
     * </pre>
     */
    var isHldy = function(date) {
        var _self = this;

        var dateNum = _self.$_h._getDateNum(date);

        if (dateNum == "") return false;
        var dateObj = _self.getDateObj(dateNum);

        var weekIdx = dateObj.getDay();

        if (weekIdx == 0) return true;
        var tmp = "9999" + dateNum.substr(4,2) + dateNum.substr(6,2);

        var hldyDay = _self.$_h._getHldyDayDataLst();
        var findDay = hldyDay.getMatchedJSON("hldyYmd", tmp, true);
        if (findDay && findDay.length > 0) {
            return true;
        }

        tmp = dateNum.substr(0,4) + dateNum.substr(4,2) + dateNum.substr(6,2);
        findDay = hldyDay.getMatchedJSON("hldyYmd", tmp, true);
        if (findDay && findDay.length > 0) {
            return true;
        }

        return false;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 날짜가 일요일, 토요일을 포함한 공휴일인지 여부를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.isHldyWSat("20211023");
     * scdateo.isHldyWSat("2021.10.23");
     * scdateo.isHldyWSat("2021/10/23");
     * scdateo.isHldyWSat("2021. 10. 23. ");
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * 
     * @return {boolean} - 토요일을 포함한 공휴일인지 여부
     * </pre>
     */
    var isHldyWSat = function(date) {
        var _self = this;

        var dateNum = _self.$_h._getDateNum(date);

        if (dateNum == "") return false;
        var dateObj = _self.getDateObj(dateNum);

        var weekIdx = dateObj.getDay();

        if ( (weekIdx == 0) || (weekIdx == 6) ) return true;

        var tmp = "9999" + dateNum.substr(4,2) + dateNum.substr(6,2);

        var hldyDay = _self.$_h._getHldyDayDataLst();
        var findDay = hldyDay.getMatchedJSON("hldyYmd", tmp, true);
        if (findDay && findDay.length > 0) {
            return true;
        }

        tmp = dateNum.substr(0,4) + dateNum.substr(4,2) + dateNum.substr(6,2);
        findDay = hldyDay.getMatchedJSON("hldyYmd", tmp, true);
        if (findDay && findDay.length > 0) {
            return true;
        }
        return false;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 해당 날짜가 민법161조 기준 공휴일인지 여부를 체크한다.
     * 접수일자가 2008.03.22(포함) 이후이면 토요일을 공휴일로 처리하고,
     * 2008.03.22 이전 접수사건이면 토요일을 평일로 처리한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.isHldy161("20211023", "20211023");
     * scdateo.isHldy161("2021.10.23", "2021.10.23");
     * scdateo.isHldy161("2021/10/23", "2021/10/23");
     * scdateo.isHldy161("2021. 10. 23. ", "2021. 10. 23. ");
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {String} jubDate - 접수일자 : 민법161조 기준이 되는 사건 접수일자(date와 포맷 동일)
     * 
     * @return {boolean} - 주말을 포함한 공휴일인지 여부
     * </pre>
     */
    var isHldy161 = function(date, jubDate) {
        var _self = this;
        var jubdateNum = _self.$_h._getDateNum(jubDate);
        if (jubdateNum == "")
          return _self.isHldy(date);

        if (_self.getDbDateStr(jubdateNum) < _self.$_h.MINBUB161_DATE)
          return _self.isHldy(date);

        return _self.isHldyWSat(date);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 해당 날짜에서 일수만큼 이전의 날짜를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getPrevYmd("20211023", 1);
     * scdateo.getPrevYmd("2021.10.23", 1);
     * scdateo.getPrevYmd("2021/10/23", 1);
     * scdateo.getPrevYmd("2021. 10. 23. ", 1);
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {Number} days - 며칠전 : 이전 날짜를 계산하기 위한 일수(> 0)
     * 
     * @return {String} - 결과 날짜
     * </pre>
     */
    var getPrevYmd = function(date, days) {
        var _self = this;

        if ( days == "0") return date;
        date = _self.$_h._getDateNum(date);

        var dateObj = _self.getDateObj(date);

        dateObj.setDate(dateObj.getDate() - parseInt(days, 10));

        return _self.getDateStr(dateObj);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 해당 날짜에서 일수만큼 이후의 날짜를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getNxtYmd("20211023", 1);
     * scdateo.getNxtYmd("2021.10.23", 1);
     * scdateo.getNxtYmd("2021/10/23", 1);
     * scdateo.getNxtYmd("2021. 10. 23. ", 1);
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {Number} days - 며칠후 : 이후 날짜를 계산하기 위한 일수(> 0)
     * 
     * @return {String} - 결과 날짜
     * </pre>
     */
    var getNxtYmd = function(date, days) {
        var _self = this;

        if ( days == "0") return date;
        date = _self.$_h._getDateNum(date);
        if (date == "") return "";
        var dateObj = _self.getDateObj(date);

        dateObj.setDate(dateObj.getDate()+ parseInt(days, 10));

        return _self.getDateStr(dateObj);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     *  해당 날짜에서 일수만큼 이후 공휴일이면 공휴일 지난 다음 날짜를 반환한다(토요일 포함).
     *  YYYYMMDD 포맷의 날짜를 반환한다.
        단, 결과 일자가 토요일을 포함하여 공휴일인 경우 공휴일이 아닌 다음 날짜를 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getNxtYmdSkipLastHldyWSat("20211023", 1);
     * scdateo.getNxtYmdSkipLastHldyWSat("2021.10.23", 2);
     * scdateo.getNxtYmdSkipLastHldyWSat("2021/10/23", 3);
     * scdateo.getNxtYmdSkipLastHldyWSat("2021. 10. 23. ", 4);
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {Number} days - 기간일수 : 이후 날짜를 계산하기 위한 일수(> 0)
     * 
     * @return {String} - 결과 날짜
     * </pre>
     */
    var getNxtYmdSkipLastHldyWSat = function(date, days) {
        var _self = this;

        var dateStr = _self.$_h._getNxtYmdSkipLastHldy(date, days);
        if (dateStr == "") return "";

        // 토요일인지 확인
        if (_self.isSat(dateStr) == true ) {
            dateStr = _self.getNxtYmd(dateStr,1);
            while ( _self.isHldyWSat(dateStr)   == true ) {
                dateStr = _self.getNxtYmd(dateStr,1);
            }
        }
        return dateStr;
    };

    /*
     * ============= ============ ==========================
