     * 
     * @param {String} psStartDate - 시작날짜 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {String} psEndDate - 종료날짜 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * 
     * @return {Number} - 일수
     * </pre>
     */
    var getDaysBetween = function(psStartDate, psEndDate) {
        var _self = this;

        var dateStart = _self.getDateObj(_self.$_h._getDateNum(psStartDate));
        var dateEnd = _self.getDateObj(_self.$_h._getDateNum(psEndDate));
        return parseInt(Math.floor((dateEnd - dateStart) / 86400000), 10);
    };

