    /**
     * <pre>
     * 해당 날짜의 Date타입 객체를 YYYYMMDD 포맷의 날짜 문자열로 변환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getDateStr(scdateo.getDateObj('20211023'));
     * scdateo.getDateStr(new Date());
     * 
     * @param {String} dateObj - Date 객체
     * 
     * @return {String} - YYYYMMDD 날짜
     * </pre>
     */
    var getDateStr = function(dateObj) {
        var _self = this;

        var yr, mon, day;
        yr = dateObj.getFullYear().toString();
        mon = (dateObj.getMonth() + 1).toString();
        day = dateObj.getDate().toString();

        if (mon.length == 1) mon = "0" + mon;
        if (day.length == 1) day = "0" + day;

        //return yr + _self.$_h.DELIMITER_DATE + mon + _self.$_h.DELIMITER_DATE + day;
        return yr + mon + day;
    };

