    /**
     * <pre>
     * 해당 연도를 표준 4자리 연도로 변환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getYear("2021");
     * scdateo.getYear("021");
     * scdateo.getYear("21");
     * scdateo.getYear("1");
     * 
     * @param {String} yr - 연도 : Y, YY, YYY, YYYY 포맷의 연도
     * 
     * @return {String} - 연도
     * </pre>
     */
    var getYear = function(yr) {
      var iYr = 0;
      yr = scutilo.skipSpaces(yr);

      if (yr == "") {
        scutilo.showMsg(scglblo.MSG.WARN,"올바른 연도를 입력하세요.");
        return "";
      }

      if (yr.length > 4) {
        scutilo.showMsg(scglblo.MSG.WARN,"올바른 연도를 입력하세요.");
        return "";
      }

      for (var i=0; i< yr.length ; i++ )
      {
        if ( (yr.charAt(i) < "0") || (yr.charAt(i) > "9") ) {
          scutilo.showMsg(scglblo.MSG.WARN,"올바른 연도를 입력하세요.");
          return "";
        }
      }

      if (yr.length==4) {
        return yr;
      }

      iYr = parseInt(yr, 10);

      switch (yr.length){
        case 1: {yr="0"+yr; break; }
        case 3: {yr=yr.substr(1,2); break;}
      }

      if (iYr > 50) return "19"+ yr;
      else return "20" + yr;
    };

    /*
