    /**
     * <pre>
     * 입력한 날짜의 요일을 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getDayOfWeek('20220520', true);
     * scdateo.getDayOfWeek('20220520');
     * 
     * @param {String} dateStr - 날짜 : YYYYMMDD 포맷
     * @param {Boolean} isFullName - '요일' 추가 여부
     * 
     * @return {String} - 요일
     * </pre>
     */
    var getDayOfWeek = function(dateStr, isFullName){
        var _self = this;
        var dayOfWeek = "";
        try{
            var weekDays   = ["일", "월", "화", "수", "목", "금", "토"];
            var dateFormat =/[0-9]{4}[0-9]{2}[0-9]{2}/; //YYYYMMDD 숫자포맷 
            if(dateFormat.test(dateStr)){
              var dateObj   = _self.getDateObj(dateStr);
              var dayOfWeek = weekDays[dateObj.getDay()];
              if(isFullName && dayOfWeek != ""){
                dayOfWeek += "요일";
              }
            }
        }catch(err){
            dayOfWeek = "";
        }
        return dayOfWeek;
    };

    return {
        $_h: $_h,
        getDateObj: getDateObj,
        getDateStr: getDateStr,
        getDayOfWeek: getDayOfWeek,
        getDaysBetween: getDaysBetween,
        getDbDateStr: getDbDateStr,
        getDbTimeStr: getDbTimeStr,
        getFmtDate : getFmtDate,
        getNxtMmYmd: getNxtMmYmd,
        getNxtYmd: getNxtYmd,
        getNxtYmdSkipLastHldy161: getNxtYmdSkipLastHldy161,
        getNxtYmdSkipLastHldyWSat: getNxtYmdSkipLastHldyWSat,
        getPrevYmd: getPrevYmd,
        getPrevYmdSkipLastHldy161: getPrevYmdSkipLastHldy161,
        getPrevYmdSkipLastHldyWSat: getPrevYmdSkipLastHldyWSat,
        getPrintDate: getPrintDate,
        getShortDate: getShortDate,
        getYear: getYear,
        isHldy: isHldy,
        isHldy161: isHldy161,
        isHldyWSat: isHldyWSat,
        isSat: isSat,
        loadHldyLst: loadHldyLst,
    }
} ();

