    /**
     * <pre>
     * scutilo.setRange 함수와 같이 규칙/불규칙적인 범위문자열을 실제 비교를 위한 정보를 담고있는
       문자열 Array로 반환한다 (단, 구간 문자열의 구분자는 "," 이며, "-"를 이용하여 구간을 지정할 수 있다)
       또한 구간의 경우 숫자가 아니면 구간으로 취급하지 않는다 (예: "K-X" 는 "K,X"와 동일하다)
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getRangeStr("11,21")의 경우 11,21을 문자열 어레이로 반환
     * scutilo.getRangeStr("11,21-25")의 경우 11,21,22,23,24,25를 문자열 어레이로 반환
     * scutilo.getRangeStr("K-R")의 경우 K,R을 문자열 어레이로 반환
     * 
     * @param {String} psRange - 필터링 범위 문자열(예 : "1, 2, 4-6")
     * 
     * @return {Array} - 범위에 해당하는 숫자 문자열 배열
     * </pre>
     */
    var getRangeStr = function(psRange) {
        var tokens = psRange.split(",");
        var rtn_data = new Array();

        for (var i = 0; i < tokens.length; i++) {
            tokens[i] = scutilo.getAllTrim(tokens[i]);
            if (tokens[i].indexOf("-") >= 0) {
                var bound = tokens[i].split("-");
                var startNum = parseInt(bound[0], 10);
                var endNum = parseInt(bound[1], 10);

                if (bound[0] == "")
                    bound[0] = "1";
                if ((!isNaN(startNum)) && (!isNaN(endNum))) {
                    for (var num = startNum; num <= endNum; num++) {
                        rtn_data.push(String(num));
                    }
                } else {
                    rtn_data.push(scutilo.getAllTrim(bound[0]));
                    rtn_data.push(scutilo.getAllTrim(bound[1]));
                }
            } else {
                if (scutilo.isNumber(tokens[i]))
                    tokens[i] = String(parseInt(tokens[i], 10));
                rtn_data.push(tokens[i]);
            }
        }
        return rtn_data;
    };

