    /**
     * <pre>
     * Base64 Decoding 후 반환한다. 
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.decode('dGVzdA==');
     * scutilo.decode('JUVBJUIwJTgwJUVCJTgyJTk4JUVCJThCJUE0');
     * 
     * @returns {String} base64 복호화
     * </pre>
     */
    var decode = function(str) {
        // 각 화면에서 컴포넌트 이벤트로 바로 설정할 경우 this는 컴포넌트가 반환되어 예외로 _self 는 scutil로 선언
        var _self = scutilo;
