     * scutilo.bindGridCmpnt('gridView1', 'csProgStepCd', sccdo.getIntgCdLst(intgGrpCd), scglblo.CMPNT_ITEMSET.SCCDO);
     * scutilo.bindGridCmpnt('gridView1', 'csProgStepCd', sccorto.getCortLst(), {
