psp.load_page = function(mPgmId, sPgmId, paramObj) {
    _trace("[#l_p] <mPID>", mPgmId, "<sPID>", sPgmId, "<param>", paramObj, "");

    var pageinfo = this.getXmlPath2Load(mPgmId, sPgmId); //this.getXmlPathByPgmId(mPgmId); // scwin.getXmlPathByPrgmId(s);
    _trace("[#l_p] <pageinfo>", pageinfo);

    var menuinfo = psp.getMenuInfo(mPgmId); //로드할 메뉴정보
    var menuname = "" + mPgmId;
    var currMenuinfo = psp.ss.get(psp.LS_KEY_MN_C, true); //현재(==바로전) 메뉴정보 //JSON.parse( WebSquare.localStorage.getItem("psp_currmenu") );

    if ( null!=menuinfo ) { //1. 이동할 메뉴 정보가 있음(메뉴 클릭시)
        menuname = menuinfo["menuNm"];

        psp.ss.set(psp.LS_KEY_MN_C, menuinfo); //현재 메뉴(psp_currmenu)에 '로그할 메뉴'로 저장

        if ( null==currMenuinfo || menuinfo.elpMenuSrno == currMenuinfo.elpMenuSrno ) {
        		psp.ss.remove(psp.LS_KEY_MN_P); //이전 메뉴(psp_prevmenu) 정보 삭제
        }
        else {
        		psp.ss.set(psp.LS_KEY_MN_P, currMenuinfo); //이전 메뉴에 '바로전 메뉴'정보 저장
        }
    }
    else { //2. 메뉴정보가 없는 경우
        // (1) 상세페이지로 이동(정상) (2) 잘못된 프로그램ID(오류)
        if ( ! mPgmId.startsWith("PSP1") ) {
        		menuname = "현재 메뉴에 대한 접근 권한이 필요합니다!";
        		pageinfo.viewpath = psp.CONTEXT_ROOT + "/ui/pspcom/pferror.xml";
        }
    }

    pageinfo["viewname"] = menuname;
    var ssparam = psp.ss.get(psp.SS_PAGEPARAM, true);
    var dat = {};

    Object.assign(dat, ssparam, paramObj, pageinfo); //Object.assign(dat, pageinfo, paramObj, ssparam);
    _trace("[#l_p] <pageinfo>", pageinfo);
    _trace("[#l_p] <paramObj>", paramObj);
    _trace("[#l_p] <ssparam>", ssparam);
    _trace("[#l_p] <params>", dat);

    var params = {
        "dataObject": {
            "type" : "json",
            "name" : "wframeParam",
            "data" : dat
        }
    };

    // 전달된 파라미터(m,s)의 값으로 해당 페이지를 '작업영역'에 로드
    $p.top().pfwork.setSrc(pageinfo.viewpath, params); //WORK_FRAME_ID = pfwork

    var divQuickMenu = psp.componentById("grp_quick_menu", "pfright");
    if ( divQuickMenu ) {
        divQuickMenu.setStyle("display", "none");
    }
    else {
        _trace("[#l_p]", "grp_quick_menu 없음!");
    }
};

/**
 * 화면(프로그램)ID로 해당 xml 화면을 work 영역에 로드 처리
 *
 * @param	prgmId		주프로그램ID 또는 부프로그램ID (만약 부프로그램ID라면, 현재 URL의 주프로그램ID 참조됨)
 * @param	paramObj	로드될 페이지로 넘기게될 파라미터객체 (참조: 이 객체는 SS에 저장됨)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.loadPage = function(prgmId, paramObj) {
    _trace("[#loadPage]", "<이동할PID>", prgmId);
    var mn = psp.getMenuInfo(prgmId.toUpperCase());

    var mPgmId = "";
    var currQsParam = WebSquare.net.paramObj; //==psputils.urlparams(); //현재의 쿼리스트링을 그대로 유지

    if ( null==mn || ! mn.hasOwnProperty('m') || scutilo.isEmpty(mn["m"]) ) {
        mPgmId = currQsParam["m"];
        currQsParam["s"] = prgmId; //부프로그램ID
        if ( mPgmId.toUpperCase() == prgmId.toUpperCase() ) {
            delete currQsParam["s"]; //현재의 쿼리스트링에 s값이 있다면 제거
        }
    }
    else {
        mPgmId = prgmId;
        delete currQsParam["s"]; //현재의 쿼리스트링에 s값이 있다면 제거
    }

    if ( prgmId.startsWith("PSP611M") && currQsParam['elpNtcMtrSrno'] ) { // URL파리미터전달 처리 추가 @2024.06.11 @see PspLayoutDefault.xml
        delete currQsParam["elpNtcMtrSrno"]; //현재 화면에 전달되었던 URL파리미터에서 이 값을 제거함
    }

    psp.go_url(mPgmId, currQsParam, paramObj, false);
};

/**
 * 지정한 주프로그램ID 화면으로 이동처리함(현재 기본 DocumentRoot 로 location 이동처리함)
 *
 * @param  mPgmId      주프로그램ID
 * @param  objParam    해당 주프로그램ID에 전달할 정보(객체) (참고) 이 정보는 sessionStorage에 임시 저장
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.10.17.   주인철         [NELS]최초 생성
 * ============= ============ ==========================
 */
 psp.loadPageDefaultPath = function(prgmId, paramObj) {
    _trace("[#loadPage]", "<이동할PID>", prgmId);
    var mn = psp.getMenuInfo(prgmId.toUpperCase());

    var mPgmId = "";
    var queryParam = WebSquare.net.paramObj; //==psputils.urlparams(); //현재의 쿼리스트링을 그대로 유지

    if ( null==mn || ! mn.hasOwnProperty('m') || scutilo.isEmpty(mn["m"]) ) {
        mPgmId = queryParam["m"];
        queryParam["s"] = prgmId; //부프로그램ID
        if ( mPgmId.toUpperCase() == prgmId.toUpperCase() ) {
            delete queryParam["s"]; //현재의 쿼리스트링에 s값이 있다면 제거
        }
    }
    else {
        mPgmId = prgmId;
        delete queryParam["s"]; //현재의 쿼리스트링에 s값이 있다면 제거
    }

    if ( prgmId.startsWith("PSP611M") && queryParam['elpNtcMtrSrno'] ) { // URL파리미터전달 처리 추가 @2024.06.11 @see PspLayoutDefault.xml
        delete queryParam["elpNtcMtrSrno"]; //현재 화면에 전달되었던 URL파리미터에서 이 값을 제거함
    }

	var _url = {}
	if ( null!=queryParam ) {
		for (ky in queryParam) { //쿼리스트링으로 전달할 파라미터의 값이 문자열 'null', 'undefined' 이면 키 자체를 제거함.
			if (queryParam.hasOwnProperty(ky)) {
				let val = queryParam[ky];
				if ( "null"===val || "undefined"===val ) {
					delete queryParam[ky];
				}
			}
		}
		Object.assign(_url, queryParam); //디폴트 현재 쿼리스트링을 이동할 쿼리스트링에 추가
	}
	if ( ! scutilo.isEmpty(mPgmId) ) {
		_url["m"] = mPgmId;
	}
	let keepCurrSsParam = false;
	var _param = {};
	if ( null!=keepCurrSsParam && true==keepCurrSsParam ) {
		var ssdata = psp.ss.get(psp.SS_PAGEPARAM, true); //JSON.parse(window.sessionStorage.getItem(psp.SS_PAGEPARAM));
		Object.assign(_param, ssdata); //현재 페이지로 전달되었던 param 객체를 유지
	}
	if ( null!=paramObj ) {
		Object.assign(_param, paramObj); //전달된 param 객체를 병합
	}
	psp.ss.set(psp.SS_PAGEPARAM, _param); //window.sessionStorage.setItem(psp.SS_PAGEPARAM, JSON.stringify(_param));

	var querystring = psputils.serialize(_url);

	if ( scutilo.isEmpty(querystring) ) {
		psp.ss.remove(psp.SS_PAGEPARAM); //홈으로 이동시 페이지파라미터 제거
	}
    // location.href = "https://"+location.hostname+location.pathname+"?" + (scutilo.isEmpty(querystring) ? "" : "?"+querystring);
    location.href = "/psp/index.on"+(scutilo.isEmpty(querystring) ? "" : "?"+querystring);
};


/**
 * (용도) 업무상세페이지(메뉴에 직접 링크된 페이지 아님)에서,
 * 해당 업무의 메인 화면으로 이동할때 호출
 * (예) m=PSP099M01&s=PSP099M02 (화면 ~099M02/M03 에서 화면 ~099M01로 이동하고자 할때)
 *
 * @param	paramObj	주프로그램ID 페이지로 넘기게될 파라미터객체 (참조: 이 객체는 SS에 저장됨)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.20.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.loadBizMain = function(paramObj) {
    _trace("[#loadBizMain]", "[paramObj]", paramObj);

    var currQsParam = WebSquare.net.paramObj; //(예) m=PSP099M01&s=PSP099M02&c=0101101&no=1111&...
    var mPgmId = currQsParam["m"];
    var sPgmId = currQsParam["s"];

    if ( scutilo.isEmpty(mPgmId) ) {
        psp.go_url(); //메인 홈으로 이동
        return;
    }

    var menuInfo = psp.getMenuInfo(mPgmId.toUpperCase()); //해당 메뉴ID롤 메뉴정보를 참조
    if ( null==menuInfo || ! menuInfo.hasOwnProperty('pgmUrl') || scutilo.isEmpty(menuInfo["pgmUrl"]) ) { //해당 메뉴ID롤 메뉴정보를 참조할수 없음.
        psp.go_url(); //메인 홈으로 이동
        return;
    }

    delete currQsParam["s"]; //현재의 쿼리스트링에 s값이 있다면 제거 //(주의) 이 함수는 해당 메뉴의 기본화면으로 이동하는 기능

    var pgparam = Object.assign({}, menuInfo, paramObj); //조회된 메뉴정보와 전달된 파라미터를 합침

    psp.go_url(mPgmId, currQsParam, pgparam, false);
};

/**
 * 화면ID가 사건확인(PSPA0UM01) 등 서류의 공통화면인 경우,
 * 전달된 서류정보(대분류,중분류등)를 이용하여 이동할 주메뉴아이디(m)를 구한뒤 화면을 로드함
