 *
 * @param	prgmId		서류의 공통화면 [부]프로그램ID
 * @param	paramObj	로드될 페이지로 넘기게될 파라미터객체 (참조: 이 파라미터내에 문건대분류콛, 문건소분류코드 필요)
 * @see		psp.loadPage()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.06.20.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.loadDocmtPage = function(pid, oparam) {
	var mid = psp.docmenu.getMid(oparam);

	_debug("[#load.d.p] mid =", mid, "/ pid =", pid, "/ [oparam]", oparam);
	if ( scutilo.isEmpty(mid) ) {
		psp.loadPage(pid, oparam);
		return;
	}

	var menuInfo = psp.getMenuInfo(mid.toUpperCase());
	var qsParam = {};

	if ( scutilo.isNotEmpty(pid) && mid != pid ) {
		qsParam['s'] = pid.toUpperCase();
	}
	psp.go_url(mid, qsParam, oparam, false);
};


