/**
 * <pre>
 * 브라우저 팝업을 오픈
 *
 * (사용예)
 * psp.openUrlPopup("PSPPOPP01", "주소정보조회" , {"initData1" : "123", "initData2" : "456"}, 1024, 600, "scwin.callBackAddrExec", false);
 *
 * @param popupId           오픈 팝업ID (예) PSPPOPP01
 * @param popupNm           오픈 팝업명
 * @param paramInfo         팝업에 넘겨줄 변수 정보
 * @param popupScrnWdth     팝업넓이
 * @param popupScrnHght     팝업높이
 * @param callbackFn        callBack함수명 (주의) 문자열만 허용
 * @param isModal           모달여부 [default: true]
 * @param popupScrnTopCodn  팝업상단위치
 * @param popupScrnLeftCodn 팝업좌측위치
 * </pre>
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  XXXX.XX.XX.   XXX         [NELS]최초 생성
 *  2025.05.27    이정의        [25A-PSP-0035] 반응형 웹 및 모바일 스타일 개선
 * ============= ============ ==========================
 */
psp.openBrowserPopup = function(popupId, popupNm, paramInfo, popupScrnWdth, popupScrnHght, callbackFn, isModal, popupScrnTopCodn, popupScrnLeftCodn ) {
    var baseUrl = $p.top().scwin.BPOP_CNTR; //팝업 컨테이너 //scutilo.getSCMain().$p.top().scwin.PSUB_CONTAINER;
    var opt = {};
    opt.id = popupId;
    opt.width = popupScrnWdth;
    opt.height = popupScrnHght;
    opt.type = "browserPopup"; //브라우저 팝업
    opt.modal = (isModal === false) ? false : true;
    opt.popupName = popupNm + " - 전자소송포털";
    opt.top = popupScrnTopCodn + "px";
    opt.left = popupScrnLeftCodn + "px";
    opt.isLinkOpen = "N";    //opener 가 linke 로 열린 경우 추가
    if ( window.location.pathname.indexOf("link.on")>0 ) {
    	opt.isLinkOpen = "Y";
    }

    var pgmUrl = psp.getXmlPathByPgmId(popupId); //
    var parentInfo = { // 호출하는 frameId, 팝업여부 추가
        parentFrameId: $p.getFrameId(),
        parentPopupId: window.$p.getPopupId(),
        //parentIsPopup: scutilo.isPopup(),
    };
    paramInfo = $.extend({}, parentInfo, paramInfo);

    var data = {"type": opt.type};
    $.extend(data, paramInfo);
    data.callbackFn = callbackFn;

    //dataobject에 추가할 데이터 셋팅
    var moveData = {
        originUrl : pgmUrl,
        title : opt.popupName,
        frame : "main",
        isLinkOpen : opt.isLinkOpen
    };
    $.extend(data, moveData);

    var _dataObj = {
        type : "json",
        data : data,
        name : "paramData"
    };
    var width = opt.width || 1200;
    var height = opt.height || 700;

    try {
        if (!opt.notMinSize) {
            if (window.screen.availHeight <= height) {
                height = window.screen.availHeight-10;
            }
        }
    } catch (ex) {
        console.error(ex);
    }

    var top  = Math.floor(((window.screen.availHeight- 50 - com.num.parseInt(height)))/ 2) + (window.screen.availTop|| 0) + "px";
    var left = Math.floor((window.screen.availWidth - com.num.parseInt(width)) / 2) + (window.screen.availLeft || 0 ) + "px";

    if (typeof _dataObj.data !== "undefined") {
        if (typeof _dataObj.data.callbackFn == "function") {
            var cbFuncIdx = ++gcm.CB_FUNCTION_MANAGER["cbFuncIdx"];
            var idx = "__close_callback_Func__" + new Date().getTime() + "_" + cbFuncIdx;
            gcm.CB_FUNCTION_MANAGER["cbFuncSave"][$p.id + idx] = _dataObj.data.callbackFn;
            _dataObj.data.callbackFn = $p.id + idx;
        } else if (typeof _dataObj.data.callbackFn === "undefined") {
            _dataObj.data.callbackFn = "";
        } else if (typeof _dataObj.data.callbackFn === "string") {
            _dataObj.data.callbackFn = $p.id + _dataObj.data.callbackFn;
        }
    }

    var paramUrl = "&" + _dataObj.name + "=" + WebSquare.text.BASE64Encode(com.str.serialize(_dataObj.data)) ;

    var options = {
        id : opt.id || 'Popup' + String(Math.random()),
        popupName : opt.popupName || "",
        type : opt.type || "browserPopup",
        width : width + "px" || "1600px",
        height : height + "px" || "900px",
        top : opt.top || top || "140px",
        left : opt.left || left || "500px",
        modal : (opt.modal == false) ? false : true,
        dataObject : _dataObj,
        alwaysOnTop : opt.alwaysOnTop || false,
        useModalStack : (opt.useModalStack == false) ? false : true,
        resizable : (opt.resizable == false) ? false : true,
        useMaximize : opt.useMaximize || false,
        className :opt.className || "",
        scrollbars : true,
        disableCloseButton  : opt.disableCloseButton || false
        //popupUrl : ".."+gcm.STG_CONTEXT_PATH+"/popup"
    };
    const beforePopupListLength = $p.getAllPopupWindowList().length;
    $p.openPopup(baseUrl + paramUrl, options);
    if (psp.env.isMobileApp()) {		// [25A-PSP-0035] 모바일인 경우 브라우저팝업 body에 psp_app 클래스 추가
    	const timer = setInterval(()=>{
    		if (beforePopupListLength < $p.getAllPopupWindowList().length) {
    			if ($p.getAllPopupWindowList()[0].document.body.classList.contains('body_popup')) {
    				$p.getAllPopupList().forEach((item, index) => {
    					item.popupWin.document.body.classList.add("psp_app");
    				})
    				clearInterval(timer);
    				console.log("팝업에 psp_app 클래스 추가완료(모바일)");
    			}
    		}
    	}, 50);
    }
};

/**
 * 현재 호출한 화면스코프가 레이어 팝업인치 판단
 *
 * @param  _p	현재 호출한 화면스코프 유틸리티 객체
 * @return 현재 호출한 화면스코프가 레이어 팝업이면 true
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.11.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.isLayerPopup = function(_p) {
	return null==_p ? ($p.isPopup() && $p.isWFramePopup()) : (_p.isPopup() && _p.isWFramePopup());
};
psp.isBrowserPopup = function(_p) {
	let __p = _p || $p;
	return __p.isPopup() && ! __p.isWFramePopup() && __p.getPopupUrl().indexOf('PSPBPopCntr')>0; //'/psp/ui/pspcom/PSPBPopCntr.xml'
};
psp.isPopup = function(_p) {
	return psp.isLayerPopup(_p) || psp.isBrowserPopup(_p);
};

/**
 * 팝업화면을 닫는다(레이어팝업, 브라우저팝업)
 *
 * @param callbackFnStr  callBack함수명(문자열)
 * @param callbackParam  팝업응답객체(또는 문자열 가능)
 * @see 	commonScope.js#com.win._closePopup() [#7804~#7837]
 */
psp.close_popup = function(callbackFnStr, callbackParam) {
    _trace("[_#c.p] " + callbackParam);
    var popId  = com.win.getPopupId();
    var rtnStr = com.str.serialize(callbackParam);
    com.win._closePopup(popId, callbackFnStr, rtnStr); //com.win._closePopup(com.win.getPopupId(), callbackFnStr, com.str.serialize(callbackParam));
};


/**
 * 지정한 공통코드 데이트를 정의된( dlt_코드그룹 ) 데이터콜렉션(데이터리스트)로 생성한다. 있으면 해당 데이터리스트 객체를 반환한다.
 *
 * @param  intgGrpCd - 공통코드그룹 문자열(like, CORT_TYP_CD)
 * @return 데이터콜렉션(데이터리스트) 객체
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.get_code_datalist = function(intgGrpCd) {
    if ( scutilo.isEmpty(intgGrpCd) ) {
        _warn("[psp.js#get_code_datalist]","공통코드 =", intgGrpCd, "* 입력한 공통코드값이 없음!"); return null;
    }

    var dc = null
    try {
        var dataListId = "dlt_" + intgGrpCd;
        var scopeObj = $p.getComponentById("mf_pffooter");
//        console.log("[psp.js#get_code_datalist]", null==scopeObj ? "<mf_pffooter 빈객체>" : "<mf_pffooter 정상객체>", "공통코드 =", intgGrpCd, "dataListId =", dataListId);

        dc = scopeObj.scope.$p.getComponentById(dataListId); // dataCollection
        if (undefined!=dc && null!=dc && "datalist"===dc.getObjectType().toLowerCase()) {
//            console.log("[psp.js#get_code_datalist]", intgGrpCd, " 데이터리스트객체ID =", dc.getID(), "<마침>");
            return dc;
        }
        var colInfo = [];
            colInfo.push({id: "systmCd", "name": "시스템코드", dataType: "text"});
            colInfo.push({id: "intgCdOnrIdntId", "name": "통합코드주체식별ID", dataType: "text"});
            colInfo.push({id: "intgGrpCd", "name": "통합그룹코드", dataType: "text"});
            colInfo.push({id: "intgCd", "name": "intgCd", dataType: "text"});
            colInfo.push({id: "intgCdNm", "name": "intgCdNm", dataType: "text"});
            colInfo.push({id: "intgCdOnrDvsCd", "name": "통합코드주체구분코드", dataType: "number"});
            colInfo.push({id: "intgInscrtMtjrCdLstCtt", "name": "통합심급사물관할코드목록내용", dataType: "text"});
            //id="elpNtcMtrSrno" name="소송포털공지사항일련번호" dataType="text"
            //{"systmCd":"STG","intgCdOnrIdntId":"STG","intgGrpCd":"CORT_TYP_CD","intgCd":"10","intgCdNm":"대법원","intgCdOnrDvsCd":1,"intgInscrtMtjrCdLstCtt":null,"fstmIntgCdAddCtt":null,"scntmIntgCdAddCtt":null}

        /*Object.keys(columnInfo).forEach(function(key) {
            colInfo.push(columnInfo[key]);
        })*/

        var option = {
            "type": "dataList",
            "option": { "baseNode": "list", "repeatNode": "map" }
        }
        option.id = dataListId;
        option.columnInfo = colInfo;

        scopeObj.scope.$p.data.create(option);

        var intgCdLst = sccdo.getIntgCdLst(intgGrpCd);

        dc = scopeObj.scope.$p.getComponentById(dataListId);
        dc.setJSON(intgCdLst);

        var dcData = dc.getAllJSON();
        var dcSize = null==dcData ? -1 : dcData.length;
        _info("[psp.js#get_code_datalist]", scopeObj, "공통코드 =", intgGrpCd, "데이터사이즈 =", dcSize);
        _trace("[psp.js#get_code_datalist]", scopeObj, "공통코드 =", intgGrpCd, "데이터JSON--------\n", dcData, "\n-------------------------");
    }
    catch(e) {
        _debug("[psp.js#get_code_datalist]", "catched", e.message);
    }
    return dc;
};

