			_debug("[#g_u_m] 사용자 메뉴개수 :", usermenu.length);
		},
	});
	psp.getFavMenu('', doforcely);
	return usermenu;
};


/**
 * 현재 로그인한 사용자의 즐겨찾기 메뉴 조회
 *
 * @param   opts	옵션 객체
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getFavMenu = function(dvsCd, doforcely) {
	var favmenu = null;
	if ( null==doforcely || true!=doforcely ) {
		favmenu = psp.ss.get(psp.LS_KEY_MN_F, true); //'psp_favmenu'
		if ( null!=favmenu && 'object'== typeof favmenu ) {
			_debug("[#g_f_m] [LS] 즐겨찾기 메뉴# :", favmenu.length);
			return scutilo.isEmpty(dvsCd) ? favmenu : favmenu.filter( mn => dvsCd === mn.elpMenuDvsCd );
		}
	}
	com.executeAjax({ //
		action: psp.CONTEXT_ROOT + "/pspmenu/selectFavMenuList.on",
		mode: "synchronous",
		mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
		requestData: JSON.stringify({'elpMenuDvsCd':dvsCd}),
		success: function(R) {
			favmenu = R.responseJSON.data.dlt_favmenu;
			var reqData = JSON.parse(this.requestData);
			if ( "02" != reqData['elpMenuDvsCd'] ) { //시작메뉴를 조회한 경우가 아니면
				psp.ss.set(psp.LS_KEY_MN_F, favmenu);
			}
			_debug("[#g_f_m] 조회된 즐겨찾기 메뉴(size) :", favmenu.length);
		},
		error: function(R) {
			alert("즐겨찾기 메뉴\n\n" + JSON.stringify(R.responseJSON));
		}
	});
	return favmenu;
};


/**
 * 지정한 주프로그램ID 화면으로 이동처리함.
 *
 * @param  mPgmId      주프로그램ID
 * @param  queryParam  URL 쿼리스트링에 포함하여 전달할 정보(객체) (예) { s=주프로그램ID, debugger=디버그모드 켜기/끄기, 기타 }
 * @param  objParam    해당 주프로그램ID에 전달할 정보(객체) (참고) 이 정보는 sessionStorage에 임시 저장 (예) { 공지사항ID, ... 등 }
 * @param  keepCurrSsParam    현재 ss에 저장중인 파라미터 객체를 유지할지 여부 (true여야 유지)
 */
psp.go_url = function(mPgmId, queryParam, objParam, keepCurrSsParam) {
	//var curUrlParam = WebSquare.net.paramObj;
	var _url = {}
	if ( null!=queryParam ) {
		for (ky in queryParam) { //쿼리스트링으로 전달할 파라미터의 값이 문자열 'null', 'undefined' 이면 키 자체를 제거함.
			if (queryParam.hasOwnProperty(ky)) {
				let val = queryParam[ky];
				if ( "null"===val || "undefined"===val ) {
					delete queryParam[ky];
				}
			}
		}
		Object.assign(_url, queryParam); //디폴트 현재 쿼리스트링을 이동할 쿼리스트링에 추가
	}
	if ( ! scutilo.isEmpty(mPgmId) ) {
		_url["m"] = mPgmId;
	}

	var _param = {};
	if ( null!=keepCurrSsParam && true==keepCurrSsParam ) {
		var ssdata = psp.ss.get(psp.SS_PAGEPARAM, true); //JSON.parse(window.sessionStorage.getItem(psp.SS_PAGEPARAM));
		Object.assign(_param, ssdata); //현재 페이지로 전달되었던 param 객체를 유지
	}
	if ( null!=objParam ) {
		Object.assign(_param, objParam); //전달된 param 객체를 병합
	}
	psp.ss.set(psp.SS_PAGEPARAM, _param); //window.sessionStorage.setItem(psp.SS_PAGEPARAM, JSON.stringify(_param));

	var querystring = psputils.serialize(_url);

	if ( scutilo.isEmpty(querystring) ) {
		psp.ss.remove(psp.SS_PAGEPARAM); //홈으로 이동시 페이지파라미터 제거
	}
	var urlStr = "index.on" + (scutilo.isEmpty(querystring) ? "" : "?"+querystring)
	var urlOpt = {spa: false, "replaceHistory" : true, "shortURL" : false};
	//$p.url(urlStr, urlOpt);
	$p.url("index.on" + (scutilo.isEmpty(querystring) ? "" : "?"+querystring));
};


/**
 * 스크린ID(프로그램ID)로 로드된(로컬스토리지) 메뉴정보를 참조하여 해당 URL 경로로 이동
 * (참고) 메뉴에 링크된 중우 주프로그램(m)만 존재함.
 *
 * @param   paramMenuInfo	메뉴정보 객체
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.onMenuClick = function(paramMenuInfo) {
    var menuObj = null;
    var menuInfo = null;
    var menuInfoObj = null;

    // 중복로그인 체크 - 업무화면내에서 서비스 호출시 체크
    var dupLoginYn = psp.getSession("dupLoginYn");
    _debug("[@_sbm_defCallbackSubmission]", "<dupLoginYn>", dupLoginYn);
    if("Y"==dupLoginYn) {

    	scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0000, "다른 컴퓨터에서 같은 사용자가 로그인 하셨습니다.\n본 컴퓨터는 자동 로그아웃 됩니다."), function() {
    			psp.clearSesn(9); //중복로그인 Redis Key 제거 포함
    			psp.go_url();
    			return;
   		});
    	return;
    } //-------------------------------------------------


    try {
        menuObj = WebSquare.util.getComponentById(this.id); //this == menulink 객체 (ex) $("#mf_pfheader_"+"grp_mn1")[0];
        menuInfo = menuObj.getUserData("menuinfo");
        menuInfoObj = JSON.parse(menuInfo);
        _debug("[#o_m_c]", "<menu element clicked> <this.id>=", this.id);

    }
    catch(e) {
    	// this가 WS객체가 아니면
    	menuInfoObj = paramMenuInfo;
    	if ( null!=paramMenuInfo && 5 > Object.keys(paramMenuInfo).length ) {
    		menuInfoObj = psp.getMenuInfo( paramMenuInfo['pgmUrl'] );
    	}
        _trace("[#o_m_c]", "<menuInfo>", menuInfoObj);
    }

    var mPgmId = menuInfoObj["pgmUrl"];
    var mElpMenuSrno = menuInfoObj["elpMenuSrno"];
    _debug("[#o_m_c]", "<menu info> pgmUrl(m)", mPgmId, ", <info>", menuInfo); // window.location.href, window.location.search

    if ( scutilo.isEmpty(mPgmId) ) { //메뉴정보 없음
        var subCnt = menuInfoObj["subCnt"];
        if ( subCnt>0 ) {
            _debug("[#o_m_c] sub menu exists."); //이동할 메뉴에 프로그램ID(pgmUrl)이 매핑되지 않음 + 하위메뉴있음.
        }
        let child1stMenuList = psp.hierarchyFirstChildMenuList(menuInfoObj, false); //현재 메뉴의 하위중 1첫번째 자식들 목록
        let child1stMenuSize = null==child1stMenuList ? 0 : child1stMenuList.length;

        if ( 0==child1stMenuSize ) {
            var sMenuOpt = menuInfoObj["menuOpt"];
            if ( scutilo.isNotEmpty(sMenuOpt) ) { //연결된 화면이 없지만 내외부링크 정보가 있는 경우
                let menuOpt = JSON.parse(sMenuOpt);
                let linkUrl = menuOpt.url;
                let linkAct = menuOpt.action;
                _debug("[#o_m_c]", "<menuOpt>", menuOpt);
                if ( scutilo.isNotEmpty(linkAct) && linkAct === "location.href" ) {
                    location.href = linkUrl;
                }
                else { // (default)window.open
                    let winOpt = "width="+ window.innerWidth + ", height=" + window.innerHeight + ", directories=yes, location=yes, menubar=yes, scrollbars=yes, status=yes, resizable=yes, toolbar=yes"
                    window.open(linkUrl, "_blank", winOpt);
                }
                return;
            }
            if ( "1414" == mElpMenuSrno ) { //나홀로소송 상단메뉴 클릭시 나홀로소송도움말 GO
            	psp.go_url("PSPJ02M01", null);
            	return;
            }
            var msg = scutilo.getMsg(pspmsg.PSP.E_0032); //E_0032: "현재 선택한 메뉴는 프로그램과 연결되지 않았습니다.",
            scutilo.showMsg(scglblo.MSG.INFO, msg, function() {
                _trace("[#o_m_c]", "<오류메시지>", msg);
                return false;
            });
            return false;
        }
        _debug("[#o_m_c] sub menu selected : size =", child1stMenuSize, " // menu[] :", child1stMenuList);
        menuInfoObj = Object.assign({}, child1stMenuList[child1stMenuSize-1]);
        mPgmId = menuInfoObj["pgmUrl"];


    }


    //메뉴클릭시 현재 로그인타입을 참조하여 접근가능여부를 체크
    //var loginType = psp.getSmplSesn('loginType'); //$p.top().pfheader.scope.scwin.SMA_INFO.loginType : '';
    var loginType = psp.getSession('loginType'); //$p.top().pfheader.scope.scwin.SMA_INFO.loginType : '';
    var isAllowed = true;

    _debug("[#o_m_c]", "<elpMenuAthoTypCd>", menuInfoObj.elpMenuAthoTypCd);

    switch(menuInfoObj.elpMenuAthoTypCd) {
    case '2': isAllowed = scutilo.isNotEmpty(loginType) && 'G' <= loginType; break; //로그인타입에 관계없음(G 이상)
    case '3': isAllowed = scutilo.isNotEmpty(loginType) && 'O' <= loginType; break; //로그인타입이 인증서 로그인(P) 이상
    default:
    	break;
    }
    if ( false===isAllowed ) { //메뉴 접근 불허

    	var oSSMA = Object.assign({}, null);

    	if (scutilo.isEmpty(psp.getSession()) ) { //미로그인 상태

    	    oSSMA["statCode"] = "NEED_INTG_LGN";
    	    psp.open_popup("PSPMAMP01", "로그인 안내", oSSMA, 385, 255, function(rslt) {
    	        if ( null==rslt || scutilo.isEmpty(rslt.loginType) ) { //취소
    	            return false;
    	        }
    	        psp.go_url("PSP101M01", null);
    	        return false;
    	    });
        } else {

            //var msg = ('3'==menuInfoObj.elpMenuAthoTypCd ? '인증서 ':'') + scutilo.getMsg(pspmsg.PSP.E_0000, "로그인후 사용할 수 있습니다.");
            //scutilo.showMsg("로그인 안내", msg, function() {});
    	    oSSMA["statCode"] = "NEED_CERT_LGN";
    	    psp.open_popup("PSPMAMP01", "로그인 안내", oSSMA, 385, 255, function(rslt) {
    	        if ( null==rslt || scutilo.isEmpty(rslt.loginType) ) { //취소
    	            return false;
    	        }
    	        $p.top().pfheader.scope.scwin.certLgnWithSesn();
    	        return false;
    	    });
        }
        return false;
    }

    var qsParam = {}
    if ( "PSP101M01"==mPgmId.toUpperCase() ) { //(참고) 로그인화면으로 이동시, 현재 주/부프로그램 정보를 (n/t)로 전달하여, 로그인 성공후 되돌아옴
        qsParam["n"] = scutilo.isEmpty(WebSquare.net.paramObj["m"]) ? "" :  WebSquare.net.paramObj["m"];
        qsParam["t"] = scutilo.isEmpty(WebSquare.net.paramObj["s"]) ? "" :  WebSquare.net.paramObj["s"];
        if ( "null"===qsParam["t"] || "undefined"===qsParam["t"] ) {
            delete qsParam["t"];
        }
    }

    var sMnOpt = menuInfoObj["menuOpt"];
    var oMnOpt = null;
    try {
        oMnOpt = JSON.parse(sMnOpt);
        if ( oMnOpt["s"] ) {
            qsParam["s"] = oMnOpt["s"];
            Object.assign(menuInfoObj, oMnOpt);//나머지파라미터를 추가로 담아서 화면파라미터로 전달한다
        }
    }
    catch(e) {
        oMnOpt = {};
    }

    //팝업메뉴이면, 화면이동이 아닌 팝업으로 처리 @2023-09
    var isPopMenu = psputils.isPopupPgm(mPgmId);
    if ( true == isPopMenu ) {
        var popparam = {};
        if ( 'PSP006P01'==mPgmId ) { //관할법원찾기
            popparam = {
                "elctnLwstTaskTypCd":"", //소송유형코드
                "csNmCd":"", //사건명코드
                "openPage": "mainMenu" //오픈페이지유형
            }
            psp.openBrowserPopup(mPgmId, menuInfoObj["menuNm"], popparam, 1200, 700);
        }
        else {
            //현재(@2023-09) 이 경우는 없음. 추후 발생시 이 주석 제거
            psp.open_popup(mPgmId, menuInfoObj["menuNm"], menuInfoObj, 1200, 600);
        }
        return;
    } //endof 팝업메뉴

    // 나홀로소송 메뉴일 경우 알림메시지 팝업 ----------------------------
    var arrPgmId = new Array();
    arrPgmId = ["PSPH01M01","PSPH02M01","PSPH03M01","PSPH04M01","PSPH05M01","PSPH06M01","PSPH07M01","PSPH08M01","PSPH09M00","PSPH0BM00"];
    var isMatch = false;

	for(let i=0; i<arrPgmId.length; i++) {
		if ( -1 < mPgmId.indexOf(arrPgmId[i]) ) {
			isMatch = true;
		}
	}
	if (true==isMatch) {

    	var sMsg = "나홀로 소송은 종이서류 작성을 위한 단순 서비스 화면으로 전자제출 기능을 지원하지 않습니다. 해당 서류를 전자로 작성·제출하고자 하는 경우 [서류제출] 화면을 이용해 주시기 바랍니다.</br></br>나홀로 소송 서류작성을 계속하시겠습니까?";

		scutilo.showConfirm(scglblo.MSG.CONFIRM, sMsg, function(result) {
			if ( result.clickValue) {
				psp.go_url(mPgmId, qsParam, menuInfoObj, false); // false==기존 전달된 파라미터 유지안함
			}
			else {
				return;
			}
		});

	} else {
		psp.go_url(mPgmId, qsParam, menuInfoObj, false); // false==기존 전달된 파라미터 유지안함
	}
	//------------------------------------------------------------------


    //psp.go_url(mPgmId, qsParam, menuInfoObj, false); // false==기존 전달된 파라미터 유지안함
};


/**
 * 스크린ID(프로그램ID)로 로드된(로컬스토리지) 메뉴정보를 찾아서 반환
 *
 * @param   screenId	스크린ID(프로그램ID)
 * @return	조회된 메뉴정보
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getMenuInfo = function(screenId) {
	if ( scutilo.isEmpty(screenId) || "1"==screenId ) {
		return null;
	}
	_debug("[#g_m_i]", "<screenId>", screenId);
	_debug("[#g_m_i]", "<psp.LS_KEY_MENU>", psp.LS_KEY_MENU);

    var menulist = psp.ss.get(psp.LS_KEY_MENU, true); //JSON.parse(allmenustr);
    if ( null==menulist || $.isEmptyObject(menulist) ) {
        //menulist = scutilo.isEmpty(psp.session()) ? psp.get_allmenu_list(true) : psp.getUserMenu(true);  // 20240730 비회원 서류제출
        if(scutilo.isEmpty(psp.session()) || "NotUser" == psp.session()) {
        	_debug("[#g_m_i] null or NotUser");
        	menulist = psp.get_allmenu_list(true);
        } else {
        	_debug("[#g_m_i] User");
        	menulist = psp.getUserMenu(true);
        }

    }
    // (예) { "level":2,"elpMenuSrno":1701,"elpScrnId":61101,"uprElpMenuSrno":17,"menuNm":"공지사항", "pgmUrl":"PSP611M01", ... }
    var objMenuFound = null;
	var _list = [];

	menulist.forEach(function (mnInfo, index) {
		if ( screenId == mnInfo.pgmUrl || screenId == mnInfo.elpMenuSrno ) { //pgmUrl 또는 elpScrnId로도 검색
			_list.push(mnInfo); _trace("[#g_m_i] 메뉴 :", mnInfo);
		}
	});
	var _cnt  = null==_list ? 0 : _list.length;
	if ( 1>_cnt ) {
		_warn("[#g_m_i]", "조회된 메뉴 정보가 없습니다. <screenId>", screenId);
		return null;
	}
	objMenuFound = _list[_cnt-1]; //디폴트(맨마지막)

	var pgparam = psp.ss.get(psp.SS_PAGEPARAM, true);
	if ( null!=pgparam && pgparam.pgmUrl && pgparam.elpMenuSrno ) { //세션파라미터에 메뉴정보가 설정되어 있으면,
		_list.forEach(function (mnInfo, index) {
			if ( pgparam.elpMenuSrno == mnInfo.elpMenuSrno ) {
				objMenuFound = mnInfo;
			}
		});
	}
	return objMenuFound;
};

/**
 * 로드된(웹스토리지) 메뉴정보에서 지정한 메뉴포함한 상위 메뉴를 찾아서 배열로 반환
 *
 * (예) 3레벨 메뉴이면 [3레벨메뉴, 2레벨메뉴, 1레벨메뉴] 길이 3인 배열반환
 * (예) 2레벨 메뉴이면 [2레벨메뉴, 1레벨메뉴] 길이 2인 배열반환
 * (예) 1레벨 메뉴이면 [1레벨메뉴] 길이 1인 배열반환
 *
 * @param   mnInfo	메뉴정보
 * @return	상위 메뉴 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.hierarchyMenuList = function(mnInfo) {
	if ( null==mnInfo ) { return []; }
	var menus = [];
		menus.push(mnInfo);
	var uppers = psp.hierarchyMenuList( psp.getMenuInfo( mnInfo["uprElpMenuSrno"] ) );
	return menus.concat(uppers);
};

/**
 * 지정한 메뉴의 첫번쨰  자식메뉴 목록을 배열로 반환. (참고) hierarchyMenuList 역순
 * (예) '사건유형별 절차안내' 이면 [ [사건유형별 절차안내, ]공통안내, 전자소송안내, 전자소송의 개념 ]
 *
 * @param   mnInfo		메뉴정보
 * @param   selfInclude	해당 메뉴 포함 여부(디폴트 false)
 * @return	첫번째 메뉴 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.hierarchyFirstChildMenuList = function(mnInfo, selfInclude=false) {
	if ( null==mnInfo ) { return []; }
	var arrMenu  = [];
	var prevMnNo = 0;

	for(_m of psp.ss.get(psp.LS_KEY_MENU, true)) {
		if ( _m["level"]==mnInfo["level"] && _m["elpMenuSrno"]==mnInfo["elpMenuSrno"] ) {
			prevMnNo = _m["elpMenuSrno"];
			if ( true===selfInclude ) {
				arrMenu.push(_m);
			}
			continue;
		}
		if ( prevMnNo>0 && prevMnNo == _m["uprElpMenuSrno"] ) {
			prevMnNo = _m["elpMenuSrno"];
			arrMenu.push(_m);
			continue;
		}
		if ( prevMnNo>0 && _m["level"]==mnInfo["level"] ) {
			break;
		}
	}
	return arrMenu;
};

/**
 * 지정한 메뉴의 상위메뉴 목록을 배열로 반환. (참고) hierarchyMenuList 역순
 *
 * @param   mnInfo		메뉴정보
 * @return	상위메뉴 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.uppperMenuList = function(mnInfo) {
	if ( null==mnInfo ) { return []; }
	var menus = psp.hierarchyMenuList(mnInfo);
	if ( null==menus ) { return []; }
	menus.shift();
	return menus; //첫번째 메뉴==mnInfo 는 삭제, 즉, 상위 메뉴들만
};

/**
 * 지정한 메뉴의 자식 메뉴 목록을 배열로 반환
 *
 * @param   mnInfo	메뉴정보
 * @return	자식 메뉴 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.29.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.childMenuList = function(mnInfo, targetMenuList) {
	if ( null==mnInfo ) { return []; }
	var childlist = [];
	var started = false;
	var arr = null==targetMenuList || targetMenuList.length<1 ? psp.ss.get(psp.LS_KEY_MENU, true) : psputils.clone(targetMenuList); //(대상)메뉴목록
	_debug("[#c_m_l] 전체(대상)메뉴길이 :", arr.length);

	for(_m of arr) {
		if ( _m["level"]==mnInfo["level"] && _m["elpMenuSrno"]==mnInfo["elpMenuSrno"] ) {
			started = true;
			continue;
		}
		if ( _m["level"]==mnInfo["level"] && true === started ) {
			break;
		}
		if ( true === started ) {
			childlist.push(_m);
		}
	}
	_debug("[#c_m_l] 하위메뉴길이 :", childlist.length);
	return childlist;
};


