/**
 * 플러그인명, 클래스명에 부합하는 컴포넌트 목록을 구하여 반환
 *
 * @param	pluginNames		플러그인명
 * @param	classNames		클래스명(배열)
 * @param	objFrame		프레임 지정(선택)
 * @return	컴포넌트 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.15.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.componentsBy = function(pluginNames, classNames, objFrame) {
	var opts = { recursive:true };
	if ( null!=pluginNames ) {
		opts["includePlugin"] = $.isArray(pluginNames) ? pluginNames.join(" ") : pluginNames;
	}

	var complist = WebSquare.util.getChildren(null==objFrame ? $p.top().pfwork : objFrame, opts); // {recursive:true, includePlugin : "textbox"}
	if (null==complist) { return complist; }

	var _comps = [];
	var clss = (null==classNames) ? null : ($.isArray(classNames) ? classNames : classNames.split(/[, ]/) );

	complist.forEach(function (comp, index) {
		if (null==clss || 1>clss.length) {
			_comps.push(comp);
			return true; //continue
		}
		var compClss = comp.getClass();
		var matched = true;

		for(let i=0; i<clss.length; i++) {
			if ( 0>compClss.indexOf(clss[i]) ) {
				matched = false;
				break;
			}
		}
		if (true==matched) { _comps.push(comp); }
	});
	return _comps;
};


/**
 * 지정한 컴포넌트 한개의 validation을 진행하고 성공시 null 반환
 * 오류가 발생시 해당 컴포넌트 참조하여 오류메시지르 반환
 *
 * 1) input, textarea 는 디폴트로 trim(), clearxss() 처리함 (노트) userData1 : trim, clearxss 처리하지 않을 경우 trim=false,xss=false
 * 2) inputcalendar 는 추가로 년도 범위 체크함(1900 ~ 2120)
 * 3) secret : 커스텀구현할 필요
 * 4) 컴포넌트의 validate항목을 다시 체크함(mandatory, minLength, maxLength, allowChar)
 * 5) 해당 컴포넌트 추가 validate : userData2 에 추가로 검증할 함수명 설정. 함수구현은 psputils.validPasswd(str) 참조
 *
 * @param	component		체크할 컴포넌트 또는 컴포넌트ID
 * @param	subFrameId		pfwork 프레임하위의 컴포넌트ID (디폴트) 'mf_pfwork' (예) wfm_tab1 또는 mf_pfwork_wfm_tab1 둘다 가능
 * @param	doFocely		무조건 체크여부 (디폴트) false (예)컴포넌트가 [readOnly, disabled] 상태이면, 디폴트로 체크하지 않음
 * @return	그룹내 모든 컴포넌트들이 정상이면 null, 오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }
 * @see		psp.validate(groupId, subFrameId)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.02.           [NELS]최초 생성
 *  2026.07.23.           [26A-PSP-0091] 각종 메시지 내용 및 안내문구 수정
 * ============= ============ ==========================
 */
psp.validone = function(component, subFrameId, doFocely) {
	var _errobj = { "errMsg":null, "errObj":null }; //검증시 오류가 있을 경우, [메시지, 대상객체]를 설정하여 반환

	var compObj = ( 'object' == typeof component ? component : psp.componentById(component, subFrameId));
	var tagName = compObj.options.pluginName.toLocaleLowerCase();

	if ( null==doFocely || false==doFocely ) {
		if ( true==compObj.getAttribute("disabled") || "true"==compObj.getAttribute("disabled") ||
			 true==compObj.getAttribute("readOnly") || "true"==compObj.getAttribute("readOnly") ) {
			_debug("[#valid1] skip validation : ID=", compObj.getID(), ", disabled=", compObj.getAttribute("disabled"), ", readOnly=", compObj.getAttribute("readOnly"));
			return null; //(예)컴포넌트가 [readOnly, disabled] 상태이면, 디폴트로 체크하지 않음
		}
	}

	var compValOrg = null;
	var compVal    = null;
	try {
		compValOrg = compObj.getValue();
		compVal    = compObj.getValue();
	}
	catch(e) {
		if ( "editor"==tagName ) {
			compValOrg = compObj.getHTML();
			compVal    = compObj.getHTML();
		}
	}

	try {
		compVal = compVal.trim();
	}
	catch(e) {
		_debug("[#valid1] [error]", e);
	}
	var compTitle  = null;
	try {
		compTitle  = compObj.getTitle();
		if ( scutilo.isEmpty(compTitle) ) {
			compTitle = compObj.options.title;
		}
	}
	catch(e) {
		compTitle = compObj.getID();
	}
	_trace("[#valid1] component 정보 :: tagName = ["+ tagName +"], title = ["+ compTitle + "], 값 앞뒤공백여부 = " + (compValOrg!=compVal));

	if ( "input"==tagName || "textarea"==tagName ) {
		var doTrim = true; //값을 trim할지 여부
		var doClearXss = true; //값에서 xss 처리할지 여부
		var userData1 = compObj.getUserData("userData1"); //trim=false,xss=false (디폴트)

		try {
			var txobj = psputils.toJsonCommaEqual(userData1);
			doTrim = "true"==txobj["trim"]; //scutilo.isEmpty( txobj["trim"] ) ? true : ("true"==txobj["trim"]);
			doClearXss = "true"==txobj["xss"];
			_trace("[#valid1] JSON.stringify(userData1) ::= " + JSON.stringify(txobj));
		}
		catch(e) {
			doTrim = true;
			doClearXss = true;
			_trace("[#valid1] userData1 옵션없음. 디폴트값 사용. ["+ userData1 +"] (원인)" + e);
		}

		compVal = compObj.getValue(); //다시 원본으로 작업
		if (null==compVal) {
			compVal = "";
		}
		if ( doTrim ) {
			compVal = compVal.trim();
		}
		if ( doClearXss ) {
			//
			compVal = compVal.replace(/</g, '&lt;');
			compVal = compVal.replace(/>/g, '&gt;');
		}
		compObj.setValue(compVal);
	}
	else if ( "editor"==tagName ) {
		//위 참조 //compVal = compObj.getHTML();
	}
	else if ( "inputcalendar"==tagName ) {
		if ( ! scutilo.isEmpty(compVal) ) {
			var dt = scdateo.getDateObj(compVal);
			var yr = dt.getFullYear();
			if ( yr<1900 || yr>2120 ) { //허용년도 = 1900~2120
				_errobj["errObj"] = compObj;
				_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1005, compTitle, yr); //W_1005: "[<%s>] 항목의 데이터로 허용되지 않는 범위(<%s>)입니다.",
				return e_errobj;
			}

			if ( /[eE]nd/.test(compObj.getID()) ) {
				// 예) ipx_endYmd 이면, ipx_bgngYmd 객체
				var bgngObj = psputils.getComponentBgngByEnd(compObj);
				var bgngVal = null==bgngObj ? null : bgngObj.getValue();

				if ( ! scutilo.isEmpty(bgngVal) ) {
					try {
						var ib_ymd = parseInt(bgngVal);
						var ie_ymd = parseInt(compVal);
						if ( ie_ymd<ib_ymd ) {
							_errobj["errObj"] = compObj;
							_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1008, compTitle, bgngObj.options.title); //W_1008: "[<%s>] 날짜는 [<%s>] 날짜보다 미래의 날짜를 선택하세요."
							return _errobj;
						}
					}
					catch(e) {
						_trace("[#valid1] 시작~종료일 체크 오류. ["+ bgngVal +"]~["+ compVal +"] (원인)" + e);
					}
				}
			}
		}
	}
	else if ( "secret"==tagName ) {
		if ( scutilo.isNotEmpty(compVal) ) { //비밀번호 객체 기본검증, 추가적으로 검증해야 함
			//비밀번호 객체 기본검증, 추가적으로 검증해야 함
			/*
			var substr = ""; //debugger
				if ( ""==substr && ( psputils.hasSpace(compVal) || psputils.hasTab(compVal) ) ) { substr = "(공백 문자 제외)"; }
				if ( ""==substr && ! psputils.hasLower(compVal) ) { substr = "(소문자 필요)"; }
				if ( ""==substr && ! psputils.hasUpper(compVal) ) { substr = "(대문자 필요)"; }
				if ( ""==substr && ! psputils.hasSpecial(compVal) ) { substr = "(특수문자 필요)"; }
				if ( ""!=substr ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1006, compTitle, substr); //W_1006: "[<%s>] 항목의 데이터 형식을 확인후 입력하세요. <%s>",
					return _errobj;
				}
			*/
			//var errmsg = psputils.validPasswd(compVal); //debugger
			//@see below userData2
		}
	}

	var valcmdsize = 0;
	try {
		valcmdsize = compObj.validator.commandList.length;
	}
	catch(e) {
		valcmdsize = 0;
	}

	if ( 1 > valcmdsize ) {
		if ( "editor"==tagName ) {
			let isMandatory = false;
			if ( scutilo.isNotEmpty(compObj.options.mandatory) ) {
				isMandatory = eval(compObj.options.mandatory);
			}
			if ( true===isMandatory ) {
				let valWoBrNl = compVal.replace(/\<br\s*\/\>/g, '').replace(/\n/g, '').trim(); //개행만 있는 경우 체크
				if ( scutilo.isEmpty(valWoBrNl) ) {
					if ( scutilo.isEmpty(compTitle) ) {
						compTitle = "HTML 입력";
					}
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1001, ""+ compTitle +""); //W_1001:"[<%s>] 항목은 반드시 입력하세요.",
					return _errobj;
				}
			}
		}
		return null; //검증할 validation 옵션 없음
	}

	for(var valcmd of compObj.validator.commandList) {
		var valcmdtype = valcmd.getType();
		_trace("[#valid1] validator command type =", valcmdtype);

		if ( "mandatory"==valcmdtype ) {
			if ( true==valcmd["mandatory"] && scutilo.isEmpty(compVal) ) {
				_errobj["errObj"] = compObj;
				_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1001, ""+ compTitle +""); //W_1001:"[<%s>] 항목은 반드시 입력하세요.",
				return _errobj;
			}
		}
		else if ( "minLength"==valcmdtype ) {
			var minlen = valcmd["minLength"];
			if ( minlen>0 && minlen > compVal.length ) {
				_errobj["errObj"] = compObj;
				_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1002, ""+ compTitle +"", minlen); //W_1002: "[<%s>] 항목은 최소 <%s>자 이상 입력하세요.",
				return _errobj;
			}
		}
		else if ( "minByteLength"==valcmdtype ) {
			var minbytes  = valcmd["minByteLength"];
			var currbytes = psputils.getByteLength(compVal);
			if ( minbytes>0 && currbytes < minbytes ) {
				_errobj["errObj"] = compObj;
				var tmpMsg = scutilo.getMsg(pspmsg.PSP.W_1010, ""+ compTitle +"", minbytes, currbytes); //W_1010: "[<%s>] 항목은 최대 <%s> 바이트 이하 입력하세요. (참고) 현재  <%s> 바이트 입력됨.",
				_errobj["errMsg"] = tmpMsg.replace("항목은 최대", "항목은 최소").replace("이하로 입력하십시오", "이상 입력하십시오");
				return _errobj;
			}
		}
		else if ( "maxLength"==valcmdtype ) {
			var maxlen = valcmd["maxLength"];
			if ( maxlen>0 && maxlen < compVal.length ) {
				_errobj["errObj"] = compObj;
				_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1003, ""+ compTitle +"", maxlen); //W_1003: "[<%s>] 항목은 최대 <%s>자 이하 입력하세요.",
				return _errobj;
			}
		}
		else if ( "maxByteLength"==valcmdtype ) {
			var maxbytes  = valcmd["maxByteLength"]; // == valcmd.getValue()
			var currbytes = psputils.getByteLength(compVal);
			if ( maxbytes>0 && currbytes > maxbytes ) {
				_errobj["errObj"] = compObj;
				_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1010, ""+ compTitle +"", maxbytes, currbytes); //W_1010: "[<%s>] 항목은 최대 <%s> 바이트 이하 입력하세요. (참고) 현재  <%s> 바이트 입력됨.",
				return _errobj;
			}
		}
		else if ( "allowChar"==valcmdtype ) {
			var allowChar = valcmd["allowChar"]; // (ex) a-zA-Z0-9_.
			var regex = eval("/[" + allowChar + "]/");

			for(var x=0; x<compVal.length; x++) {
				if ( ! regex.test( compVal.charAt(x) ) ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1004, ""+ compTitle +"", compVal.charAt(x)); //W_1004: "[<%s>] 항목의 데이터로 허용되지 않는 문자(<%s>)입니다.",
					return _errobj;
				}
			}
		}
		else if ( "user"==valcmdtype ) {
			if ( null != valcmd.userFunc ) {
				_error("[#valid1] [주의] valcmdtype==user, valcmd.userFunc not null!.");
			}
		}
		else {
			_trace("[#valid1] [주의] validator command type =", valcmdtype);
		}
	}

	var userData2 = compObj.getUserData("userData2"); //추가로 호출함 함수명을 userData2에 설정
	if (scutilo.isNotEmpty(userData2)) {
		try {
			var _func = null;
			if ( userData2.startsWith("scwin.") ) {
				_func = eval('compObj.getScope().scope.' + userData2); //eval('$p.top().pfwork.scope.' + userData2);
			}
			else  {
				_func = eval(userData2);
			}
			if (scutilo.isFunction(_func)) {
				let eMsg =  _func.call(null, compVal);
				if ( ! scutilo.isEmpty(eMsg) ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = eMsg;
					return _errobj; //사용자 구현 함수에서 반환한 문자열이 오류 문자열임
				}
			}
			else {
				_error("[#valid1] [주의] userData2 ::= ", userData2, " (원인) 해당 함수를 참조할 수 없습니다! 다시 한번 확인하세요.");
			}
		}
		catch(e) {
			_error("[#valid1] [오류발생] userData2 ::=", userData2, " (원인)", e);
		}
	}
	return null; //검증 성공시 null을 반환
};

/**
 * 전달한 컴포넌트들의 validation을 진행하고 성공시 null 반환(@since 2023-05-02)
 * 오류가 발생시 해당 컴포넌트 참조하여 오류메시지르 반환
 *
 * @param	components		체크할 컴포넌트 또는 컴포넌트ID 배열
 * @param	subFrameId		pfwork 프레임하위의 컴포넌트ID (디폴트) 'mf_pfwork' (예) wfm_tab1 또는 mf_pfwork_wfm_tab1 둘다 가능
 * @param	doFocely		무조건 체크여부 (디폴트) false (예)컴포넌트가 [readOnly, disabled] 상태이면, 디폴트로 체크하지 않음
 * @return	그룹내 모든 컴포넌트들이 정상이면 null, 오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }
 * @see		validone(components, subFrameId, doFocely)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.12.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.validn = function(components, subFrameId, doFocely) {
	if ( null==components ) { return null; }

	var _errobj = { "errMsg":null, "errObj":null }; //검증시 오류가 있을 경우, [메시지, 대상객체]를 설정하여 반환

	if ( 'string' == typeof components ) {
		var arrCompId = components.split(",");

		for (var n=0; n<arrCompId.length; n++) {
			var compId = $.trim( arrCompId[n] );
			_errobj = psp.validone(compId, subFrameId, doFocely);
			if ( null!=_errobj ) {
				_info("[#validn] [검증] [오류반환] compId =", compId, "/ subFrameId :", subFrameId);
				return _errobj;
			}
		}
	}
	else if ( 'object' == typeof components && Array.isArray(components) ) {
		for (var i=0; i<components.length; i++) {
			_errobj = psp.validone(components[i], subFrameId, doFocely);
			if ( null!=_errobj ) {
				_info("[#validn] [검증] [오류반환] compId =", components[i]["id"], "/ subFrameId :", subFrameId);
				return _errobj;
			}
		}
	}
};

/**
 * 지정한 영역내의 값을 저당하는 모든 컴포넌트를 순회하면서, validate 조건에 부합하는지 체크함
 * 오류가 발생시 해당 컴포넌트 참조하여 오류메시지 표시후 false 반환
 *
 * 1) input, textarea 는 디폴트로 trim(), clearxss() 처리함 (노트) userData1 : trim, clearxss 처리하지 않을 경우 trim=false,xss=false
 * 2) inputcalendar 는 추가로 년도 범위 체크함(1900 ~ 2120)
 * 3) secret 기본적인 비밀번호 규칙 체크(길이, 대소문자, 특수문자)
 * 4) 컴포넌트의 validate항목을 다시 체크함(mandatory, minLength, maxLength, allowChar)
 * 5) 해당 컴포넌트 추가 validate : userData2 에 추가로 검증할 함수명 설정. 함수구현은 psputils.validPasswd(str) 참조
 *
 * @param	groupId		컴포넌트 검증할 그룹 컴포넌트의 ID문자열
 * @param	subFrameId	pfwork 프레임하위의 컴포넌트ID (예) wfm_tab1 또는 mf_pfwork_wfm_tab1 둘다 가능
 * @param	doFocely	(@2023-06-14추가) 무조건 체크여부 (디폴트) false (예)컴포넌트가 [readOnly, disabled] 상태이면, 디폴트로 체크하지 않음
 * @return	그룹내 모든 컴포넌트들이 정상이면 null, 오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.09.08.           [NELS]최초 생성
 *  2026.07.23.           [26A-PSP-0091] 각종 메시지 내용 및 안내문구 수정
 * ============= ============ ==========================
 */
psp.validate = function(groupId, subFrameId, doFocely) {
	var _errobj = { "errMsg":null, "errObj":null }; //검증시 오류가 있을 경우, [메시지, 대상객체]를 설정하여 반환
	//var elements2check = ['input','secret','textarea','selectbox', 'multiselect', 'checkbox', 'radio', 'autocomplete', 'inputcalendar' ];

	var groupObject = psp.componentById(groupId, subFrameId);

	for(var i=0; i<groupObject.getAllChildren().length; i++) {
		var compObj = groupObject.getAllChildren()[i];
		var tagName = compObj.options.pluginName.toLocaleLowerCase();
		if ( ! psp.VALID_TAGS.includes(tagName) ) {
			_trace("[psp.validate] skip validation on tag :", tagName);
			continue;
		}
		if ( null==doFocely || false==doFocely ) { //(@2023-06-14추가) 무조건 체크여부
			if ( true==compObj.getAttribute("disabled") || "true"==compObj.getAttribute("disabled") ||
				 true==compObj.getAttribute("readOnly") || "true"==compObj.getAttribute("readOnly") ) {
				_debug("[#validate] skip validation : ID=", compObj.getID(), ", disabled=", compObj.getAttribute("disabled"), ", readOnly=", compObj.getAttribute("readOnly"));
				continue; //(예)컴포넌트가 [readOnly, disabled] 상태이면, 디폴트로 체크하지 않음
			}
		}

		var isHide = psputils.isHide(compObj);
		if ( true==isHide ) {
			_debug("[#validate] skip validation : ID=", compObj.getID(), ", isHide =", isHide, "");
			continue;
		}

		var compValOrg = null;
		var compVal    = null;
		try {
			compValOrg = compObj.getValue();
			compVal    = null==compValOrg ? "" : compObj.getValue();
		}
		catch(e) {
			if ( "editor"==tagName ) {
				compValOrg = compObj.getHTML();
				compVal    = compObj.getHTML();
			}
		}

		try {
			compVal = compVal.trim();
		}
		catch(e) {
			_debug("[#validate] [error]", e);
		}
		var compTitle  = null;
		try {
			compTitle  = compObj.getTitle();
			if ( scutilo.isEmpty(compTitle) ) {
				compTitle = compObj.options.title;
			}
		}
		catch(e) {
			compTitle = compObj.getID();
		}
		_trace("[#validate] component 정보 :: tagName = ["+ tagName +"], title = ["+ compTitle + "], 값 앞뒤공백여부 = " + (compValOrg!=compVal));

		if ( "input"==tagName || "textarea"==tagName ) {
			var doTrim = true; //값을 trim할지 여부
			var doClearXss = true; //값에서 xss 처리할지 여부
			var userData1 = compObj.getUserData("userData1"); //trim=false,xss=false (디폴트)

			try {
				var txobj = psputils.toJsonCommaEqual(userData1);
				doTrim = "true"==txobj["trim"]; //scutilo.isEmpty( txobj["trim"] ) ? true : ("true"==txobj["trim"]);
				doClearXss = "true"==txobj["xss"];
				_trace("[psp.validate] JSON.stringify(userData1) ::= " + JSON.stringify(txobj));
			}
			catch(e) {
				doTrim = true;
				doClearXss = true;
				_trace("[psp.validate] userData1 옵션없음. 디폴트값 사용. ["+ userData1 +"] (원인)" + e);
			}

			compVal = compObj.getValue(); //다시 원본으로 작업
			if (null==compVal) {
				compVal = "";
			}
			if ( doTrim ) {
				compVal = compVal.trim();
			}
			if ( doClearXss ) {
				//
				compVal = compVal.replace(/</g, '&lt;');
				compVal = compVal.replace(/>/g, '&gt;');
			}
			compObj.setValue(compVal);
		}
		else if ( "editor"==tagName ) {
			//위 참조 //compVal = compObj.getHTML();
		}
		else if ( "inputcalendar"==tagName ) {
			if ( ! scutilo.isEmpty(compVal) ) {
				var dt = scdateo.getDateObj(compVal);
				var yr = dt.getFullYear();
				if ( yr<1900 || yr>2120 ) { //허용년도 = 1900~2120
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1005, compTitle, yr); //W_1005: "[<%s>] 항목의 데이터로 허용되지 않는 범위(<%s>)입니다.",
					return _errobj;
				}

				if ( /[eE]nd/.test(compObj.getID()) ) {
					// 예) ipx_endYmd 이면, ipx_bgngYmd 객체
					var bgngObj = psputils.getComponentBgngByEnd(compObj);
					var bgngVal = null==bgngObj ? null : bgngObj.getValue();

					if ( ! scutilo.isEmpty(bgngVal) ) {
						try {
							var ib_ymd = parseInt(bgngVal);
							var ie_ymd = parseInt(compVal);
							if ( ie_ymd<ib_ymd ) {
								_errobj["errObj"] = compObj;
								_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1008, compTitle, bgngObj.options.title); //W_1008: "[<%s>] 날짜는 [<%s>] 날짜보다 미래의 날짜를 선택하세요."
								return _errobj;
							}
						}
						catch(e) {
							_trace("[#validate] 시작~종료일 체크 오류. ["+ bgngVal +"]~["+ compVal +"] (원인)" + e);
						}
					}
				}
			}
		}
		else if ( "secret"==tagName ) {
			if ( scutilo.isNotEmpty(compVal) ) { //비밀번호 객체 기본검증, 추가적으로 검증해야 함
				/*
				var substr = ""; //debugger
				if ( ""==substr && ( psputils.hasSpace(compVal) || psputils.hasTab(compVal) ) ) { substr = "(공백 문자 제외)"; }
				if ( ""==substr && ! psputils.hasLower(compVal) ) { substr = "(소문자 필요)"; }
				if ( ""==substr && ! psputils.hasUpper(compVal) ) { substr = "(대문자 필요)"; }
				if ( ""==substr && ! psputils.hasSpecial(compVal) ) { substr = "(특수문자 필요)"; }
				if ( ""!=substr ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1006, compTitle, substr); //W_1006: "[<%s>] 항목의 데이터 형식을 확인후 입력하세요. <%s>",
					return _errobj;
				}
				*/
				//var errmsg = psputils.validPasswd(compVal); //debugger
				//@see below userData2
			}
		}

		var valcmdsize = 0;
		try {
			valcmdsize = compObj.validator.commandList.length;
		}
		catch(e) {
			valcmdsize = 0;
		}

		if ( 1 > valcmdsize ) {
			if ( "editor"==tagName ) {
				let isMandatory = false;
				if ( scutilo.isNotEmpty(compObj.options.mandatory) ) {
					isMandatory = eval(compObj.options.mandatory);
				}
				if ( true===isMandatory ) {
					let valWoBrNl = compVal.replace(/\<br\s*\/\>/g, '').replace(/\n/g, '').trim(); //개행만 있는 경우 체크
					if ( scutilo.isEmpty(valWoBrNl) ) {
						if ( scutilo.isEmpty(compTitle) ) {
							compTitle = "HTML 입력";
						}
						_errobj["errObj"] = compObj;
						_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1001, ""+ compTitle +""); //W_1001:"[<%s>] 항목은 반드시 입력하세요.",
						return _errobj;
					}
				}
			}
			continue;
		}

		for(var valcmd of compObj.validator.commandList) {
			var valcmdtype = valcmd.getType();
			_trace("[#validate] validator command type =", valcmdtype);

			if ( "mandatory"==valcmdtype ) {
				if ( true==valcmd["mandatory"] && scutilo.isEmpty(compVal) ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1001, ""+ compTitle +""); //W_1001:"[<%s>] 항목은 반드시 입력하세요.",
					return _errobj;
				}
			}
			else if ( "minLength"==valcmdtype ) {
				var minlen = valcmd["minLength"];
				if ( minlen>0 && minlen > compVal.length ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1002, ""+ compTitle +"", minlen); //W_1002: "[<%s>] 항목은 최소 <%s>자 이상 입력하세요.",
					return _errobj;
				}
			}
			else if ( "minByteLength"==valcmdtype ) {
				var minbytes  = valcmd["minByteLength"]; // == valcmd.getValue()
				var currbytes = psputils.getByteLength(compVal);
				if ( minbytes>0 && currbytes < minbytes ) {
					_errobj["errObj"] = compObj;
					var tmpMsg = scutilo.getMsg(pspmsg.PSP.W_1010, ""+ compTitle +"", minbytes, currbytes); //W_1010: "[<%s>] 항목은 최대 <%s> 바이트 이하 입력하세요. (참고) 현재  <%s> 바이트 입력됨.",
					_errobj["errMsg"] = tmpMsg.replace("항목은 최대", "항목은 최소").replace("이하로 입력하십시오", "이상 입력하십시오");
					return _errobj;
				}
			}
			else if ( "maxLength"==valcmdtype ) {
				var maxlen = valcmd["maxLength"];
				if ( maxlen>0 && maxlen < compVal.length ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1003, ""+ compTitle +"", maxlen); //W_1003: "[<%s>] 항목은 최대 <%s>자 이하 입력하세요.",
					return _errobj;
				}
			}
			else if ( "maxByteLength"==valcmdtype ) {
				var maxbytes  = valcmd["maxByteLength"]; // == valcmd.getValue()
				var currbytes = psputils.getByteLength(compVal);
				if ( maxbytes>0 && currbytes > maxbytes ) {
					_errobj["errObj"] = compObj;
					_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1010, ""+ compTitle +"", maxbytes, currbytes); //W_1010: "[<%s>] 항목은 최대 <%s> 바이트 이하 입력하세요. (참고) 현재  <%s> 바이트 입력됨.",
					return _errobj;
				}
			}
			else if ( "allowChar"==valcmdtype ) {
				var allowChar = valcmd["allowChar"]; // (ex) a-zA-Z0-9_.
				var regex = eval("/[" + allowChar + "]/");

				for(var x=0; x<compVal.length; x++) {
					if ( ! regex.test( compVal.charAt(x) ) ) {
						_errobj["errObj"] = compObj;
						_errobj["errMsg"] = scutilo.getMsg(pspmsg.PSP.W_1004, ""+ compTitle +"", compVal.charAt(x)); //W_1004: "[<%s>] 항목의 데이터로 허용되지 않는 문자(<%s>)입니다.",
						return _errobj;
					}
				}

			}
			else if ( "user"==valcmdtype ) {
				if ( null != valcmd.userFunc ) {
					_error("[#validate] [주의] valcmdtype==user, valcmd.userFunc not null!.");
				}
			}
			else {
				_trace("[#validate] [주의] validator command type =", valcmdtype);
			}
		}

		var userData2 = compObj.getUserData("userData2"); //추가로 호출함 함수명을 userData2에 설정한다.
		if (scutilo.isNotEmpty(userData2)) {
			try {
				var _func = null;
				if ( userData2.startsWith("scwin.") ) {
					_func = eval('compObj.getScope().scope.' + userData2); // (ex) eval('$p.top().pfwork.scope.' + userData2);
				}
				else  {
					_func = eval(userData2);
				}
				if (scutilo.isFunction(_func)) {
					errMesg =  _func.call(null, compVal);

					if ( null!=errMesg ) {
						_errobj["errObj"] = compObj;
						_errobj["errMsg"] = errMesg; //사용자 구현 함수에서 반환한 문자열이 오류 문자열임
						return _errobj;
					}
				}
				else {
					_error("[#validate] [주의] userData2 ::= ", userData2, " (원인) 해당 함수를 참조할 수 없습니다! 다시 한번 확인하세요.");
				}
			}
			catch(e) {
				_error("[#validate] [오류발생] userData2 ::=", userData2, " (원인)", e);
			}
		}
	}
	return null; //검증 성공시 null을 반환
};

/**
 * 지정한 여러개의 영역(그룹) 전체를 순회하면서 validate 조건에 부합하는지 체크함
 * (참조) psp.validate
 *
 * @param	groupId		그룹 ID문자열(콤마로 그룹ID 분리) (예) "grp1,grp2,grp3"
 * @param	subFrameId	pfwork 프레임하위의 컴포넌트ID (예) wfm_tab1 또는 mf_pfwork_wfm_tab1 둘다 가능
 * @return	여러개의 영역(그룹)내 모든 컴포넌트들이 정상이면 null, 오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.09.08.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.validates = function(groupIds, subFrameId) {
	if (null==groupIds || undefined==groupIds) {
		return false;
	}

	var arrGroupId = [];
	if ( "string" == typeof groupIds ) {
		arrGroupId = groupIds.split(",");
	}
	else if ( $.isArray(groupIds) ) {
		arrGroupId = groupIds;
	}
	else {
		return false;
	}

	var errInfo = null;

	for (var n=0; n<arrGroupId.length; n++) {
		var groupId  = arrGroupId[n];
		errInfo = psp.validate(groupId, subFrameId);
		if ( null!=errInfo ) {
			_info("[psp.validates] [검증] [오류반환] groupId =", groupId, "/ subFrameId :", subFrameId);
			return errInfo;
		}
	}
	return null;
};

/**
 * 오류가 발생한 경우, 오류메시지를 표시하며 결과(false)를 반환. 검증성공이면 true 반환
 *
 * @param	groupId		그룹 ID문자열(콤마로 그룹ID 분리) (예) "grp1,grp2,grp3"
 * @param	subFrameId	pfwork 프레임하위의 컴포넌트ID (예) wfm_tab1 또는 mf_pfwork_wfm_tab1 둘다 가능
 * @return	여러개의 영역(그룹)내 모든 컴포넌트들이 정상이면 null, 오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.09.08.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.validate_wm = function(groupId, doFocely) {
	var errInfo = psp.validate(groupId, null, doFocely); //오류이면 오류객체 { "errMsg":"오류메시지", "errObj":오류대상객체 }

	if ( null==errInfo || scutilo.isEmpty(errInfo["errMsg"]) ) {
		return true
	}

	var errCompId = errInfo["errObj"].getID();
	var cbparam = { popupName: "알림",
					data: { "objId": errCompId, }
				}; //callback param

	com.win.alert(errInfo["errMsg"], //오류메시지
					function(param) {
						//var obj = $p.getComponentById(param.data.objId); //@see callbackParam
						var obj = psp.componentById(param.data.objId);
						obj.focus();
					},
					cbparam);
	return false; //검증 실패
};

/**
 * 컴포넌트의 validation 속성값을 지정함 (예) "mandatory" or "minLength" or "maxByteLength" or "allowChar" 등
 * (참고) "userData2"는 validation 속성이 아님, compObj.setUserData("userData2", null);
 *
 * @param	compObj		지정할 컴포넌트 객체
 * @param	strOptNm	validation 속성명 (예) "mandatory" or "minLength" or "maxByteLength" or "allowChar" 등
 * @param	optVal		validation 속성값 (예) true, 10, 200,
 * @return	값이 설정된 경우, 설정값을 그대로 반환. 설정되지 않으면 null을 반환
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.25.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.setValidOpt = function(compObj, strOptNm, optVal) {
	if ( null==compObj ) { return null; }
	if ( scutilo.isEmpty(strOptNm) ) { return null; }
	if ( "mandatory"==strOptNm.toLowerCase() ) {
		//(주의) compObj.setMandatory(false) 하게 되면, commandList 목록에서 아예 삭제되어 버림. 이 경우 방지하는 코드
		for(var objCmnd of compObj.validator.commandList) {
			var cmndType = objCmnd.getType();
			if ( "mandatory"==cmndType ) {
				objCmnd["mandatory"] = optVal;
				return optVal;
			}
		}
		//현재 컴포넌트에 'mandatory' 옵션이 없는 경우임
	}
	var optValSet = null;
	try {
		switch(strOptNm.toLowerCase()) {
		case "mandatory": compObj.setMandatory(optVal); optValSet = optVal; break; //이 경우는 'mandatory' 설정도 추가해야함.
		case "maxlength": compObj.setMaxLength(optVal); optValSet = optVal; break;
		case "minlength": compObj.setMinLength(optVal); optValSet = optVal; break;
		case "maxbytelength": compObj.setMaxByteLength(optVal); optValSet = optVal; break;
		case "minbytelength": compObj.setMinByteLength(optVal); optValSet = optVal; break;
		default: optValSet = null; break;
		}
	}
	catch(e) {
		optValSet = null;
		_error(`[#s.valid.opt] 옵션명 = '${strOptNm}', 오류 : ${e.message}`);
	}
	return optValSet;
};

/**
 * 컴포넌트의 validation 속성값 조회
 * (주의) 대소문자 가리지 않도록 함.
 *
 * @param	compObj		지정할 컴포넌트 객체
 * @param	strOptNm	조회할 검증 속성명 ( 'mandatory' | 'maxlength' | 'minlength' | 'maxByteLength' | 'minByteLength' )
 * @return	현재 검증 속성값. 없으면 null이 반환된
 * @see		psp.setValidOpts(compObj, validOpts)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.28.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getValidOptVal = function(compObj, strOptNm) {
	if ( null==compObj ) { return null; }
	if ( scutilo.isEmpty(strOptNm) ) { return null; }

	for(var objCmnd of compObj.validator.commandList) {
		var sCmndType = objCmnd.getType(); //"mandatory" or "minLength" ... 등

		if ( strOptNm.toLowerCase() == sCmndType.toLowerCase() ) {
			return objCmnd[sCmndType];
		}
	}
	_warn(`[#g.vld.opt.v] 검증 옵션('${strOptNm}') 없음!`);
	return null;
};

/**
 * 컴포넌트의 validation 속성값들은 조회하여 객체로 반환
 *
 * @param	compObj		지정할 컴포넌트 객체
 * @return	현재 검증 속성값 객체 (주의) validation 속성이 설정되지 않으면, 값이 null로 설정됨
 * @see		psp.getValidOptVal(compObj, strOptNm)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.28.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getValidOptVals = function(compObj) {
	if ( null==compObj ) { return null; }
	//(주의) validation 속성이 설정되지 않으면, 값이 null로 설정됨
	return {
		"mandatory": psp.getValidOptVal(compObj, "mandatory"),
		"maxlength": psp.getValidOptVal(compObj, "maxlength"),
		"minlength": psp.getValidOptVal(compObj, "minlength"),
		"maxByteLength": psp.getValidOptVal(compObj, "maxByteLength"),
		"minByteLength": psp.getValidOptVal(compObj, "minByteLength"),
		"userData2": compObj.getUserData("userData2"), //개발자가 추가로 지정했던 검증함수가 있으면 백업
	};
};

/**
 * 컴포넌트의 validation 속성값을 전체 제거함
 * (관련속성) ( 'mandatory', 'maxlength', 'minlength', 'maxByteLength', 'minByteLength', 'userData2' )
 * (참고) "userData2"의 값도 제거함
 *
 * @param	compObj		지정할 컴포넌트 객체
 * @return	제거된 validation 속성정보 및 userData2 속성
 * @see		psp.setValidOpts(compObj, validOpts)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.25.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.clearValidOpts = function(compObj) {
	if ( null==compObj ) { return null; }
	var currOpts = psp.getValidOptVals(compObj); //

	//젠장한 WS대소문자...API확인/사용시 주의
	if ( null != currOpts['mandatory'] ) { //( null!=currOpts["mandatory"] && false!=currOpts["mandatory"] )
		psp.setValidOpt(compObj, "mandatory", false);
	}
	if ( null != currOpts["maxlength"] && currOpts["maxlength"] > -1 ) { //( null!=currOpts["maxlength"] && currOpts["maxlength"]>-1 )
		psp.setValidOpt(compObj, "maxLength", "");
	}
	if ( null != currOpts["minlength"] && currOpts["minlength"] > -1 ) {
		psp.setValidOpt(compObj, "minLength", "");
	}
	if ( null != currOpts["maxByteLength"] && currOpts["maxByteLength"] > -1 ) {
		psp.setValidOpt(compObj, "maxByteLength", "");
	}
	if ( null != currOpts["minByteLength"] && currOpts["minByteLength"] > -1 ) {
		psp.setValidOpt(compObj, "minByteLength", "");
	}
	if ( null != currOpts["userData2"] ) {
		compObj.setUserData("userData2", null); //개발자가 추가로 지정했던 검증함수가 있으면 백업(반환되는 파라미터 저장후 복원)
	}
	return currOpts;
};

/**
 * 컴포넌트의 validation 속성값을 전체적으로 다시 설정함
 * (참고) "userData2"의 값도 있으면 설정
 *
 * @param	compObj		지정할 컴포넌트 객체
 * @param	validOpts	validation 속성 정보 전체
 * @see		psp.clearValidOpts(compObj)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.25.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.setValidOpts = function(compObj, validOpts) {
	if ( null==compObj || null==validOpts ) { return null; }

	if ( null!=validOpts["mandatory"] ) {
		psp.setValidOpt(compObj, "mandatory", validOpts["mandatory"]);
	}
	if ( null!=validOpts["maxlength"] && validOpts["maxlength"]>-1 ) {
		psp.setValidOpt(compObj, "maxLength", validOpts["maxlength"]);
	}
	if ( null!=validOpts["minlength"] && validOpts["minlength"]>-1 ) {
		psp.setValidOpt(compObj, "minLength", validOpts["minlength"]);
	}
	if ( null!=validOpts["maxByteLength"] && validOpts["minByteLength"]>-1 ) {
		psp.setValidOpt(compObj, "maxByteLength", validOpts["minByteLength"]);
	}
	if ( null!=validOpts["minByteLength"] && validOpts["minByteLength"]>-1 ) {
		psp.setValidOpt(compObj, "minByteLength", validOpts["minByteLength"]);
	}
	if ( scutilo.isNotEmpty(validOpts["userData2"]) ) {
		compObj.setUserData("userData2", validOpts["userData2"]);
	}
	return;
};

/**
 * 현재 세션이 유효한지 판단
 * 1. 로컬저장 세션 확인
 * 2. 필요시 서버 세션 확인
 * @param	withSvr		디폴트 서버세션도 확인(null 또는 true시)
 * @return	유효한 세션이면 true
 * @see		psp.getSession()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.11.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.isValidSesn = function(withSvr) {
	var isVld = psp.ss.hasData(psp.LS_KEY_USER);
	if ( false==isVld ) {
		_debug("[#ivs] 세션 유효?", isVld);
		return isVld;
	}
	if ( null!=withSvr && false==withSvr ) { //디폴트 서버도 체크
		return isVld;
	}
	var k = "elpUserId"; //,loginType,elpUserTypCd,uprUserId
	var v = psp.getSession(k);
	isVld = ! scutilo.isEmpty(v);
	_debug(`[#ivs] (서버)세션 유효? '${isVld}', '${k}':'${v}'`);
	return isVld;
};

/**
 * 전달된 사용자정보를 클라이언트에 저장
 * 1. 로컬스토리지 이용
 * 2. 필요시 데이터 암호화 기능
 *
 * @param	objUserInfo	저장할 사용자정보(객체 또는 문자열)
 * @return	저장성공시 true
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.31.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp._setClntSesn = function(objUserInfo) {
	if ( null==objUserInfo ) {
		return false;
	}
	psp.ss.set(psp.LS_KEY_USER, objUserInfo);
	return true;
};
psp._getClntSesn = function(key) {
	var objUserInfo = psp.ss.get(psp.LS_KEY_USER, true);
	if ( null==objUserInfo ) {
		return null;
	}
	return scutilo.isEmpty(key) ? objUserInfo["elpUserId"] : objUserInfo[key];
};
psp._updtClntSesns = function(objNewUserInfo) {
	var objUserInfo = psp.ss.get(psp.LS_KEY_USER, true);
	if ( null==objUserInfo ) {
		return -2;
	}
	var keys = [];
	for (const [key, value] of Object.entries(objNewUserInfo)) {
		objUserInfo[key] = value; //키의 값을 갱신/또는/추가
//		console.log(`[#_updtClntSesns] '${key}' : '${value}'`);
		keys.push(key);
	}
	psp.ss.set(psp.LS_KEY_USER, objUserInfo);

    //[스토리지공유]동일 도메인의 다른 탭에 로그인 요청(2024-03-26)
    psp.ls.set("UPDATING_CREDENTIALS", psp.ss.get(psp.LS_KEY_USER, true));
    psp.ls.remove("UPDATING_CREDENTIALS");
    _info("[#_updtClntSesns][공유]UPDATING_CREDENTIALS 요청");

	return keys;
};
psp._updtClntSesn = function(key, value) {
	var objUserInfo = psp.ss.get(psp.LS_KEY_USER, true);
	if ( null==objUserInfo ) {
		return -2;
	}
	var result = objUserInfo.hasOwnProperty(key) ? 1 : 0;
	objUserInfo[key] = value; //키의 값을 갱신/또는/추가
//	console.log(`[#_updtClntSesn] '${key}' : '${value}' (반환값:1=키값갱신, 0=키값추가) = '${result}'`);
	psp.ss.set(psp.LS_KEY_USER, objUserInfo);

    //[스토리지공유]동일 도메인의 다른 탭에 로그인 요청(2024-03-26)
    psp.ls.set("UPDATING_CREDENTIALS", psp.ss.get(psp.LS_KEY_USER, true));
    psp.ls.remove("UPDATING_CREDENTIALS");
    _info("[#_updtClntSesn][공유]UPDATING_CREDENTIALS 요청");

	return result; //1=키값갱신, 0=키값추가
};


/**
 * 로그인후 저장된 세션 정보중 원하는 키에 해당하는 값을 반환. 키가 지정되지 않으면, 아이디를 반환
 * (노트) 원인코드가 1이하이면, 로그아웃이후로 전체메뉴 정보를 다시 조회함.
 *
 * @param	causeCode	무효화 원인코드 (0=로그아웃, 1=로그아웃처리오류, 2=세션조회후없음, ...)
 * @return	삭제된 사용자정보
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp._clearClntSesn = function(causeCode) {
	_debug("[#_c.c.s] 클라이언트 세션 무효화. causeCode =", causeCode);
	var ssInfo = null;
	try {
		ssInfo = psp.ss.get(psp.LS_KEY_USER, true);
		psp.ss.remove(psp.LS_KEY_USER); //psp_user
		psp.ss.remove(psp.LS_KEY_MN_F); //psp_favmenu
		WebSquare.cookie.delCookie("SCOTKN");

		//쿠키제거(2024-03-11) : LAT, TTL, TTI
		if (null!=causeCode && 2>causeCode) {
			_debug("[#_c.c.s] 메뉴 재조회");
			psp.get_allmenu_list(true);
		}
		//중복로그인 Redis Key제거(2024-05-23)
		if (null!=causeCode && 9==causeCode) {
			_debug("[#_c.c.s] 중복로그인 Redis Key제거");
			psp.delSessionUser();
		}

	}
	catch(e) {
		_error("[#_c.c.s]", e.message);
		ssInfo = null;
	}
	return ssInfo;
};


/**
 * 서버측 세션 정보중 모두 조회하여 반환. 콜백함수가 지정되면 async로 호출하고 해당 콜백함수를 호출
 *
 * @param	callback	조회후 호출할 콜백함수(파라미터 1개, json객체)
