psp.getSessionUser = function(callback) {
    var _mode = "synchronous";
    var ssUsr = null;
    //debugger
    if ( null!=callback && 'function'== typeof callback ) {
        _mode = "asynchronous";
    }
    var param = {
        "dma_ssreq" : {
            "n":psp.session('userRandNo'),
            "e":"true"
        }
    };

	//client 세션값 체크 추가
    if(!psp.ss.hasData(psp.LS_KEY_USER)) {
        psp._clearClntSesn();
        return null;
    }

    try {
        var url = psp.CONTEXT_ROOT + "/psp001/getSessionUser.on";
        com.executeAjax({
            action: url,
            mode: _mode,
            method: 'POST',
            mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
            requestData: JSON.stringify(param),
            success: function(_data) {
                ssUsr = _data.responseJSON.data.dma_ssresp;
                respCode = _data.responseJSON.data.respCode;
