/**
 * 세션값 [ ownAtho, ownAthoTxt ]를 기준으로 권한을 가지고 있으면 true 반환
 *
 * @param	athoCd	조회할 권한코드 (예) 10, 20, ..., 70
 * @return	해당 권한이 있으면 true
 * @see		psp.session("ownAtho")
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.hasAtho = function(athoCd) {
    var ownAtho = psp.session("ownAtho");
    if ( scutilo.isEmpty(athoCd) || scutilo.isEmpty(ownAtho) ) {
        _warn("[권한조회] Login First!");
        return false; //세션없음.
    }
    var _hasAtho = false;
    try {
        var blen = psputils.getByteLength( athoCd.trim() );

        if ( blen < 3 ) { //숫자 10, 20, ..., 50, 60, 70
            var athoval = null;
            try {
                var idx = athoCd.trim().charAt(0) - '1';
                _hasAtho = '1' == ownAtho.charAt(idx) ? true : false;
            }
            catch(e) {
                _hasAtho = false;
                _error("[권한조회 오류]", e.description, "(입력 코드)", athoCd.trim());
            }
        }
        else {
            var ownAthoTxt = psp.session("ownAthoTxt"); //"전자제출=1,송달확인=1,사건정보조회=1,전자납부=1,각종서명=1,당사자조회=0,형사사건조회=0"
            try {
                var idx = ownAthoTxt.indexOf( athoCd.trim() );
                if (idx>0) {
                    var x = ownAthoTxt.indexOf("=", idx) + 1;
                    var y = ownAthoTxt.indexOf(",", idx); if ( y < 0 ) { y = x+1; }
                    var chr = ownAthoTxt.substring(x, y);
                    _hasAtho = "1"==chr ? true : false;
                }
            }
            catch(e) {
                _hasAtho = false;
                _error("[권한조회 오류]", e.description, "(입력 코드)", athoCd.trim());
            }
        }
    }
    catch(e) {
        _hasAtho = false;
        _error("[권한조회 오류]", e.description, "(입력 코드)", athoCd.trim());
    }
    return _hasAtho;
};

/**
 * 인증서 로그인하기위해 이동
 *
 * @param	doCheckAlert			true 이면 메시지창 표시후 이동
 * @param	addParamObj.comp		함수 호출한 웹스퀘어 컴포넌트 (취소 시 focus할 컴포넌트)
 * @param	addParamObj.callback	인증서 로그인 성공 시 호출 할 콜백함수
 * @see		psp.toCertLoginForcely()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.14.   안종광        [NELS]최초 생성
 *  2024.08.12.   백인호        취소 시 focus 기능 추가
 * ============= ============ ==========================
 */
psp.toCertLogin = function(doCheckAlert, addParamObj) {
	let comp = null; // 화면에서 본 함수 호출한 웹스퀘어 컴포넌트
	let callback = null;
	if (addParamObj != null && typeof addParamObj === "object") {
		if (addParamObj["comp"] != null && typeof addParamObj["comp"] === "object") {
			comp = addParamObj["comp"];
		}
		if (addParamObj["callback"] != null && typeof addParamObj["callback"] === "function") {
			callback = addParamObj["callback"];
		}
	}

	var loginType = psp.session("loginType");

    if ( "P"== loginType) {
        _debug("[인증서로그인이동] 이미 인증서 로그인되어 있음");
        scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(pspmsg.PSP.I_0077));
        return; //이미 인증서 로그인됨
    }
    if ( null!=doCheckAlert && true==doCheckAlert ) {

    	var oSSMA = Object.assign({}, null);
	    oSSMA["statCode"] = "NEED_INTG_LGN";

    	if ( "G"==loginType ) {
    		oSSMA["statCode"] = "NEED_CERT_LGN";
    	}

	    psp.open_popup("PSPMAMP01", "로그인 안내", oSSMA, 385, 255, function(rslt) {
	        if ( null==rslt || scutilo.isEmpty(rslt.loginType) ) { //취소
	            return false;
	        }
	        if ( "G"==loginType ) {
	        	$p.top().pfheader.scope.scwin.certLgnWithSesn(callback);
	        } else {
	        	psp.go_url("PSP101M01", null);
	        }

	        return false;
	    });
    }
    else {
        psp.toCertLoginForcely();
    }
};

