/**
 * Submission 객체를 동적으로 생성한다.
 *
 * (디폴트1) encoding  = "utf-8"
 * (디폴트2) mediatype = "application/json"
 * (디폴트3) mode      = "asynchronous"
 *
 * @param objOpt 서브미션 옵션설정(객체) (옵션사항이며, 지정하지 않으면, 디폴트값으로 설정됨)
 *               {
 *                          "mediatype" : "", //미디어타입지정 (디폴트) "application/json"
 *                          "mode"      : "", //서버와의 통신 방식. (디폴트) "asynchronous" (or) "synchronous"
 *                          "method"    : "", //HTTP메소드.  (디폴트) "post" (or) "get" (or) ...
 *                          "instance"  : "", //instance 지정. (디폴트) "none"
 *                          "processMsg": "", //메시지 문자열 지정. (디폴트) ""(없음)
 *                          "errorHandler" : "", //에러처리 핸들러 함수 지정, (디폴트) 없음
 *                          "submitHandler": "", //submit 핸들러 함수 지정, (디폴트) 없음
 *               }
 * @param sbmId     submission 객체의 ID
 * @param sRef      서버로 보낼(request) DataCollection의 조건 표현식.(조건에 때라 표현식이 복잡하다) 또는 Instance Data의 XPath.
 * @param sTarget   서버로 응답(response) 받은 데이터가 위치 할 DataCollection의 조건 표현식. 또는 Instance Data의 XPath.
 * @param sAction   통신 할 서버 측 URI (예) "/psp/pspLawDocMain/selectDocmtBas.on"
 * @param sScopeId  스코프ID문자열 (예) "mf_pfwork"
 * @param doneHndlr {script type="javascript" ev:event="xforms-submit-done"} 에 대응하는 함수
 *
 * @see   com.createSubmission(options)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.01.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.createSbm = function(objOpt, sSbmId, sRef, sTarget, sAction, sScopeId, doneHndlr) {
	var option = Object.assign({}, objOpt);
	var scopeId = psp.getScope(sScopeId); //null==sScopeId ? "mf_pfwork" : (scutilo.isString(sScopeId) ? sScopeId : sScopeId.id);

	if ( scutilo.isNotEmpty(sSbmId)  ) { option["id"]      = sSbmId; }
	if ( scutilo.isNotEmpty(sRef)    ) { option["ref"]     = sRef; }
	if ( scutilo.isNotEmpty(sTarget) ) { option["target"]  = sTarget; }
	if ( scutilo.isNotEmpty(sAction) ) { option["action"]  = sAction; }
	if ( scutilo.isNotEmpty(sScopeId)) { option["scopeId"] = scopeId; } //실제 submission에는 사용하지 않지만 저장해둠

	if ( scutilo.isEmpty(option["mode"])      ) { option["mode"]      = gcm.DEFAULT_OPTIONS_MODE;      }    // "asynchronous"
	if ( scutilo.isEmpty(option["mediatype"]) ) { option["mediatype"] = gcm.DEFAULT_OPTIONS_MEDIATYPE; }    // "application/json"
	if ( scutilo.isEmpty(option["method"])    ) { option["method"]    = "post"; }    //
	if ( scutilo.isEmpty(option["encoding"])  ) { option["encoding"]  = "UTF-8"; }   //
	if ( scutilo.isEmpty(option["instance"])  ) { option["instance"]  = "none"; }   //

	if ( null!=doneHndlr ) {
		var submitDoneHandler = (typeof doneHndlr === "function") ? doneHndlr
								: ((typeof doneHndlr === "string") ? doneHndlr : ""); //$p.id +
		option["submitDoneHandler"] = submitDoneHandler;
	}

	//체크 : [id, action]은 필수설정
	if ( scutilo.isEmpty(option["id"])     ) { _error("[#createSbm] NO object ID!"); return null; }  // 오류시 여기서 반환
	if ( scutilo.isEmpty(option["action"]) ) { _error("[#createSbm] NO action url!"); return null; } // 오류시 여기서 반환

	var scopeObj = psp.getScope(sScopeId);
	/*try {
		scopeObj = $p.getComponentById(scopeId);
	}
	catch(e) {
		scopeObj = $p.getComponentById("mf_pfwork");
	}*/
	scopeObj.$p.createSubmission(option);

	var sbmObj = scopeObj.$p.getComponentById( option["id"] );
	_debug("[#createSbm] submission created. ID = ", sbmObj.id);

	return sbmObj;
};


/**
 * 프로미스이용한 서브미션의 비동기 처리
 * (참고) 사용예는 개발예제화면 참조
 *
 * @param sbmId     submission 객체의 ID
 * @param reqData   executeSubmission의 요청데이터(대부분 사용하지 않음)
 * @param obj       executeSubmission의 객체(대부분 사용하지 않음)
 * @see   $p.executeSubmission(sbmId, reqData, obj)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.19.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.submit = function(sbmId, reqData, obj) { //
	return new Promise(function(resolve) {
		var sub = $p.getSubmission(sbmId);
		if (sub.userEventList === undefined) {
			sub.userEventList = [new WebSquare.Events.XmlEvent("xforms-submit-done", "script", {handler:resolve})];
		}
		else {
			var submitdone = sub.userEventList.find(function(o){return o.name === "xforms-submit-done";});
			submitdone.param.handler = resolve;
		}
		$p.executeSubmission(sbmId, reqData, obj);
	});
};


/**
 * 전달된 '스코프윈도우' 객체를 탐색하여
 * 'viewid'를 포함하는 [프로그램 파라미터] 객체를 구하여 반환한다.
 *
 * (노트) 만약 '컴포넌트' 객체가 없으면 pfheader 기준
 *
 * @param	component	웹스퀘어 컴포넌트 객체 (submission, trigger 등 가능)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.12.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getPgmParam = function(scopeWindow) {
	if (null==scopeWindow) { return null; }
	if (null==scopeWindow.scwin) {
		return null;
	}

	var pgmParam = null;
	//#1. 전달된 스코프ID 우선
	try {
		var arr = Object.entries(scopeWindow.scwin).filter( arr => 'function' != typeof arr[1]).filter( arr => '$w' != arr[0]);
		for(let i=0; i<arr.length; i++) { //arr[0] :: ['pageparam', {…}]
			let varName = arr[i][0]; //string
			let varVal  = arr[i][1]; //object
			if ( null==varVal ) {
				continue;
			}
			if ( varVal['viewid'] && varVal['viewtype'] ) { // viewid, viewname, viewtype, && {menuinfo}
				pgmParam = Object.assign({}, varVal);
				pgmParam['_var_name'] = varName;
				break;
			}
//			$w          : object
//			pageparam   : object
//			smaInfo     : object
//			onpageload  : function
//			dmfn_authed : function
		}
	}
	catch(e) {
		pgmParam = null;
		_warn("[#g.p.p] (cause)", e.message);
	}
	_debug("[#g.p.p] ", (null==pgmParam ? "<NULL>" : pgmParam['_var_name']), pgmParam);
	return pgmParam;
};

/**
 * 전달된 컴포넌트를 기준으로
 * 1. 현재 화면(메인)의 상단에 포함된 scwin.smaInfo
 * 2. 부모 화면의 상단에 포함된 scwin.smaInfo
 * 3. pfheader에 포함된 scwin.SMA_INFO
 * 순으로 객체를 조회하여 반환.
 *
 * (노트) 만약 '컴포넌트' 객체가 없으면 pfheader 기준
 *
 * @param	component	웹스퀘어 컴포넌트 객체 (submission, trigger 등 가능)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.12.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getSmaInfo = function(compOrObj) {
	var objSMA = null;
	try {
		if ( 'submission'==compOrObj._pluginName || scutilo.isNotEmpty(compOrObj._wTagName) ) {
			if ( compOrObj.getScopeWindow().scwin && compOrObj.getScopeWindow().scwin.smaInfo ) {
				objSMA = compOrObj.getScopeWindow().scwin.smaInfo;
				objSMA['_scope'] = 'main';
			}
			else if (compOrObj.getScopeWindow().$p.getParentWindow().scwin && compOrObj.getScopeWindow().$p.getParentWindow().scwin.smaInfo) {
				objSMA = compOrObj.getScopeWindow().$p.getParentWindow().scwin.smaInfo;
				objSMA['_scope'] = 'wframe';
			}
		}
		else {
			if ( 'object' == typeof obj && compOrObj['elpUserId'] ) {
				objSMA = Object.assign({}, compOrObj);
				objSMA['_scope'] = 'itself';
			}
		}
	}
	catch(e) {
		objSMA = null;
		_warn("[#g.sma] (cause)", e.message);
	}
	try {
		if ( null==objSMA ) {
			objSMA = $p.top().pfheader.scope.scwin.SMA_INFO;
			objSMA['_scope'] = 'header';
		}
	}
	catch(e) {
		objSMA = null;
		_warn("[#g.sma] (cause)", e.message);
	}
	return objSMA;
};


/**
 * 헤더에 {사용자ID} 값을 설정
 * (주의사항) 프로그램ID는 여기서 설정하면 적용안됨. 반드시 화면 onload()에서 scscrno.setScPgmId(pid) 설정
 *
 * @param	uidOrComp	지정된 사용자아이디 또는 화면컴포넌트 객체(이경우 세션을 추적하여 사용자아이디 구함)
 * @param	pgmId		프로그램아이디 (예) 'PSP001M01'
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.11.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.setHeader = function(uidOrComp, pgmId) {
	let objSMA = psp.getSmaInfo(uidOrComp);
	let usrid = ""; //scutilo.isNotEmpty(userId) ? userId : psp.session();
	let pgmid = "" || pgmId;
	let src   = null;
	let smaScope = null==objSMA ? "" : objSMA['_scope'];
	let pgmParam = null;

	try {
		if ( objSMA ) {
			usrid = objSMA['elpUserId'];
			src =  "(sma_" + smaScope + ")";
		}
		if ( 'string' == typeof uidOrComp ) {
			usrid = ""+uidOrComp;
			src =  "(param)";
		}
		if ( scutilo.isEmpty(usrid) ) {
			usrid = psp.session();
			src =  "(sesn)";
		}

		if ( scutilo.isEmpty(pgmid) && scutilo.isNotEmpty(smaScope) ) {
			if ( "main"==smaScope || "wframe"==smaScope ) {
				pgmParam = psp.getPgmParam( uidOrComp.getScopeWindow() );
				pgmid = null==pgmParam ? null : pgmParam['viewid'];
				if ( scutilo.isEmpty(pgmid) ) {
					pgmParam = psp.getPgmParam( uidOrComp.getScopeWindow().$p.getParentWindow() );
					pgmid = pgmParam['viewid'];
				}
			}
			if ( scutilo.isEmpty(pgmid) ) {
				pgmid = psputils.urlparams("s");
				if ( scutilo.isEmpty(pgmid) ) {
					pgmid = psputils.urlparams("m");
				}
			}
		}
		if ( scutilo.isEmpty(pgmid) ) {
			_warn("[#s.H] pgmId 없음. scscrno.setScPgmId() 호출 확인 필요함!");
		}
	}
	catch(e) {
		_error("[#s.H]", e.message);
	}

	//관리자인 경우 프로그램ID로 판단해서 사용자아이디 조회. (2024-02-26)
	try {
		var scReqHds = null==uidOrComp ? {} : uidOrComp.getScopeWindow().scscrno.getScRequestHeaders();
		if(scReqHds["SC-Pgmid"] != null && scReqHds["SC-Pgmid"].substr(3,1) == "9") {
			usrid = pspadmin.session();
		}
	} catch(e) {
		_error("[#s.H] (관리자체크)", e.message);
	}

	if ( scutilo.isEmpty(usrid) ) {
		usrid = "anonymous";
	}
	scglblo.setScUserId( usrid );

	var trcid = usrid;
	var headerInfo = {};
		headerInfo["SC-Userid"] = usrid; // psp.C.REQH_KEY_USRID
	if ( scutilo.isNotEmpty(pgmid) ) {
		headerInfo["SC-Pgmid"] = pgmid;
		trcid = `${pgmid}@${usrid}`;
	}
		headerInfo["SC-Traceid"] = trcid;
	_debug('[#s.H] headerInfo :', headerInfo);

	return headerInfo;
};

psp.setMySuitCount = function(cntMyCs) {
	let usrid = psp.session();

	if ( scutilo.isNotEmpty(usrid) ) {
		$p.top().pfright.scope.spn_cntIng.setLabel("<b>" + psputils.putComma(cntMyCs) + "</b> 건");
		psp._updtClntSesn("cntMyCs", cntMyCs);
