 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.08.   백인호        [NELS]최초 생성
 *  2024.12.02.   김영규        [NELS]분기 추가
 * ============= ============ ==========================
 */
psp.windowOpen = function(url, arg, opts) {
	console.log('#################### [psp.windowOpen :: psp.isMobileApp()] ' + psp.isMobileApp());
    if (psp.isMobileApp() === true) { // 모바일 웹접근성 외부 브라우저 연결 위한 처리
    	// 조건 체크 시 psp.env.isMobile()은 태블릿에 적용이 안되므로 psp.env.isMobileApp()로 변경 (24-11-09)
    	// 조건 체크 시 psp.env.isMobileApp()는 팝업에서 참조에러 발생한다고 하여 psp.isMobileApp으로 변경 (24-11-13)
    	// 이미 열린 팝업에서 팝업을 오픈할 경우 안드로이드,ios 별 팝업오픈 코드 적용
    	console.log('#################### [psp.windowOpen :: psp.isPopupInMobileApp()] ' + psp.isPopupInMobileApp());
    	if (psp.isPopupInMobileApp()) {
    		console.log('#################### [psp.windowOpen :: navigator.userAgentData] ' + navigator.userAgentData);
    		if (navigator.userAgentData) {	// 안드로이드OS인 경우
    			subWebview.openBrowser(url);
    		} else {		// 안드로이드OS가 아닌 경우 (window, ios 등)
    			// 아이폰인 경우
    			console.log('#################### [psp.windowOpen :: navigator.platform] ' + navigator.platform);
    			if (navigator.platform == 'iPhone') {
    				window.webkit.messageHandlers.subWebview.postMessage(url);
    			}
    		}
    	} else {
    		// 모바일 웹접근성 외부 브라우저 연결
    		$h.misc.openBrowser((result) => {
//    			console.log(result)
    		},{"url": url});
    	}


    } else {
    	arg = scutilo.isEmpty(arg) ? '_blank' : '';
    	// 새창 열기
        window.open (url, arg, opts);
    }
}

