 * 모바일 환경에서 보이는 탭에 대응되는 아코디언 hide 처리
 *
 * 웹스퀘어 엔진에서 동적으로 생성한 탭에 대응되는 아코디언에 대해 hide 처리가 제대로 되지 않아 모바일 오픈 전 임시 조치를 위해 만든 함수.
 * 웹스퀘어 문의 필요.
 * 해당 함수는 임시 방편으로 하드코딩으로 조치할 것이 아니라, 웹스퀘어 엔진에서 hide된 탭에 대해서도 고려하여 아코디언 보이지 않도록 처리가 필요해보임.
 * 인라인 스타일로 display none !important 주더라도 계속해서 인라인 스타일 리프레시 되어 의미가 없음.
 * 그냥 "dsN" 클래스 주더라도 앞에 "w2tabcontrol_contents" 클래스 때문에 "dsN" 클래스가 먹히지 않음.
 * 그래서 "w2tabcontrol_contents" 클래스 제거도 함께 필요.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.03.09.   백인호       [NELS]최초 생성
 * ============= ============ ==========================
 *
 */
psp.hideTabContentForMobile = function (id) {
    try {
        document.getElementById(id).classList.remove("w2tabcontrol_contents");
        document.getElementById(id).classList.add("dsN");
    } catch(e) {
        _error("psp.hideTabContentForMobile 에러", e.stack);
    }
}

/**
 * 앱 실행여부 체크. (개발환경을 위한 함수)
 * 가능한 해당로직이 아닌 psp.env.isMobileApp() 사용바랍니다.(psputils.js)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.11.   김영규        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.isMobileApp = function() {
	//인스웨이브의 WHybrid App에서 실행했는지 여부
	return navigator.userAgent.includes('whybridscourt');
};

/**
 * 스마트폰 여부 체크 (접속단말기가 스마트폰인 경우 true, 그 외(pc, 태블릿 등) false ) (개발환경을 위한 함수)
 * 가능한 해당로직이 아닌 psp.env.isMobile() 사용바랍니다.(psputils.js)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.13.   김영규        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.isMobile = function() {
	// 스마트폰 OS가 IOS, 안드로이드OS 외 기종인 경우 기능 적용 안됨. 이 경우 추가작업 필요

	if (navigator.userAgentData) {	// 안드로이드OS, 윈도우OS인 경우
		// 안드로이드OS 중 스마트폰인 경우 true, 스마트폰이 아닌 경우(태블릿인 경우) false
		return navigator.userAgentData.mobile ? navigator.userAgentData.mobile : false;
	} else {		// 안드로이드OS가 아닌 경우 (window, ios 등)
		// 아이폰인 경우
		if (navigator.platform == 'iPhone') {
			return true;
		}
	}

	return false;
};

