function _debugable() {
	if (psp.DEBUGGER && "on"===psputils.urlparams("traceable")) { psp.LOG_LEVEL = 0; }
	if (psp.DEBUGGER && "on"===psputils.urlparams("debugable")) { psp.LOG_LEVEL = 1; }
	if (psp.DEBUGGER && "on"===psputils.urlparams("inforable")) { psp.LOG_LEVEL = 2; }
	return (psp.DEBUGGER && "on"===psputils.urlparams("debugger")) || true===psp.TEMPORARILY_DEBUGGABLE;
}


function _log() {
	var m = "";
	try {
		for(let i=0; i<arguments.length; i++) {
			m += (""==m ? "" : " ");
			if ( "object" ==typeof arguments[i] ) {
				try {
					m += JSON.stringify(arguments[i]);
				}
				catch(e) {
					m += arguments[i].toString();
				}
			}
			else {
				m += arguments[i];
			}
		}
		//if (arguments.callee.caller.caller) { m += " :: caller=@(" + arguments.callee.caller.caller.name + ")"; }
	}
	catch(e) {
		m += "" + e.message;
	}
	if ( 0==psp.LOG_PIPE || 2==psp.LOG_PIPE ) {
		if ( 0==m.indexOf("[error]") ) { console.error(m); }
		else if ( 0==m.indexOf("[warn]") ) { console.warn(m); }
		else { console.log(m); }
	}
	if ( 1==psp.LOG_PIPE || 2==psp.LOG_PIPE ) { $p.log(m); }
}

function _chkLogLvl() {
	try {
		if (psputils.isLocal() || psputils.isDev() || psputils.isStag()) {
			psp.LOG_LEVEL = psp.LOG_LEVEL_DEV;
		}
	} catch (e) {

	}
}

function _trace() {
	_chkLogLvl();
	if (psp.LOG_LEVEL<1) {
		var args0 = Array.from(arguments);
			args0.unshift( "[trace]" );
		_log.apply(null, args0);
	}
}
function _debug() {
	_chkLogLvl();
	if (psp.LOG_LEVEL<2) {
		var args0 = Array.from(arguments);
			args0.unshift( "[debug]" );
		_log.apply(null, args0);
	}
}

function _info() {
	_chkLogLvl();
	if (psp.LOG_LEVEL<3) {
		var args0 = Array.from(arguments);
			args0.unshift( "[info]" );
		_log.apply(null, args0);
	}
}
function _warn() {
	_chkLogLvl();
	if (psp.LOG_LEVEL<4) {
		var args0 = Array.from(arguments);
			args0.unshift( "[warn]" );
		_log.apply(null, args0);
	}
}
function _error() {
	_chkLogLvl();
	if (psp.LOG_LEVEL<5) {
		var args0 = Array.from(arguments);
			args0.unshift( "[error]" );
		_log.apply(null, args0);
	}
}

