     *
     * @see ECF000.js function cfSelRelSaClsByEtc(sysCd, cdSec, etcGbnNo, etcGbnVal, relSaClsCdNm)
     */
    getReltCsClLst : function(systmCd, intgGrpCd, etcDvs, etcVal, objDataList) {

        sccdo.loadIntgCdLst(systmCd + scglblo.DELIMITER.HYPHEN + intgGrpCd); //DOC_CL_CD , CS_DVS_CD
        sccdo.setSystm(systmCd);
        var comCd = null;
        if("1" == etcDvs){
            comCd = sccdo.getIntgCdLstByFstmCtt(intgGrpCd, etcVal)
        }
        else if("2" == etcDvs) {
            comCd = sccdo.getIntgCdLstByScntmCtt(intgGrpCd, etcVal)
        }
        var resutlLst = [];

        for(var idx = 0; idx < comCd.length; idx++)  {
            // 분류목록세팅시 연계배당(B1) 제외함
            if("B1" == comCd[idx].intgCd) {
                continue;
            }

            // 당사자별 관련사건 분류 목록세팅시 해당분류를 중간에 삽입함.
            if("2" == etcDvs && ("99" == comCd[idx].intgCd  && "기타" == comCd[idx].intgCdNm)) {
                resutlLst.push({ "intgCd":"99_01", "intgCdNm":"채권가압류" });
                resutlLst.push({ "intgCd":"99_02", "intgCdNm":"채권압류및추심명령" });
                resutlLst.push({ "intgCd":"99_03", "intgCdNm":"채권압류및전부명령" });
            }
            resutlLst.push({ "intgCd":comCd[idx].intgCd, "intgCdNm": comCd[idx].intgCdNm });
        }
        objDataList.setJSON(resutlLst);
    },

    /**
     * 관련사건분류에 따라서 사건구분을 가져온다.
     * (사용예) psp.cd.getReltCsClByCsDvsLst("99", objDataList)
     * (참조1) sccdo.getIntgCdLstByFstmCtt("RELT_CS_DVS_CD", "102");
     *
     * @see ECF000.js function cfSelRelSaGbnByRelSaCls(srelSaCls, relSaGbnCdNm)
     */
    getReltCsClByCsDvsLst : function(reltCsCl, objDataList) {

        var arrReltCsCl1 = [ "A0",  // 판결정보(A0)
                             "A7",  // 조정조서(A7)
                             "A9",  // 화해권고결졍(A9)
                             "B0" ];// 조정을 갈음하는 결정또는 강제조정(B0)

