                             "99_02",   // 채권압류및 추심명령(99_02)
                             "99_03" ]; // 채권압류및 전부명령(99_03)

        var systmCd     = "LBA";        // 시스템코드
        var intgGrpCd   = "CS_DVS_CD";  // 통합구분코드
        var comCd       = null;
        var resutlLst   = [];

        // 판결정본(A0), 조정조서(A7), 화해권고결정(A9), 조정을갈음하는결정또는강제조정(B0)
        if (arrReltCsCl1.includes(reltCsCl)) {
