/**
 * <pre>
 * 입력한 날짜의 오늘, 3일, 일주일, 1개월전 날짜를 조회
 *
 * @memberOf scdateo
 *
 * @example ex)
 *
 * pspdate.getInsDay("20220520", "to"); 당일날짜
 * pspdate.getInsDay("20220520", "th"); 3일전날짜
 * pspdate.getInsDay("20220520", "we"); 7일전날짜
 * pspdate.getInsDay("20220520", "mon"); 31일전날짜
 * pspdate.getInsDay("20220520", "year"); 1년전날짜
 *
 * @param {String} psEndDate - 기준날짜 : YYMMDD 날짜
 * @param {String} vgbn - to:당일, th:3일전, we:7일전, mon:31일전 날짜, year:1년전날짜
 *
 * @return {String} - 해당날짜
 * </pre>
 */
pspdate.getInsDay = function(psEndDate, vgbn) {
	var psStartDate = "";
	if (vgbn == "to") {
		psStartDate = psEndDate;	//당일날짜
	}
	else if (vgbn == "th") {
		psStartDate = scdateo.getPrevYmd(psEndDate,2);	//3일전날짜
	}
	else if (vgbn == "we") {
		psStartDate = scdateo.getPrevYmd(psEndDate,6);	//7일전날짜
	}
	else if (vgbn == "mon") {
		psStartDate = scdateo.getPrevYmd(psEndDate,30);	//31일전날짜
	}
	else if (vgbn == "year") {
		psStartDate = scdateo.getPrevYmd(psEndDate,365);	//1년전날짜
	}
	return psStartDate;
};


