/**
 * <pre>
 * 오늘 날자 가져오기
 *
 * @param 날자 포맷 형식 null 이면 2009.12.12 형식
 *
 * </pre>
 */
pspdate.cfGetToday  = function(vformat){
  if(vformat == null){
    vformat = ".";
  }
  var vdate = new Date();
  var vyear = vdate.getFullYear();
  var vmonth = "0"+ (vdate.getMonth() + 1);
  var vday = "0"+ vdate.getDate();
  vmonth = vmonth.substr(vmonth.length - 2);
  vday = vday.substr(vday.length - 2);
  var vtoday = vyear + vmonth + vday;
  vtoday = vtoday.replace(/(\d{4})(\d{2})(\d{2})/,"$1"+ vformat + "$2" + vformat + "$3");
  return vtoday;

}

/**
 * <pre>
 * 19이상 성인여부 체크
 * </pre>
 * @param rrno1(주민(외국인)등록번호 앞 6자리), rrno2(주민(외국인)등록번호 뒤 7자리)
 * @return ture,false
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.03.   이석원       [NELS]최초 생성
 * ============= ============ ==========================
 */
pspdate.isAdult = function(rrno1, rrno2) {
	var currentDate = pspdate.cfGetToday("");
	var resultYear = 0;
	var resultDay = 0;
	var jSex = "";
	var convBfrRrno = "";
	var resultStr = "";

	if (null == rrno1 || null == rrno2) {
		return false;
	}

	if ("" == rrno1 || "" == rrno2) {
		return false;
	}

	var jSex = rrno2.substr(0, 1);

	if (jSex == 1 || jSex == 2 || jSex == 5 || jSex == 6) { // 1900년대생
		//convBfrRrno = "19" + rrno1.substr(0, 2) + "-" + rrno1.substr(2, 2) + "-" + rrno1.substr(4, 2);
		convBfrRrno = "19" + rrno1;
