/**
 * <pre>
 * 지정한 기준일자를 기준으로 날짜를 연산하여 결과 데이트 객체를 반환
 * 1) 지정한 기준일자가 없으면 현재 시각
 * 2) 오프셋은 +- 숫자 또는 지정한 문자열 가능. 없으면 0
 *
 * var objTodayDate = pspdate.addDate("20230815", "to"); //'2023-08-15' 기준, 당일 날짜객체(Date)
 * var objTodayDate = pspdate.addDate("20230815"); //'2023-08-15' 기준, 당일 날짜(Date) 객체
 *
 * var objD3Date = pspdate.addDate(null, "th"); //오늘 기준, 3일전 날짜객체(Date)
 * var objD3Date = pspdate.addDate(null, -3);   //오늘 기준, 3일전 날짜객체(Date)
 *
 * var objD7Date = pspdate.addDate(null, "we"); //오늘 기준, 1주일전 날짜객체(Date)
 * var objD7Date = pspdate.addDate(null, -7);   //오늘 기준, 1주일전 날짜객체(Date)
 *
 * var objD30Date = pspdate.addDate(null, "mon"); //오늘 기준, 31일전 날짜객체(Date)
 * var objD30Date = pspdate.addDate(null, -31); //오늘 기준, 31일전 날짜객체(Date)
 *
 * @param  paramDate   기준날짜(null, Date, String) : null이면 현재일시기준, "YYYYMMDD" 날짜문자열
 * @param  paramOffset 오프셋(null, 숫자, String) : null이면 0, {String} vgbn - to:당일, th:3일전, we:7일전, mon:31일전 날짜, yr:365일전 날짜
 * @return 연산된 날짜 객체
 * </pre>
 */
pspdate.addDate = function(paramDate, paramOffset) {
	let objDate = null;
	if ( null==paramDate ) {
		objDate = new Date();
	}
	objDate = ( 'object' == typeof baseDate ) ? paramDate : scdateo.getDateObj(paramDate); // 문자열이면 Date 객체로 변경

	let offset = 0;
	try {
		if ( isNaN( parseInt(paramOffset) ) ) {
			switch(paramOffset) {
			case "th":
			case "three":
				offset = -3; //3일전날짜
				break;
			case "we":
			case "week":
				offset = -7; //1주일전
				break;
			case "mon":
			case "month":
				offset = -31; //31일전
				break;
			case "yr":
			case "year":
				offset = -365; //365일전
				break;
			default:
				offset = 0; //오늘
				break;
			}
		}
		else {
			offset = parseInt(paramOffset);
		}
	}
	catch(e) {
		offset = 0;
	}
	objDate.setDate(objDate.getDate() + offset);

	return objDate; //scdateo.getDateStr(objDate);
};

/**
 * (샘플) 서버타임 조회 async 함수
 * (사용법예) pspdate.getSvrDateTime().then(e => { alert(JSON.stringify(e)); });
 *
 * @return 조회된 서버타임 객체(Promise)
 */
pspdate.getSvrDateTime = async function() {
	await psp.fetch("/pspcom/datetime.on")
		.then( (result) => {
			pspdate.svrDateTime = result.data["dma_datetime"];
			_debug("[dt#g.s.d.t]", result.message);
		})
		.catch( (error) => { //(참조) psp.PspError가 반환됨.
			_error("[dt#g.s.d.t]", error.message);
			scutilo.showMsg("응답오류", error.message);
			pspdate.svrDateTime = null;
		});
	return pspdate.svrDateTime; //(Promise)
};
