        var btnComp = psp.componentById(hlpCtnt.subId,  currFullId);
//        console.log(`HelpCont - make BtnCom Event =======> ${btnComp.getID()}`);

        btnComp.unbind("onclick");
        btnComp.bind("onclick", function(e) {

//            console.log(`HelpCont click HELPSHOW ============> ${helpCont.id}  : ${this.getOriginalID()} `);

            let isStdWeb        = !psp.env.isMobileSize(); //도움말은 화면사이즈로만 판단해야함
            let prnt_bfHelpId   = psphelp.bfHelpId;
            let prnt_allOpenYn  = psphelp.allOpenYn;
            let obj_btnShowAll  = mf_pfwork.getWindow().btn_showAll;

            let sFrstId         = `${currOrigId}_1ndGrp`;
            let sCurrId         = `${sFrstId}_${this.getOriginalID()}_2ndGrp`;
            let fullId          = psp.componentById(sCurrId, "pfwork").getID();

//            console.log(`HelpCont fnShowHelpCont ============> ${sFrstId}  : ${sCurrId} : ${prnt_bfHelpId} : ${prnt_allOpenYn} : ${fullId}`);

            if (true==isStdWeb) {
                if ($("#"+ fullId).css("display") == "block" && prnt_bfHelpId == sCurrId) {
                    if ($(".container").hasClass("open_infos") && prnt_allOpenYn == "N") {
                        $(".container").removeClass("open_infos");
                        return;
                    }
                }

                if (!$(".container").hasClass("open_infos")) {
                    $(".container").addClass("open_infos");
                }

                if (null!=obj_btnShowAll) {
                    obj_btnShowAll.show("");
                }

                var helpCtt = document.getElementsByClassName("help_cls");

                for (var idx = 0, len = helpCtt.length; idx < len ; idx++) {
                    helpCtt[idx].style.display = 'none';

                    var sHelpCttId = helpCtt[idx].id;
//                    console.log(`HelpCont Input =====================> ${sHelpCttId} : ${sFrstId} : ${sCurrId}`);

                    if(sHelpCttId.endsWith(sFrstId) || sHelpCttId.endsWith(sCurrId)) {
//                        console.log(`HelpCont View ======================> ${sHelpCttId} : ${currFullId} : ${sFrstId}`);
                        helpCtt[idx].style.display = 'block'; //지정한 '도웅말' 표시
                    }
                }
                psphelp.bfHelpId  = sCurrId;  // scwin.bfHelpId = id;
                psphelp.allOpenYn = "N"; // scwin.allOpenYn = "N";

                $(".dcmn_help").addClass('maxsize');
                if(psphelp.isHeaderVisible()) {
                    $(".dcmn_help").removeClass('maxsize');
                }
            }
            else { //모바일이면 팝업으로 동작
                var titl = "";
                var ctt  = "";
                var objId = "#"+id.replace(id.split("_")[2]+"_"+id.split("_")[3]+"_","");
//                titl = $(objId)[0].children[0].getInnerHTML();
                titl = $(objId)[0].children[0].innerHTML;
                for(var i = 1; i < $(objId)[0].childNodes.length; i++){
                    // ctt += "- " + $(objId)[0].children[i].getInnerHTML();
                    ctt += "- " + $(objId)[0].children[i].innerHTML;
                    ctt += "\n";
                }

                scutilo.showMsg(titl, ctt);
            }

        });
    }
}

