/**
 * <pre>
 * 전자소송포털 화면상 데이터 component 초기 binding 처리
 *  - 샘플 처리용
 * </pre>
 *
 * @parameter
 *     - initParam : 바인딩 데이터(필수)
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.02.21.   이석원         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.setInitComponent = function(initParam){
  var comp = null;

  for(var i = 0;  i < initParam.length; i++){
    comp = initParam[i];

    if(comp.dataSetKnTyp == "sccdo" && comp.uprElpPrptId == "lwstDvs"){
      sccdo.loadIntgCdLst(scglblo.SYSTM.STG + scglblo.DELIMITER.HYPHEN + comp.intgGrpCd); //DOC_CL_CD , CS_DVS_CD
      sccdo.setSystm(scglblo.SYSTM.STG);
      sccdo.bindIntgCdLst(comp.compId, comp.intgGrpCd);
    }else if(comp.dataSetKnTyp == "sccdo" && comp.uprElpPrptId == "moblDvs"){
      sccdo.loadIntgCdLst(scglblo.SYSTM.STG + scglblo.DELIMITER.HYPHEN + comp.intgGrpCd); //DOC_CL_CD , CS_DVS_CD
      sccdo.setSystm(scglblo.SYSTM.STG);
      pspscrn.bindIntgCdLstCdToVal(comp.compId, comp.intgGrpCd);

    }else if(comp.dataSetKnTyp == "sccorto" && comp.uprElpPrptId == "cort"){
      sccorto.bindCortLstByTyp(comp.compId, comp.filter); //60708090, 65, 71 유형도 있음.
    }else{
      if(comp.dataSetKnTyp == "comCd"){
        var params = {
                "dma_param" : {
                        "uprElpPrptId"  : comp.uprElpPrptId
                }
            };

        pspscrn.initCommCd(params, comp.compId, comp.dataSetId);
      }
    }
  }
};


/**
 * <pre>
 * 전자소송포털 공통코드 목록 조회 - component binding 처리
 * label값을 value값과 동일하게 출력
 * </pre>
 *
 * @parameter
 *     - compId(바인딩할 component id) : 필수
 *     - intgGrpCd(공통그룹코드) : 필수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.02.21.   이석원         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.bindIntgCdLstCdToCd = function(compId, intgGrpCd){
  var scopeId = $p.getFrameId();
  var _self = sccdo;
  if(null == scopeId){
    scopeId = "mf_pfwork";
  }

  var comp = psp.componentById(compId, "");

  compId = comp.id.replace(scopeId + "_", "");

  var dataId = compId + String(Math.random());

  var dataLstId = pspscrn.createDataLst({
    scopeId: scopeId,
    dataId: dataId,
    dataLstFieldInf: pspscrn.getMainDataClct(pspscrn.CD_DATA_ID).cellIdList,
    getDataFunc: _self.getIntgCdLst.bind(_self, intgGrpCd),
  });

  pspscrn.bindComponentData({
        scopeId: scopeId,
        compId: compId,
        dataLstId: dataLstId,
        label: 'intgCdNm',
        value: 'intgCdNm',
    });
};


