/**
 * <pre>
 * 사건번호 조회 사건연도 자동 세팅
 * </pre>
 * @parameter
 *     - compId(component id) : 필수
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.02.21.   이석원         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.initCsYr = function(compId){
  var comCd = pspscrn.initPspCommCd();
  var idx = 0;
  var initCsYr = null;
  var today = new Date();
  var todayYear = today.getFullYear();

  for(var i = 0; i < comCd.length; i++){
    if(comCd[i].elpPrptId == "psp.case.init.year"){
      idx = i;
    }
  }

  initCsYr = parseInt(comCd[idx].elpPrptVal);

  var comp = psp.componentById(compId);
  comp.removeAll(true);

  var listCnt = todayYear - initCsYr + 1;
  idx = 0;

  for(var i = 0; i < listCnt; i++){
    comp.addItem( todayYear - i, todayYear -i,  idx + i);
  }

};



