pspscrn.setIntgCdBnd = function (intgGrpCds) {
    var isDataList = function (compId) {
        var objType = "";
        try {
            objType = $p.getComponentById(compId).getObjectType();
        }
        catch {
            objType = "";
        }
        return scutilo.isNotEmpty(objType) && objType == "dataList";
    }

    var isValbyLabel = function() {

    }


    if (scutilo.isNotEmpty(intgGrpCds)) {
        var reqGrpCds = [];

        for (var idx = 0, len = intgGrpCds.length; idx < len; idx++) {
            var mstGrpCd =  intgGrpCds[idx];
            for(var jdx = 0, jlen = mstGrpCd[1].length; jdx < jlen; jdx++) {
                reqGrpCds.push([mstGrpCd[0], mstGrpCd[1][jdx].split(scglblo.DELIMITER.HYPHEN)[0]].join(scglblo.DELIMITER.HYPHEN));
            }
        }
        sccdo.loadIntgCdLst(reqGrpCds.join(","));
        for (var idx = 0, len = intgGrpCds.length; idx < len; idx++) {
            var mstGrpCd =  intgGrpCds[idx];
            for(var jdx = 0, jlen = mstGrpCd[1].length; jdx < jlen; jdx++) {
                var cds     = mstGrpCd[1][jdx].split(scglblo.DELIMITER.HYPHEN);
                var codeId  = cds[0];
                var eles    = cds[1].split(scglblo.DELIMITER.COMMA);
                var isLabel = "";
                if(cds.length > 2) {
                    isLabel = cds[2];
                }

                for(var ele of eles) {
                    if(scutilo.isNotEmpty($p.getComponentById(ele))) {
                        var grpcds = mstGrpCd[0].split(scglblo.DELIMITER.HYPHEN);
                        if(grpcds.length > 1) {
                            sccdo.setTask(grpcds[0], grpcds[1]);
                        }
                        else {
                            sccdo.setSystm(grpcds[0]);
                        }
                        if(isDataList(ele)) {
//                            console.log(`datalist 아직 구성중이에요---> ${ele}`);
                        }
                        else {
                            if(scutilo.isNotEmpty(isLabel)) {
                                pspscrn.bindIntgCdLstCdToCd(ele, codeId);
                            }
                            else {
                                sccdo.bindIntgCdLst(ele, codeId);
                            }
                        }
                    }
                    else {
//                        console.log(`continue 없어요 ---> ${ele}`);
                    }
                }
            }
        }
    }
}

