pspscrn.selLwstTypCdLst = function(dcId, isAll){
    var resultLwstTyp = null;
    //소송유형코드목록조회를 한다.
    com.executeAjax({
        action: psp.CONTEXT_ROOT + "/pspcom/selectLwstTypCdLst.on",
        mode: "synchronous",
        method: "POST",
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        requestData: JSON.stringify({
            isAll: isAll,
        }),
        success: function(_data) {
            resultLwstTyp = _data.responseJSON.data.result;
        },
        error: function(e) {
            alert("error code : " + e.responseStatusCode);
        },
    });

    //jsonData 생성
    var jsonData = JSON.parse(JSON.stringify(resultLwstTyp));

    //DataCollention에 값 설정
    dcId.setJSON(jsonData);
};

