/**
 * 웹스퀘어 selectbox와 autoComplete 의 value 에 해당하는 index
 *
 * @param  객체ID, value 검색할 value , dcId 검색할 데이터콜렉션ID (옵션)
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.02.   김성민        [NELS]최초 생성
 *  2023.04.11.   황은관        autoComplete 추가
 * ============= ============ ==========================
 */
pspscrn.selectboxGetIndexValue = function(selectboxId, value, dcId) {
    if(typeof(selectboxId) == 'undefined' || (selectboxId.getPluginName() != 'selectbox' && selectboxId.getPluginName() != 'autoComplete')) {
        return -1;
    }

    var itemArray = selectboxId.getItemArray();
    for(var i=0; i<itemArray.length; i++) {
        if(itemArray[i].value == value) {
            return i;
        }
    }

    return -1;
}

