/**
 * <pre>
 * @설명: 사건번호의 사건시작년도 콤보 조회
 * @param csYearCombo : 사건연도 콤보ID
 * @see ECF000.cfSelSaYearCommCd
 * </pre>
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.17.   황은관   [NELS]최초 생성
 * ============= ============ ==========================
 */
pspscrn.selCsYearCommCd = function(csYearCombo) {
    var currDay = pspdate.cfGetToday(""); // 현재일자 가져오기

    var startYear = psp.C.SA_YEAR;
    var toYear = parseInt(currDay.substring(0, 4));
    var diff = toYear - startYear;

    csYearCombo.removeAll(true);

    for (var i = 0; i <= diff; i++) {
        csYearCombo.addItem(toYear - i, toYear - i);
    }

    csYearCombo.setSelectedIndex(0);
}

