 * 테스트법원여부
 * </pre>
 *
 * @parameter
 *  cortCd:법원코드
 *
 * @return 테스트법원여부
 * @see ECF000.cfChkTestBubCd()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.04.26.   전성영         [NELS] 최초생성
 * 2024.05.09.	 이상현		  수정
 * ============= ============ ==========================
 */
pspscrn.isTestCortCd = function(cortCd){
    var vPrpt = psp.prpt.getPrpt("psp", "psp.testBubCd");

    if (undefined == cortCd  || "" == cortCd  || undefined == vPrpt.val || vPrpt.val.length == 0 ){
        return false;
    }

    var vPrptArr = vPrpt.val.split(",");

    if ( vPrptArr.indexOf(cortCd) > -1 ) {
        return true;
    }

    return false;
};

