 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.04.26.   전성영         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.selIntgCdLst = function(dcId, systm, codeGroup, scntmIntgCdIdx, scntmIntgCdVal) {
    var vIntgCdLst = psp.data.codes(systm, codeGroup); //공통코드 값
    var vIntgCdLstR = new Array(); //필터용 리턴값

    var vIdx = 0;

    if (undefined == scntmIntgCdIdx && null == scntmIntgCdIdx && undefined == scntmIntgCdVal && null == scntmIntgCdVal) {
        dcId.setJSON(vIntgCdLst);
    } else {
        for (var i = 0; i < vIntgCdLst.length; i++) {
            // 공통코드의 etc2값의 해당 인덱스 값이 표청한 값이면
            if (vIntgCdLst[i].scntmIntgCdAddCtt.charAt(scntmIntgCdIdx) == scntmIntgCdVal) {
                vIntgCdLstR[vIdx] = vIntgCdLst[i];
                vIdx++;
            }
        }

        dcId.setJSON(vIntgCdLstR);
    }
};

