/**
 * 서버인증서 정보 조회
 *
 * @return  서버인증서 문자열
 * @see     (asis) jsp에서 구현됨
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.15.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.getSvrCert = function() {

    // 프레임웤 CORS 오류 방지
    if (window.opener!= null ){
        window.opener = null;
    }

    if ( null==pspsoltn.SVR_CERT || ''==pspsoltn.SVR_CERT ) {
        var param = {"dma_null":{}}
        try {
            com.executeAjax({
                action: psp.CONTEXT_ROOT + "/psp001/svrcert.on",
                mode: "synchronous",
                method: 'POST',
                mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
                requestData: JSON.stringify({"dma_null":{}}),
                success: function(_data) {
                    var _dma = _data.responseJSON.data.dma_svrcert;
                    respCode = _data.responseJSON.data.dma_svrcert.respCode;
                    //_debug("[svrcert] 응답결과(dma_svrcert) ", _dma);
                    if ( "00"==respCode ) {
                        eval(_dma.svrcert);
                        pspsoltn.SVR_CERT = svrcert;
                    }
                    else {
                        _error("[#getSvrCert] respCode :", respCode);
                        scutilo.showMsg("정보", scutilo.getMsg(pspmsg.PSP.W_0000, '서버인증서를 참조하지 못하였습니다.'), function() {
                           _debug('[#getSvrCert] [showMsg.콜백] 서버인증서를 참조하지 못하였습니다.');
                        });
                    }
                    //if ( "asynchronous"===_mode ) {
                        //callback.call(null, val);
                    //}
                },
            });
        }
        catch(e) {
            scutilo.showMsg("정보", scutilo.getMsg(pspmsg.PSP.W_0000, '서버인증서를 참조하지 못하였습니다.'), function() {
                _debug('[#svrcert] [showMsg.콜백] 서버인증서를 참조하지 못하였습니다.');
            });
        }
    }
    return pspsoltn.SVR_CERT;
}


/**
 * 플러그인 체크한 회수에 따라, 다음 체크할 인터벌(밀리초)을 구하여 반환한다.
 * 디폴트) 30초 간격으로 체크
 *
 * @param   currCheckCount  체크회수(1,2,...), 최대 10회로 제한
 * @return  다음 체크할 인터벌(밀리초)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.03.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.getCheckInterval = function(currCheckCount, opts) {

     _debug('[#getCheckInterval] 허용된 최대회수 이상. curr# =', currCheckCount,  '/ opts :', opts);  // 임시ㅇ

    var _cnt_limit = opts && opts.chkCnt && opts.chkCnt>0 ? opts.chkCnt : pspsoltn.MAX_CNT_PLUGIN_CHECK;

    _debug('[#getCheckInterval] 허용된 최대회수 이상. _cnt_limit# =', _cnt_limit,  '/ opts.chkCnt :', opts.chkCnt);  // 임시ㅇ

    if ( currCheckCount>=_cnt_limit ) {
        _debug('[#getCheckInterval] 허용된 최대회수 이상. curr# =', currCheckCount, '/ 허용회수 =', _cnt_limit, '/ opts :', opts);
        return -1; //최대 10회로 제한, 이후 체크하지 않도록 함.(호출하는 함수에서 체크)
    }
    var seconds = pspsoltn.PLUGIN_CHECK_INTV_SEC; //30초
    var intvMs = seconds * pspsoltn.PLUGIN_CHECK_INTV_UNIT; // (밀리초단위로 반환)
    if ( opts && opts.chkIntv && opts.chkIntv>1000 ) {
        intvMs = opts.chkIntv;

        _debug('[#getCheckInterval] 허용된 최대회수 => . curr# =', currCheckCount, '/ 허용회수 =', _cnt_limit, '/ opts :', opts);   // 임시ㅇ

    }
    //var seconds = Math.pow(2, pspsoltn.MAX_CNT_PLUGIN_CHECK - currCheckCount); //2^9, 2^5 ==> 30
    //if (seconds>60) { seconds = 30 }
    return intvMs; // (밀리초단위로 반환)
};

/**
 * AnySign 플러그인 체크
 *
 * (아래는 사용법
    pspsoltn.checkAnySignPlugin(function(r) {
        _debug("[checkAnySignPlugin] 콜백 결과 : ", r);
    });
 *
 * @param   callbackFunc    체크결과 성공시 호출할 콜백함수
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.15.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.checkAnySignPlugin = function(callbackFunc) {
    var flg = true;
    do {
        _debug('[check ASP] begin...');
        WebSquare.layer.showProcessMessage("플러그인(ASP) 파일 로드중입니다.");
        AnySignLoad.init( function() {
            WebSquare.layer.hideProcessMessage();
            AnySign.mAnySignShowImg.showImg = false; // 설치 여부 검증 처리
            AnySign.StartAnySign(true);
            setTimeout(function() {
                AnySign4PC_installCheck(function(r) {
                    _debug('[check ASP] anySign: ', r);
                    if (r === 'ANYSIGN4PC_NORMAL') {
                        callbackFunc(r);
                    }
                    else {
                        _debug('[check ASP] 플러그인(ASP)이 설치되어 있지 않습니다! ' + r);
                        scutilo.showConfirm("정보", scutilo.getMsg(pspmsg.PSP.C_0094,''), //C_0094: "[인증서] 프로그램이 설치되지 않았습니다.\n프로그램을 설치하시겠습니까?",
                            function(result) {
                                if ( result.clickValue) {
                                    psp.onMenuClick({"pgmUrl":"PSP791M01"}); //설치화면으로 이동
                                }
                            }
                        );
                        callbackFunc(r);
                    }
                });
            }, 1000);
        });
    } while (! flg);
};


