/**
 * Papyrus의 StreamDocs 플러그인이 설치 체크결과 이 함수가 콜백으로 호출된다.(함수명 변경불가)
 *
 * (주의) 기존 이 함수에서 문서 출력 처리를 위해, agentPrintSuccess(), agentPrintFail()를 호출하였는데,
 *       차세대는 이 함수가 다시 호출하는 업무쪽 콜백함수에서 처리하도록 함.
 *
 * @param   data    버전체크/문서출력 결과 문자열 (예) 'version:5.0.4.186', 'print:NonPDFFile'
 * @see     (asis) htdocs\WebContent\papyrus\js\papyrusAgent.js#agentCallback(data)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.03.   안종광        [NELS]최초 생성
 *  2023.09.07.   배흥기        version check 추가
 * ============= ============ ==========================
 */
function agentCallback(data) {
    _debug("[#agentCallback] (of StreamDocs) : ", data);
    var results = {
        "status": false, //StreamDocs플러그인(Papyrus Plugin Agent) 설치여부
        "message": "",

    };
    if ( scutilo.isNotEmpty(data) ) {
        var arr = data.split(":"); //ex) ['version', '5.0.4.186']
        if ( null!=arr && 2==arr.length ) {
            results[arr[0]] = arr[1];
            if(pspsoltn.plugins.StreamDocs.version == arr[1]){ // version 확인
                results["status"] = true;
            }

        }
    }
    // (data ex) 'version:5.0.4.186', 'print:NonPDFFile'

    if ( null!=_streamdocs_callback_func ) {
        _streamdocs_callback_func(results)
    }
}


