// 파일확장자(소문자)를 반환 // (예) "첨부파일 업로드 테스트 hwp 파일 01.hwp" to "hwp"
pspsoltn.getFileExt = function(fileName) {
    if ( scutilo.isEmpty(fileName) || 0>fileName.indexOf(".") ) { return "";}
    var ext = null;
    try {
        ext = fileName.substring(1 + fileName.lastIndexOf(".")).toLowerCase(); //hwp
    }
    catch(e) {
        ext = "";
        _error("[soltn#getFileExt] fileName :", fileName, "/ message :", e.message);
    }
    return ext; //txt(소문자) (or) 오류시 ""
}

// 일반 서식 파일이면 true
pspsoltn.isDocFile = function(fileName) {
    if ( scutilo.isEmpty(fileName) ) { return null; }
    var fnext = pspsoltn.getFileExt(fileName);
    return pspsoltn.ALLOWED_DOC_FILE_EXTS.includes(fnext);
}

// 멀티미디어 파일이면 true
pspsoltn.isMmFile = function(fileName) {
    if ( scutilo.isEmpty(fileName) ) { return null; }
    var fnext = pspsoltn.getFileExt(fileName);
    return pspsoltn.ALLOWED_MM_FILE_EXTS.includes(fnext);
}

// 업로드 가능한 파일크기이면 true : 일반파일 (20M까지), 멀티미디어파일 (100M까지)
pspsoltn.isAllowedFileSize = function(fileSize, fileName) {
    var isMmFile = pspsoltn.isMmFile(fileName);
    if (true==isMmFile) {
        return pspsoltn.MAX_SIZE_MM_FILE > fileSize;
    }
    return pspsoltn.MAX_SIZE_DOC_FILE > fileSize;
}

// 파일유형에 따라 최대 업로드 가능한 파일크기를 반환 : 일반파일 (20M까지), 멀티미디어파일 (100M까지)
pspsoltn.getMaxUploadableSizeByFileType = function(fileName) {
    var isMmFile = pspsoltn.isMmFile(fileName);
    return true==isMmFile ? pspsoltn.MAX_SIZE_MM_FILE : pspsoltn.MAX_SIZE_DOC_FILE;
}


/**
 * 업로드용 이노릭스 컨트롤 객체 생성하고, 디폴트 이벤트 핸들러 설정.
 *
 * 1. 객체 생성
 * 2. 파일선택 전처리 : 허용할 파일확장자 필터
 * 3. 파일선택 후처리 : (업로드)
 * 4. 업로드 완료 : 전체 파일크기 표시
 * 5. 업로드 오류
 *
 * (참고) 각 업무화면에서 추가적인 이벤트 처리가 필요한 경우,
 * 이 pspsoltn.initInrx() 로 반환된 객체에서 해당 이벤트를 재정의 하여 사용
 *
 * (사용예 예, @see PSP000M03.xml)
 *
 * var btnFileDelHeaderObj = psp.componentById("grdAtchFile_btnFileDel", "pfwork");
 * var fileSizeDispObj = $(btnFileDelHeaderObj).children()[0];
 * scwin.control = pspsoltn.initInrx('#mf_pfwork_grp_innorix', dlt_gvfiles, fileSizeDispObj);
 *
 * scwin.control.on('afterAddFiles', function(files) {
 *     //각 화면에서 재정의하여 사용함.
 * }
 *
 *
 * @param   elemId  이노릭스가 바인딩될 (전체)엘리멘트ID (예) '#mf_pfwork_grp_innorix'
 * @param   dltObj  업로드된 파일정보가 저장되는 데이터리스트 객체
 * @param   fileSizeDispObj  업로드후 전체 파일사이즈를 표시할 객체
 * @param   inrxOption  이노릭스를 생성할 경우 필요한 옵션 - 별도처리를 위한

 * @return  업로드용 이노릭스 컨트롤 객체
 * @see     PSP000M03.xml
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.24   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.initInrx = function(elemId, dltObj, fileSizeDispObj, inrxOption) {
    var isInnorixIncluded = false;
    try {
        if ( ! innorix ) {
            _error("[soltn#initInrx] can NOT load innorix!");
        }
        isInnorixIncluded = true;
    }
    catch(e) {
        isInnorixIncluded = false;
    }
    if ( ! isInnorixIncluded ) {
        scutilo.showMsg("오류", "파일처리 객체를 로드하지 못하였습니다!"); //, function(p) { return false; });
        return null;
    }

    // 외부에서 이노릭스 옵션을 줄 경우 처리방안
    if(!inrxOption) {
        inrxOption = pspsoltn.getInrxOption(elemId);
    }

    if(scutilo.isNotEmpty(inrxOption.allowType)) {
//        console.log(`===================> ${inrxOption.allowType}`);
        if($.isArray(inrxOption.allowType)) {
            inrxOption.allowExtension = inrxOption.allowType;
        }
        else {
            inrxOption.allowExtension = inrxOption.allowType.replaceAll(/[\s\"]/g, '').split(',');
        }
    }

    // #1. 업로드용 이노릭스 컨트롤 객체 생성
    var _innoControl = innorix.create(inrxOption);
    _innoControl.setSize("99.5%", "120px"); //(생성시 설정안됨) boxHeight: 250,  boxWidth: "100%",
    // #2. 파일추가 전처리 이벤트 핸들러 : 파일상자에 파일을 추가하기 전 체크로직
    _innoControl.on('beforeAddFile', function(p) {
//        console.log(`===================beforeAddedFile `);
        _debug("[soltn#initInrx] before :", p);
        // 공통파일 검증
        if(!pspsoltn.cmnChkAtfl(p, _innoControl)) {
            return false;
        }
        var fpath = p.filePath;
        var fname = fpath.substring( 1+fpath.lastIndexOf("\\") );
        var fnext = fname.substring( 1+fname.lastIndexOf(".") ).toLowerCase();

        if(dltObj.getMatchedIndex('clientFileName', fname).length > 0) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0335, `<br>(${fname})`), function(p) {return false;});
            return false;
        }

        // 멀티미디어 파일은 단건만 등록가능함
        if(pspsoltn.isMmFile(fname)) {
            dltObj.setColumnFilter({
                type: 'func',
                colIndex: 'clientFileName',
                key: function(cellData, tmpParam, rowIdx) {
                    return pspsoltn.isMmFile(cellData);
                },
                condition: 'and'
            });
            if( dltObj.getRowCount() > 0) {
                dltObj.clearFilter();
                scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0256), function(p) {return false;});
                return false;
            }
            dltObj.clearFilter();
        }
        var filePermCnt = inrxOption.filePermCnt;

        if(dltObj.getRowCount() >= filePermCnt) {   // 기존에 등록한 값이 허용 수 보다 같거나 많으면
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0212,  filePermCnt), function(e) {
                return false;
            });
            return false;
        }
        // 단일파일을 위한 처리
        var fileSz = dltObj.getColData('fileSize').reduce((acc, curr) => { return acc+curr}, 0);

        if(fileSz > inrxOption.maxFileSize) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0125, psputils.getByteText(inrxOption.maxFileSize, 2)), function(p) {return false;});
            return false;
        }
    });

    // #3. 파일추가 후처리 이벤트 핸들러 : 파일상자에 파일을 추가하기 후 처리할 내용, (디폴트) 파일을 바로 업로드함
    _innoControl.on('afterAddFiles', function(files) {

//        console.log(`=================> ${JSON.stringify(files)}`);
        var fileCurrCnt = files.length + dltObj.getRowCount();
        var filePermCnt = _innoControl.option.filePermCnt;
        // 한번에 등록 가능한 수를 검증
        if(fileCurrCnt > filePermCnt) { // 허용가능한 수보다 많으면,
            fileCurrCnt = filePermCnt - dltObj.getRowCount();

            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0354,  filePermCnt, fileCurrCnt), function(e) {

            });
            // 컨트롤에서 파일 삭제
            for(var idx = files.length-1; idx >= fileCurrCnt; idx--) {
                _innoControl.removeFileByIndex(idx);
            }
            // 올리는 파일에서 삭제
            files.splice(0, fileCurrCnt);
        }

        var oneDocFileSize  = pspsoltn.MAX_SIZE_DOC_FILE;
        if(_innoControl.option.oneDocFileSize != undefined && scutilo.isNotEmpty(_innoControl.option.oneDocFileSize)) { // 일반파일
            oneDocFileSize = _innoControl.option.oneDocFileSize;
        }

        var currFileSz  = 0;
        var compSize    = 0;
        // 파일크기에 따른 업로드URL
        for(var idx=0, len=files.length; idx < len; idx++) {
//            if(files[idx].fileSize > pspsoltn.MAX_NORMAL_FILE) {
//                files[idx].uploadUrl =  files[idx].uploadUrl.replace("/smko/", "/smkobig/");
//            }
//            else {
//                files[idx].uploadUrl =  files[idx].uploadUrl.replace("/smkobig/", "/smko/");
//            }
            if(files[idx].fileSize > compSize) {
                compSize = files[idx].fileSize;
            }
            currFileSz += files[idx].fileSize;
        }
        pspsoltn.checkUploadUrl(compSize, _innoControl);
//        console.log(`====================> URL : ${_innoControl.getUploadUrl()},   FILE_SIZE : ${compSize}`);
        // 한번에 등록 가능한 파일 사이즈
        var fileSz = dltObj.getColData('fileSize').reduce((acc, curr) => { return acc+curr}, 0);
        fileSz = fileSz + currFileSz;
//        console.log(`====================> fileSz : ${fileSz}`);
        if(fileSz > _innoControl.option.maxFileSize) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0125, psputils.getByteText(_innoControl.option.maxFileSize, 2)), function(p) {return false;});
            _innoControl.removeAllFiles();
            return false;
        }

        // 시스템에 등록 가능한 파일 사이즈
        var isSucc = pspsoltn.getElpUserByAtflSz(fileSz);

        if(isSucc) {
            _innoControl.upload(); //(디폴트) 파일을 바로 업로드함
        }
        else {
            _innoControl.removeAllFiles();
            return false;
        }
    });

    // #4. 업로드 완료 이벤트 핸들러 : 업로드 완료후, 전체 파일사이즈 등 표시
    _innoControl.on('uploadComplete', function (p) {
        _debug("[soltn#initInrx] uploadComplete :", p);
        var files       = p.files;
        var currSize    = dltObj.getRowCount();
        var totalSize   = 0;

        for (var i = 0; i < files.length; i++ ) {
            _debug("[soltn#initInrx] uploadComplete :", i, "(파일정보)", files[i]);
            var rowdata0 = {
                "transferID"    : p.transferID,
                "fileSizeTxt"   : psputils.getByteText(files[i].fileSize, 2)
            };
            var rowdata = Object.assign({}, rowdata0, files[i]); //$.extend(rowdata, files[i]);
            totalSize += files[i].fileSize;
            var rowidx = i+currSize;

            dltObj.insertRow(rowidx);
            dltObj.setRowJSON(rowidx, rowdata, true);
            _debug("[soltn#initInrx] uploadComplete : i=", i, ", 행인덱스 =",  rowidx, ", (업로드정보)", dltObj.getRowJSON(rowidx));
        }
        _debug("[soltn#initInrx] uploadComplete : totalSize", totalSize);

        //#scwin.setTotalFileSizeText();
        if ( null != fileSizeDispObj ) {
            var totalSize2 = 0;
            for(var i = 0; i < dltObj.getRowCount(); i++) {
                var rowdata = dltObj.getRowJSON(i);
                totalSize2 += rowdata["fileSize"];
            }
            fileSizeDispObj.textContent = psputils.getByteText(totalSize2, 1);
        }
        _innoControl.removeAllFiles(); //업로드 완료후, 파일상자의 파일들은 삭제함

        //if ( scutilo.isEmpty(ibxDocNm.getValue()) ) {
        //    ibxDocNm.focus();
        //}
    });

    // #5. 업로드 오류 이벤트 핸들러 : 오류시 처리 핸들러
    _innoControl.on('uploadError', function(p) {
        _error("[soltn#initInrx] uploadError : [파일전송오류]", p);
        _innoControl.transferCancel();      // 전송 취소
        _innoControl.closeTransferWindow(); // 전송창 닫기
        _innoControl.removeAllFiles();      // 파일상자의 파일들은 삭제함
        dltObj.removeAll();                 // 파일업로드 된것을 삭제한다.
        var files = p.files;
        var strErrMsg = "";
        for (var i = 0; i < f.length; i++ ) {
            if (files[i].errorMessage !== undefined)
            strErrMsg += "\n" + files[i].errorMessage; //<br>
        }

        var m = "업로드 중 에러가 발생했습니다!";
            m+= strErrMsg;
        scutilo.showMsg("파일확인", m, function(p) { return false; });
    });

    return _innoControl;
}

pspsoltn.redefine = function(_innoControl, eventName, func) {
    if ( null==_innoControl ) {
        _error("[soltn#edefineInrx] innrix object is null!");
        return false;
    }
    if ( scutilo.isEmpty(eventName) ) {
        _error("[soltn#edefineInrx] event name is empty!");
        return false;
    }
    if ( null==func ) {
        _error("[soltn#edefineInrx] handler function is null!");
        return false;
    }

}


/**
 * 다운로드용 이노릭스 컨트롤 객체 생성하고, 디폴트 이벤트 핸들러 설정.
 * (참고) 파일업로드후 EDMS 등록하면, smko 임시파일이 삭제됨.
 * (참고) 이 다운로드 처리는 EDMS 등록전에만 가능함.
 *
 * 1. 객체 생성
 * 2. 객체로드 완료시
 * 3. 다운로드 완료시
 *
 * (사용예 예, @see PSP000M03.xml)
 *
 * scwin.ctrl4dl = pspsoltn.initInrxDn('#mf_pfwork_grp_innorix_dl', serverFilePath, serverFileName);
 * setTimeout(() => scwin.ctrl4dl.download(), 500);
 *
 *
 * @param   elemId  다운로드이노릭스가 바인딩될 (전체)엘리멘트ID (예) '#mf_pfwork_grp_innorix_dl'
 * @param   serverFilePath  서버파일경로(문자열)
 * @param   serverFileName  서버파일명(문자열)
 * @param   {boolean} isCallDownload 초기화 완료 후 다운로드 바로 호출할 것인지 여부 (기본값: false)
 * @param
 * @return  다운로드용 이노릭스 컨트롤 객체
 * @see     PSP000M03.xml
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.24   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.initInrxDn = function(elemId, serverFilePath, serverFileName, isCallDownload) {
    var isInnorixIncluded = false;
    try {
        if ( ! innorix ) {
            _error("[soltn#initInrxDn] can NOT load innorix!");
        }
        isInnorixIncluded = true;
    }
    catch(e) {
        isInnorixIncluded = false;
    }
    if ( ! isInnorixIncluded ) {
        scutilo.showMsg("오류", "파일처리 객체를 로드하지 못하였습니다!"); //, function(p) { return false; });
        return null;
    }

    var downfiles = [];
    var svrDir = serverFilePath.replace(serverFileName, "");
    //_debug("[soltn#initInrxDn] svrDir :", svrDir);
    _debug("[soltn#initInrxDn] serverFileName :", serverFileName);

    var fileinfo = {
        "printFileName": serverFileName,
        "downloadUrl": "/smko/smkofile/downloadFilesBySoltn.on?fileNm=" + serverFileName + "&filePath=" + svrDir
    };
    downfiles.push(fileinfo);
    _debug("[soltn#initInrxDn]", fileinfo);

    // #1. 다운로드 객체 생성
    _innoControlDn = innorix.create({
        el : elemId, // 컨트롤 출력 HTML 객체 ID
        agent: false, // true = Agent 모드, false = HTML5 모드
        transferMode : 'download', //both 업로드 사용
        installUrl : '/psp/cm/innorix/install.html',//'http://172.25.41.44:20611/smko/install/install.html', // Agent 설치 페이지
        isHighSpeed: true,
    });
    _innoControlDn.setSize("99.5%", "120px"); //(생성시 설정안됨) boxHeight: 250,  boxWidth: "100%",

    // #2. 객체로드 완료시
    _innoControlDn.on('loadComplete', function (p) { // 다운로드 파일 추가
        _innoControlDn.presetDownloadFiles(downfiles);
        if (isCallDownload === true) {
        	_innoControlDn.download(); //다운로드 실행
        }
    });

    // #3. 다운로드 완료시
    _innoControlDn.on('downloadComplete', function (p) { // 다운로드 전송완료 이벤트 처리
        _debug("[soltn#initInrxDn] downloadComplete :", p);
        //scwin.ctrl4dl = null; //scwin.ctrl4dl.destory();
    });
    return _innoControlDn;
}

/**
 * nas에 업로드된 파일을 pdf컨버팅및 edms에 등록하고 후처리 정보를 등록한다.
 *
 * 1. nas 업로드된 파일을 EDMS로 전송한다.
 * 2. EDMS에 등록된 파일의 정보를 DB에 저장한다.
