pspsoltn.fileUpload = function(dmaAtflInf, dltObj, pdfConvYn, isSaveYn, fnSuccess, fnErr, isExtPdfYn) {

    isExtPdfYn = scutilo.isEmpty(isExtPdfYn) ? "N":isExtPdfYn;
