/**
 * 일반대상파일을 PDF로 변환후 변환정보를 저장한다.
 *
 * 1. PDF변환이 필요한 파일은 PDF로 변환한다.
 * 2. PDF변환 정보를 수정한다.
 *
 * @param  {dmaAtflInf: 첨부파일 기본정보, dltObj: 첨부파일목록, fnSuccess : 콜백함수, fnErr : 에러시 함수, 변환여부}
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.25.   우근석       [NELS]최초 생성
 *  2023.10.05.   우근석       PDF변환시 파일 확장자 제거
 *  2024.02.07.   우근석       PNG, GIF 확장자 제거 삭제
 * ============= ============ ==========================
 */
pspsoltn.pdfConvert = function(dmaAtflInf, dltObj, fnSuccess, fnErr) {

    var elpEcdocNo      = dmaAtflInf.elpEcdocNo;        //  소송포털전자문서번호
    var elpUserId       = dmaAtflInf.elpUserId;         //  소송포털사용자
    var frameId         = dmaAtflInf.frameId;           //  프레임ID

    var sScopeId        = psp.getScopeId(frameId);

    var dmaResult = psp.createDma([
        { "dataType":"text",   "id":"respCode",                "name":"결과코드" },
        { "dataType":"text",   "id":"respMesg",                "name":"결과내용" }],
        "dma_response", sScopeId);

    // PDF변환 요청
    var dltPdfConvReqObj = psp.createDlt([
        { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
        { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
        { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
        { "dataType":"text",   "id":"jobKind",                 "name":"작업구분" },
        { "dataType":"text",   "id":"fileEdmsDocId",           "name":"파일EDMS문서ID" },
        { "dataType":"text",   "id":"marginTop",               "name":"상단여백" },
        { "dataType":"text",   "id":"marginBottom",            "name":"하단여백" },
        { "dataType":"text",   "id":"marginLeft",              "name":"왼쪽여백" },
        { "dataType":"text",   "id":"marginRight",             "name":"오른쪽여백" },
        { "dataType":"text",   "id":"pdfConvFileNm",           "name":"PDF변경파일명" },
        { "dataType":"text",   "id":"userId",                  "name":"작성요청자ID" },
        { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
        "dlt_convReq", sScopeId);

    // PDF변환 응답
    var dltPdfConvResObj = psp.createDlt([
        { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
        { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
        { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
        { "dataType":"text",   "id":"fileEdmsDocId",           "name":"파일EDMS문서ID" },
        { "dataType":"text",   "id":"fileNm",                  "name":"파일명" },
        { "dataType":"text",   "id":"fileSz",                  "name":"파일크기" },
        { "dataType":"text",   "id":"fileUnqNo",               "name":"파일유일번호" },
        { "dataType":"text",   "id":"fileHashVal",             "name":"파일해쉬값" },
        { "dataType":"number", "id":"docPageCnt",              "name":"문서장수" },
        { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
        "dlt_convRes", sScopeId);

    // 파일목록정보
    var dltFileSaveInf = psp.createDlt([
        { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
        { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
        { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
        { "dataType":"text",   "id":"elpUserId",               "name":"소송포털사용자ID" },
        { "dataType":"text",   "id":"atchDocmtNm",             "name":"첨부서류명" },
        { "dataType":"text",   "id":"atchDocmtKndCd",          "name":"첨부서류종류코드" },
        { "dataType":"text",   "id":"atflEdmsDocId",           "name":"첨부파일EDMS문서ID" },
        { "dataType":"text",   "id":"atflHshVal",              "name":"첨부파일해쉬값" },
        { "dataType":"text",   "id":"atflNm",                  "name":"첨부파일명" },
        { "dataType":"text",   "id":"atflSz",                  "name":"첨부파일사이즈" },
        { "dataType":"text",   "id":"atflConvTrgtYn",          "name":"첨부파일변환대상여부" },
        { "dataType":"text",   "id":"atchDocmtKndCd",          "name":"첨부서류종류코드" },
        { "dataType":"text",   "id":"convAtflEdmsDocId",       "name":"변환첨부파일EDMS문서ID" },
        { "dataType":"text",   "id":"convAtflHshVal",          "name":"변환첨부파일해쉬값" },
        { "dataType":"text",   "id":"convAtflNm",              "name":"변환첨부파일명" },
        { "dataType":"text",   "id":"convAtflSz",              "name":"변환첨부파일사이즈" },
        { "dataType":"number", "id":"docPageCnt",              "name":"문서장수" },
        { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
        "dlt_atchfiles", sScopeId);

    // fnErr가 입력되어 있는지 확인 후 없으면 기본function으로 생성한다.
    if(fnErr === undefined ) {
        var fnErr = function () {
            scutilo.showMsg(scglblo.MSG.ERROR, scutilo.getMsg(pspmsg.PSP.E_0400, "PDF변환")); //처리중오류가 발생하였습니다.
        }
    }
    WebSquare.layer.showProcessMessage(scutilo.getMsg(pspmsg.PSP.I_0000, "PDF변환대상파일을 변환하는 중입니다."));
    // PDF변환이 필요한 파일을 PDF로 변환한다.
    var fnConvertPdf = function (dltLst) {
        dltPdfConvReqObj.removeAll();
        var compSz = 0;
        for(var idx = 0, len = dltLst.length; idx < len; idx++ ) {
            var fileObj = dltLst[idx];
            var fileNm  = fileObj.atflNm;
            fileNm      = fileNm.replace(/\s/g, "_");                   // 공백을 허용하지 않음
//            fileNm      = fileNm.replace(/(.png|.gif)$/, '');           // PNG/GIF 제거
            fileNm      = fileNm.substring(0, fileNm.lastIndexOf('.')); // 확장자 제거
            var docIssuNo = "";
            if(fileObj.docIssuNo != undefined ) {
                docIssuNo = fileObj.docIssuNo;
            }
            if(compSz < fileObj.atflSz) {
                compSz = fileObj.atflSz;
            }

            dltPdfConvReqObj.insertJSON(idx, [{
                "elpEcdocNo"            : fileObj.elpEcdocNo,           // 소송포털전자문서번호
                "elpEcdocAtchDocmtSeq"  : fileObj.elpEcdocAtchDocmtSeq, // 소송포털전자문서첨부서류순번
                "elpEcdocAtflSeq"       : fileObj.elpEcdocAtflSeq,      // 소송포털전자문서첨부파일순번
                "jobKind"               : "PSP",                        // EDMS등록 시스템코드
                "fileEdmsDocId"         : fileObj.atflEdmsDocId,        // 첨부파일EDMSID
                "pdfConvFileNm"         : fileNm + ".pdf",
                "docIssuNo"             : docIssuNo,                    // 문서발급번호
                "userId"                : elpUserId
            }]);
        }


        var url = "/smko/smkofile/convertPdfFiles.on";
        url = pspsoltn.replaceSmkoBigUrl(url, compSz);
        com.executeSubmission(
                psp.createSbm({
                    "processMsg"         : "PDF변환대상파일을 변환하는 중입니다.",     // 메시지문자열
                    "submitErrorHandler" : fnErr
                },
                "sbm_convertPdfFiles",
                "data:json, {'id':'dlt_convReq','key':'dlt_convertPdfFiles'}",          // 요청
                "data:json, {'id':'dlt_convRes','key':'data.dlt_convertPdfFilesRes'}",  // 응답
                url,
                sScopeId,
                fnSavePdfFiles));
    }

    // PDF로 변환된 정보를 수정한다.
    var fnSavePdfFiles = function () {

        dltFileSaveInf.removeAll();
        for(var idx = 0, len = dltPdfConvResObj.getRowCount(); idx < len; idx++ ) {
            var reqObj = dltPdfConvReqObj.getRowJSON(idx);
            var resObj = dltPdfConvResObj.getRowJSON(idx);

            dltFileSaveInf.insertJSON(idx, [{
                "elpEcdocNo"            : reqObj.elpEcdocNo,             // 소송포털전자문서번호
                "elpEcdocAtchDocmtSeq"  : reqObj.elpEcdocAtchDocmtSeq,   // 소송포털전자문서첨부서류순번
                "elpEcdocAtflSeq"       : reqObj.elpEcdocAtflSeq,        // 소송포털전자문서첨부파일순번
                "atflEdmsDocId"         : reqObj.fileEdmsDocId,
                "atflHshVal"            : reqObj.fileHashVal,
                "atflNm"                : reqObj.fileNm,
                "atflSz"                : reqObj.fileSz,
                "docIssuNo"             : reqObj.docIssuNo,             // 문서발급번호

                "convAtflEdmsDocId"     : resObj.fileEdmsDocId,
                "convAtflHshVal"        : resObj.fileHashVal,
                "convAtflNm"            : resObj.fileNm,
                "convAtflSz"            : resObj.fileSz,
                "docPageCnt"            : resObj.docPageCnt
            }]);
        }

        com.executeSubmission(
                psp.createSbm({
                    "processMsg"         : "PDF변환정보를 저장하는 중입니다.",     // 메시지문자열
                    "submitErrorHandler" : fnErr
                },
                "sbm_updateConvPdfLst",
                "data:json, {'id':'dlt_atchfiles',  'key':'cvtInfList'}",   // 요청
                "data:json, {'id':'dma_response',   'key':'message'}",      // 응답
                "/psp/pspACom/updateConvPdfLst.on",
                sScopeId,
                function(){
                    if ( null!=fnSuccess && 'function' == typeof fnSuccess ) {
                        fnSuccess.call(null, dltFileSaveInf.getAllJSON());
                    }
                } ));
    }
    fnConvertPdf(dltObj);
}

