/**
 * 파일을 EDMS에 등록한 후 PSP027, 028테이블에 저장한다.
 * @param  {{elpEcdocNo     : 소송포털전자문서번호,
 *          elpUserId       : 소송포털사용자ID,
 *          atchDocmtKndCd  : 첨부서류종류코드},
 *          dltAtflLst      : 첨부파일목록,
 *          mode            : Sync,Async 모드,
 *          fnSuccess       : 콜백함수,
 *          fnErr           : 에러시 함수}
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.01.18.   우근석
 * ============= ============ ==========================
 */
pspsoltn.fnRegAtchDocmtExtend = function (dmaAtflInf, dltAtflLst, mode, fnSuccess, fnErr) {

//    console.log(`=====================================> fnRegAtchDocmtExtend  :: ${mode}`);
//    console.log(`=====================================> fnRegAtchDocmtExtend  :: ${JSON.stringify(dmaAtflInf, null, '\t')}`);
    var elpEcdocNo          = dmaAtflInf.elpEcdocNo;            //  소송포털전자문서번호
    var atchDocmtKndCd      = dmaAtflInf.atchDocmtKndCd;        //  첨부서류종류
    var atchDocmtRegMthdCd  = dmaAtflInf.atchDocmtRegMthdCd;    //  첨부서류등록방법코드
    var fileNmSameYn        = dmaAtflInf.fileNmSameYn;          //  파일명 동일여부
    var elpUserId           = dmaAtflInf.elpUserId;             //  프레임ID
    var frameId             = dmaAtflInf.frameId;               //  스코프ID
    var sScopeId            = psp.getScopeId(frameId);
    //[#증거] 형사추가 star
    // 증거서류 : 증거신청유형코드 smk에 조회조건에 추가 하기 위해 송달처구분코드 추가
    var dlvrplDvsCd    = "";
    var docmt          = psp.componentById("dma_docmt", "pfwork");

    if(scutilo.isNotEmpty(docmt)) {
    	dlvrplDvsCd    = docmt.get("dlvrplDvsCd");
    }
    //[#증거] 형사추가 end

    // 파일목록정보
    var dltAtfl = psp.createDlt([
        { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
        { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
        { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
        { "dataType":"text",   "id":"elpUserId",               "name":"소송포털사용자ID" },
        { "dataType":"text",   "id":"atchDocmtNm",             "name":"첨부서류명" },
        { "dataType":"text",   "id":"atchDocmtKndCd",          "name":"첨부서류종류코드" },
        { "dataType":"text",   "id":"atchDocmtRegMthdCd",      "name":"첨부서류등록방법코드" },
        { "dataType":"text",   "id":"atflEdmsDocId",           "name":"첨부파일EDMS문서ID" },
        { "dataType":"text",   "id":"atflHshVal",              "name":"첨부파일해쉬값" },
        { "dataType":"text",   "id":"atflNm",                  "name":"첨부파일명" },
        { "dataType":"text",   "id":"atflSz",                  "name":"첨부파일사이즈" },
        { "dataType":"text",   "id":"atflConvTrgtYn",          "name":"첨부파일변환대상여부" },
        { "dataType":"text",   "id":"convAtflEdmsDocId",       "name":"변환첨부파일EDMS문서ID" },
        { "dataType":"text",   "id":"convAtflHshVal",          "name":"변환첨부파일해쉬값" },
        { "dataType":"text",   "id":"convAtflNm",              "name":"변환첨부파일명" },
        { "dataType":"text",   "id":"convAtflSz",              "name":"변환첨부파일사이즈" },
        { "dataType":"number", "id":"docPageCnt",              "name":"문서장수" },
        { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
        "dlt_atflLst", sScopeId);

    // 파일기본정보  //[#증거] dlvrplDvsCd 추가
    var dmaAtchDocmt = psp.createDma([
        { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
        { "dataType":"text",   "id":"atchDocmtKndCd",          "name":"첨부서류종류코드" },
        { "dataType":"text",   "id":"atchDocmtRegMthdCd",      "name":"첨부서류등록방법코드" },
        { "dataType":"text",   "id":"ofdocDvsCd",              "name":"문건구분코드" },
        { "dataType":"text",   "id":"dcmevdMarkDvsCd",         "name":"서증부호구분코드" },
        { "dataType":"text",   "id":"dcmevdBrncMarkNm",        "name":"가지부호명" },
        { "dataType":"text",   "id":"dlvrplDvsCd",             "name":"송달처구분코드" },
        { "dataType":"text",   "id":"fileNmSameYn",            "name":"파일명과동일여부"}],
        "dma_atchDocmt", sScopeId);
    if(fnErr === undefined ) {
        fnErr = function () {
            scutilo.showMsg(scglblo.MSG.ERROR, scutilo.getMsg(pspmsg.PSP.E_0400, '첨부서류 저장'));
        }
    }
    if(fnSuccess === undefined ) {
        fnSuccess = function() {
            scutilo.showMsg(scglblo.MSG.INFO, scutilo.getMsg(pspmsg.PSP.W_0638, dltAtflLst.length));
        }
    }
    WebSquare.layer.showProcessMessage(scutilo.getMsg(pspmsg.PSP.I_0000, "첨부서류 정보를 저장하는 중입니다."));
    var regAtchDocmtUrl =  "/psp/pspA0m/saveAtchLst.on";
    //
    dmaAtchDocmt.setJSON({
        "elpEcdocNo"            : elpEcdocNo,               // 소송포털전자문서번호
        "atchDocmtKndCd"        : atchDocmtKndCd,           // 첨부서류종류
        "atchDocmtRegMthdCd"    : atchDocmtRegMthdCd,       // 첨부서류등록방법코드
        "fileNmSameYn"          : fileNmSameYn              // 파일명과동일여부
    });

    if( psp.C.ADK_JG === atchDocmtKndCd) {
        dmaAtchDocmt.set("ofdocDvsCd",          dmaAtflInf.ofdocDvsCd);
        dmaAtchDocmt.set("dcmevdMarkDvsCd",     dmaAtflInf.dcmevdMarkDvsCd);
        dmaAtchDocmt.set("dcmevdBrncMarkNm",    dmaAtflInf.dcmevdBrncMarkNm);
        dmaAtchDocmt.set("dlvrplDvsCd",         dlvrplDvsCd); //[#증거]

        regAtchDocmtUrl =  "/psp/pspA0l/saveDcmevdAtflLst.on";
    }
    dltAtfl.setJSON(dltAtflLst);

    com.executeSubmission(
            psp.createSbm({
                "mode"               : mode,
                "processMsg"         : "첨부서류 정보를 저장하는 중입니다.",     // 메시지문자열
                "submitErrorHandler" : function() {
                    dltAtfl.removeAll();
                    fnErr();
                    WebSquare.layer.hideProcessMessage();
                }
            },
            "sbm_saveAtchLst",
            "data:json, [{'id':'dlt_atflLst',   'key':'dlt_atchfiles'}, " +
                        "{'id':'dma_atchDocmt', 'key':'dma_atflInf'}]",         // 요청
            "data:json, [{'id':'dma_response',  'key':'data.dma_response'}, " +
                        "{'id':'dlt_atflLst',   'key':'data.atflLst'}]",        // 응답
            regAtchDocmtUrl,
            sScopeId,
            function() {
//                console.log(`============> fnRegAtchDocmtSucc `);
                fnSuccess(dltAtfl.getAllJSON());
                dltAtfl.removeAll();
                WebSquare.layer.hideProcessMessage();
            }));
}

