/**
 * EDMS파일 관련 정보 조회
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.11.28.   우근석
 * ============= ============ ==========================
 */
pspsoltn.getFileInfo = function(arg) {
    var data = {};
    com.executeAjax({ //
        action      : "/psp/pspA0m/getFileInfo.on",
        mode        : "synchronous",
        mediatype   : gcm.DEFAULT_OPTIONS_MEDIATYPE,
        requestData : JSON.stringify({ type : arg }),
        success     : function(e) {
            data = e?.responseJSON?.data?.fileInfo;
        },
    });
    return data;
}

/**
 *  5개파일에 대한 업로드용 이노릭스 컨트롤 객체 생성하고, 디폴트 이벤트 핸들러 설정.
 * @param  {elemId          : 첨부파일 객체ID
 *          dltObj          : 첨부파일 임시 목록 객체
 *          dmaAtflInf      : 첨부파일 등록시 기본정보 객체
 *          dlt_atchList    : 첨부파일 목록 객체
 *          fnSucc          : 콜백함수
 *          fnCrtElpEcdocNo : 첨부파일 등록 시 전자소송포털문서번호생성 함수
 *          inrxOption      : 첨부파일 생성옵션 - 옵션 (값이 없을 경우 기본값으로 처리)
 *          eleDropBoxId    : 드롭박스존 객체ID - 옵션 (값이 없을 경우 드롭박스 처리를 하지 않음)}
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.01.18.   우근석
 *  2024.07.30.   우근석       첨부서류명이 없을 경우 파일명을 첨부서류명으로 처리
 * ============= ============ ==========================
 */
pspsoltn.initInrxExt = function(elemId, dltObj, dmaAtflInf, dlt_atchList, fnSucc, fnCrtElpEcdocNo, inrxOption, isPdfExtYn) {

    var isInnorixIncluded = false;
    try {
        if ( ! innorix ) {
            _error("[soltn#initInrx] can NOT load innorix!");
        }
        isInnorixIncluded = true;
    }
    catch(e) {
        isInnorixIncluded = false;
    }
    if ( ! isInnorixIncluded ) {
        scutilo.showMsg("오류", "파일처리 객체를 로드하지 못하였습니다!"); //, function(p) { return false; });
        return null;
    }

    if(scutilo.isEmpty(dmaAtflInf.atchDocmtNm) && scutilo.isEmpty(dmaAtflInf.atchDocmtNmId)) {
        scutilo.showMsg("오류", "설정값을 확인하세요."); //, function(p) { return false; });
        return null;
    }
    // 외부에서 이노릭스 옵션을 줄 경우 처리방안
    if(!inrxOption) {
        inrxOption = pspsoltn.getInrxOption(elemId);
        // 초기값 선언
//        var permDocSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSize").val||'10';                 //첨부 가능 1개 파일 용량
//        var totAtflSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.totSizeForAttach").val||'50';         //첨부 가능 전체 파일 용량
//
//        var expendYn     = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendAllYn").val||'Y';
//        var expendId     = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendID").val||'';
//        if(expendYn == "Y" || (scutilo.isNotEmpty(expendId) &&
//                              scutilo.isNotEmpty(psp.session()) &&
//                              expendId.split(',').indexOf(psp.session()) > -1)) {
//              permDocSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSizeNew").val||'20';
//              totAtflSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.totSizeForAttachNew").val||'100'; //첨부 가능 전체 파일 용량
//        }
//        inrxOption.allowType        = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.typeAttachForNotMulti").val;   // 멀티미디어를 제외한다.
//        inrxOption.oneDocFileSize   = permDocSz*1024*1024;
//        inrxOption.maxFileSize      = totAtflSz*1024*1024;

        var fileInfoJson = pspsoltn.getFileInfo("I");

        var permDocSz   = fileInfoJson["permDocSz"];
        var totAtflSz   = fileInfoJson["totAtflSz"];
        var allowCont   = fileInfoJson["allowContIlBan"];

        inrxOption.allowType        = fileInfoJson["allowTpIlBan"];    // 허용파일 확장자
        inrxOption.allowExtCont     = `첨부가능한 파일 형식 (${permDocSz}MB까지 첨부가능) : ${allowCont}`;
        inrxOption.oneDocFileSize   = permDocSz*1024*1024;
        inrxOption.maxFileSize      = totAtflSz*1024*1024;

    }

    if(scutilo.isNotEmpty(inrxOption.allowType)) {
//        console.log(`===================> ${inrxOption.allowType}`);
        if($.isArray(inrxOption.allowType)) {
            inrxOption.allowExtension = inrxOption.allowType;
        }
        else {
            inrxOption.allowExtension = inrxOption.allowType.replaceAll(/[\s\"]/g, '').split(',');
        }
    }

    var _innoControl =  pspsoltn.initInrxCtrl(elemId, dltObj, inrxOption, function () {
        if(dltObj.getRowCount() > 0) {

            var atchDocmtNm = "";
            if(scutilo.isNotEmpty(dmaAtflInf.atchDocmtNmId)) {
                atchDocmtNm =   psp.componentById(dmaAtflInf.atchDocmtNmId, dmaAtflInf.frameId).getValue();
            }
            else if(scutilo.isNotEmpty(dmaAtflInf.atchDocmtNm)) {
                atchDocmtNm = dmaAtflInf.atchDocmtNm;
            }
            // 전자소송포털문서번호가 없을 경우
            if(scutilo.isEmpty(dmaAtflInf.elpEcdocNo)) {
                fnCrtElpEcdocNo.call(null);
                var dmaDocmt = psp.componentById("dma_docmt", "pfwork");
                dmaAtflInf.elpEcdocNo = dmaDocmt.get("elpEcdocNo");
            }
//            console.log(`pspsoltn.initInrxCtrl(===================> ${JSON.stringify(dmaAtflInf)}`);
            pspsoltn.fileUpload(dmaAtflInf, dltObj, "Y", "N", function(dltAtflLst) {
                dltObj.removeAll();
                var elpEcdocAtchDocmtSeq = "";

                if(dlt_atchList.getRowCount() > 0) {
                    elpEcdocAtchDocmtSeq = dlt_atchList.getCellData(0, "elpEcdocAtchDocmtSeq");
                }

                for(var idx=0,len=dltAtflLst.length; idx < len; idx++) {
                    dltAtflLst[idx]["elpEcdocAtchDocmtSeq"]  = elpEcdocAtchDocmtSeq;
                    dltAtflLst[idx]["atchDocmtNm"]           = scutilo.isEmpty(atchDocmtNm) ? dltAtflLst[idx]["atchNm"]: atchDocmtNm;
                }
                pspsoltn.fnRegAtchDocmt(dmaAtflInf, dltAtflLst, fnSucc);
            }, null, isPdfExtYn);
        }
    });

    _innoControl.on('afterAddFiles', function (files) {
        if(_innoControl.fileList.files.length > 0 ) {
            var fileCnt = dlt_atchList.getRowCount();
            var fileCurr = _innoControl.fileList.files.length;
            if(_innoControl.option.filePermCnt < (fileCnt+fileCurr)) {
                scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0212,  _innoControl.option.filePermCnt), function(e) {
                });
                _innoControl.removeAllFiles();
                return false;
            }
            else {
                _innoControl.upload();
            }
        }
    });


    if(scutilo.isNotEmpty(dmaAtflInf.dropZoneId)) {
        // 드래그앤 드롭 존 설정
        var innoJquery = innorix._load("innoJquery");
        innoJquery("#" + dmaAtflInf.dropZoneId).on({
            "dragenter": function (e) {
                _innoControl.setDropZone(e, this); // DropZone 으로 지정
            }
        });
    }
    return _innoControl;
}

