//
//        var expendYn            = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendAllYn").val||'Y';
//        var expendId            = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendID").val||'';
//
//        if(expendYn == "Y" ||
//                       (scutilo.isNotEmpty(expendId) &&
//                        scutilo.isNotEmpty(psp.session()) &&
//                        expendId.split(',').indexOf(psp.session()) > -1)) {
//            permDocSz       = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSizeNew").val||'20';
//            permMultiSz     = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSizeForMultiNew").val||'100';
//        }


        var fileInfoJson = pspsoltn.getFileInfo();
        var sAllowContDefault   = fileInfoJson["allowContNotMulti"];    //첨부 가능 일반파일   안내메시지용
        var sAllowContMulti     = fileInfoJson["allowContMulti"];       //첨부 가능 멀티미디어 안내메시지용
        var permDocSz           = fileInfoJson["permDocSz"];
        var permMultiSz         = fileInfoJson["permMultiSz"];

        var rtnMsg = "";
        isType = isType||"D";
        var sAllowCont = "";

        if(isType === "M") {    // 멀티미디어파일의 경우
            rtnMsg = scutilo.getMsg("※ 첨부가능한 파일 형식 : <%s> (<%s>MB까지 첨부가능)", sAllowContMulti, permMultiSz);
        }
        else if(isType === "A") { // 전체파일의 경우
            rtnMsg = scutilo.getMsg("<p class=\"fc_green\">※ 첨부가능한 파일 형식</p><p>- 일반문서 : <%s> (PDF파일로 자동변환, <%s>MB까지 첨부가능)</p><p>- 멀티미디어자료(<%s>MB까지 첨부가능) : <%s></p>", sAllowContDefault, permDocSz, permMultiSz, sAllowContMulti);
        }
        else if(isType === "AN") { // 전체파일(PDF변환X)의 경우
            rtnMsg = scutilo.getMsg("<p class=\"fc_green\">※ 첨부가능한 파일 형식</p><p>- 일반문서(<%s>MB까지 첨부가능) : <%s> </p><p>- 멀티미디어자료(<%s>MB까지 첨부가능) : <%s></p>", permDocSz, sAllowContDefault, permMultiSz, sAllowContMulti);
        }
        else {
            rtnMsg = scutilo.getMsg("※ 첨부가능한 파일 형식 : <%s> (PDF파일로 자동변환, <%s>MB까지 첨부가능)", sAllowContDefault, permDocSz);
        }

        if(dispElement != null && dispElement.setLabel != null) {
            dispElement.setLabel(rtnMsg);
        }

        return rtnMsg;
    }
    catch (e) {
        _error("pspsoltn.allowTypeCont", "error", e.stack);
    }
}

/**
*
* @param  {edmsFileIds : 첨부파일EDMS_ID,
*          elpUserId   : 사용자ID,
*          scopeId     : 화면스코프ID,
*          callback    : 콜백함수,
*          fnErr       : 에러시 함수}
* @return
* ============= ============ ==========================
*  Date          Author       Description
* ============= ============ ==========================
*  2023.08.07.   우근석       [NELS]최초 생성
* ============= ============ ==========================
*/
pspsoltn.fnPdfValidate = function(dltObj, fnSucc) {
    dltObj.setColumnFilter({
        type: 'func', colIndex: "serverFileName", key: function (cellData, tmpParam, rowIdx) {
            return pspsoltn.getFileExt(cellData) === "pdf";
        }, condition: 'and'
    });
    let dltFilteredData = dltObj.getAllFilteredJSON();
    dltObj.clearFilter();

    if(dltFilteredData.length > 0) {
        com.executeAjax({
            action: "/psp/pspcom/selectPdfValidate.on",
            requestData: JSON.stringify({
                "dlt_fileLst" : dltFilteredData
            }),
            mode: "asynchronous",
            mediatype: "application/json",
            method: "POST",
            success: function (_data) {
                var dltFileObj = _data?.responseJSON?.data?.dltFileLst;
                var targetLst = dltFileObj.filter((fileObj)=> fileObj.errPdfYn == "Y");

                if(targetLst.length > 0) {
                    var fileNms = "";
                    for(var idx=0, len=targetLst.length; idx < len; idx++ ) {
                        fileNms += "<br>"+targetLst[idx].serverFileName+ "("+targetLst[idx].errPdMsg+")";
                    }
                    for(var fileObj of targetLst) {
                        // filePath
                        var idx = dltObj.getMatchedIndex("rowID", fileObj.rowID);
                        dltObj.removeRow(idx);
                        pspsoltn.deleteFileOnServer(fileObj.serverFilePath);
                    }
                    if(targetLst.length == dltObj.getRowCount()) {
                        scutilo.showMsg(scglblo.MSG.CONFIRM, scutilo.getMsg(pspmsg.PSP.I_0484, fileNms));
                    }
                    else {
                        scutilo.showMsg(scglblo.MSG.CONFIRM, scutilo.getMsg(pspmsg.PSP.I_0483, fileNms), function(result) {
                            if(dltObj.getRowCount() > 0) {
                                fnSucc.call(this);
                            }
                        });
                    }
                }
                else {
                    fnSucc.call(this);
                }
            },
            error: function (e) {
                console.error(e);
            },
        });
  }
  else {
      fnSucc.call(this);
  }
};


/**
 * PDF 텍스트추출여부 확인
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.18.   우근석        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.fnPdfExtractTxtYn = function(dltObj, fnSucc) {

    var fnErr = function() {

    }
    dltObj.setColumnFilter({
        type: 'func', colIndex: "serverFileName", key: function (cellData, tmpParam, rowIdx) {
            return pspsoltn.getFileExt(cellData) === "pdf";
        }, condition: 'and'
    });
    let dltFilteredData = dltObj.getAllFilteredJSON();
    dltObj.clearFilter();

    if(dltFilteredData.length > 0) {
          com.executeAjax({
              action: "/psp/pspcom/selectPdfExtractTxt.on",
              requestData: JSON.stringify({
                  "dlt_fileLst" : dltFilteredData
              }),
              mode: "asynchronous",
              mediatype: "application/json",
              method: "POST",
              // processMsg : "PDF파일의 문자정보의 검색 및 추출여부를 확인하고 있습니다.", // 메시지문자열
              success: function (_data) {

                  var dltFileObj = _data?.responseJSON?.data?.dltFileLst;
                  var errtLst = dltFileObj.filter((fileObj)=> fileObj.errPdfYn == "Y");
                  var targetLst = dltFileObj.filter((fileObj)=> fileObj.txtExtractYn == "N" && fileObj.errPdfYn != "Y");
                  if(errtLst.length > 0 || targetLst.length > 0) {
                      var errfileNms    = "";
                      var fileNms       = "";
                      for(var idx=0, len=errtLst.length; idx < len; idx++ ) {
                          errfileNms += "<br>"+errtLst[idx].serverFileName+ "("+errtLst[idx].errPdMsg+")";
                      }
                      for(var idx=0, len=targetLst.length; idx < len; idx++ ) {
                          fileNms += "<br>"+targetLst[idx].serverFileName+ "("+targetLst[idx].errPdMsg+")";
                      }

                      var showMsg   = "";
                      var isType    = true;
                      // 첨부파일이 전부 오류인경우
                      if(errtLst.length > 0  && targetLst.length == 0) {
                          showMsg   = scutilo.getMsg(pspmsg.PSP.I_0484, errfileNms);
                          isType    = false;
                      } // 텍스트만 추출안된 경우
                      else if(errtLst.length == 0  && targetLst.length > 0) {
                          showMsg = scutilo.getMsg(pspmsg.PSP.I_0482, fileNms);
                      }// PDF오류이면서 텍스트가 추출안된경우
                      else {
                          showMsg = scutilo.getMsg(pspmsg.PSP.I_0482, fileNms);
                          showMsg += "<br>"+scutilo.getMsg(pspmsg.PSP.I_0484, errfileNms);
                      }

                      if(scutilo.isNotEmpty(showMsg) ) {
                          for(var fileObj of errtLst) {
                              // filePath
                              var idx = dltObj.getMatchedIndex("rowID", fileObj.rowID);
                              dltObj.removeRow(idx);
                              pspsoltn.deleteFileOnServer(fileObj.serverFilePath);
                          }

                          if(isType) {
                              scutilo.showConfirm(scglblo.MSG.CONFIRM, showMsg, function(result) {
                                  if (result.clickValue) {
                                      fnSucc.call(this);
                                  }
                                  else {
                                      // 첨부파일 삭제
                                      for(var fileObj of targetLst) {
                                          // filePath
                                          var idx = dltObj.getMatchedIndex("rowID", fileObj.rowID);
                                          dltObj.removeRow(idx);
                                          pspsoltn.deleteFileOnServer(fileObj.serverFilePath);
                                      }
                                      if(dltObj.getRowCount() > 0) {
                                          fnSucc.call(this);
                                      }
                                  }
                              });
                          }
                          else {
                              scutilo.showMsg(scglblo.MSG.CONFIRM, showMsg);
                          }
                      }
                  }
                  else {
                      fnSucc.call(this);
                  }
              },
              error: function (e) {
                  console.error(e);
              },
          });
    }
    else {
        fnSucc.call(this);
    }
};

