//입력한 문자열이 차세대 비밀번호로 유효한 문자열인지 체크하여, 유효한 경우 null을 반환, 아니면 오류 메시지 반환
psputils.chkValidPasswd = function(str){
	var emsg = "";

	if ( psputils.hasSpace(str) || psputils.hasTab(str) ) {
		return emsg + "\n(공백문자 제외)";
	}

	// 영문자가 없는 경우
	if ( ! psputils.hasLower(str) && ! psputils.hasUpper(str) ) {
		if ( ! psputils.hasNumber(str) ) {	// 특수문자로만 구성된 경우
			if ( psputils.hasSpecial(str) == '' ) {
				return emsg + "\n(영문자 또는 숫자 필요)";
			}
		}
		else{
			if ( ! psputils.hasSpecial(str) ) { // 숫자로만 구성된 경우
				return emsg + "\n(영문자 또는 특수문자 필요)";
			}
		}
	}
	else{
		if ( ! psputils.hasNumber(str) && ! psputils.hasSpecial(str)) {// 영문자로만 구성된 경으
			return emsg + "\n(숫자 또는 특수문자 필요)";
		}
	}

	if ( psputils.hasCharRepeat(str) ) {//같은문자/숫자/특수문자가 4번 반복일 경우
		return emsg + "\n(같은 문자 4번 반복)";
	}

	if ( psputils.hasContinuousChars(str) ) { // 연속된 문자열일 경우
		return emsg + "\n(순차적 문자열 (예) 1234, abcd, BCDE)";
	}

	if ( ! psputils.hasRuleChar(str) ) {// 사용할 수 없는 문자열일 경으
		return emsg + "\n(사용할 수 없는 문자열(대소문자 구분 불필요)사용 - 'qwer','asdf','zxcv','!@#$')";
	}
	/*
	if ( ! psputils.hasLower(str) ) {
		return emsg + "(소문자 필요)";
	}
	if ( ! psputils.hasUpper(str) ) {
		return emsg + "(대문자 필요)";
	}
	if ( ! psputils.hasNumber(str) ) {
		return emsg + "(숫자 필요)";
	}
	if ( ! psputils.hasSpecial(str) ) {
		return emsg + "(특수문자 필요)";
	}
	if ( psputils.hasCharRepeat(str) ) {
		return emsg + "(같은 문자 3번 반복)";
	}
	if ( psputils.hasContinuousChars(str) ) {
		return emsg + "\n(순차적 문자열 (예) 1234, abcd, BCDE)";
	}
	*/
	return null;
}

// 비밀번호(str)에 비교 문자열(str1)이 쓰였는지 체크
