//유니코드 문자열에서 ZWSP(Zero Width SPace) 문자열을 제거/변환 한 뒤 반환.
//(주의) 최초작성시 ZWSP는 [\u00A0, \u200B, \uFEFF] 3개만 제거했으며, 이후 필요시 나머지 ZWSP 추가로 제거 (@since 2023-10-20)
psputils.trimUniSpace = function(s) {
	if ( undefined==s || "" == s) { return s; }
	let t = s.replace(/\u00A0/g, ' '); //NO-BREAK SPACE ( 194 160 ) 를 space로 변경
		t = t.replace(/\u200B/g, ''); //Zero-Width SPace 제거
		t = t.replace(/\uFEFF/g, ''); //Zero-Width NO-BREAK SPace 제거
	return t;
}

// UTF-8 문자열의 바이트길이를 구하여 반환 (주의) ZWSP 제거해줘야 함
psputils.getByteLength = function(s) {
	if ( undefined==s || "" == s) {
		return 0;
	}
	//for(b=i=0;c=s.charCodeAt(i++);b+=c>>11?3:c>>7?2:1); return b;
	let t = psputils.trimUniSpace(s); //유니코드 문자열에서 ZWSP 제거/변환
	let te = new TextEncoder().encode(t);
	return te.byteLength;
}

psputils.getByteText = function(bytes, decimal=2) {
	if ( undefined==bytes || "" == bytes || 0===bytes ) {
		return '0 Bytes';
	}
    const k = 1024;
    const dm = decimal < 0 ? 0 : decimal;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];
}

//쿼리스트링의 해당 키 값을 구하여 반환, 지정한 키가 없으면  쿼리스트링의 전체 값을 객체로 반환
//(참조) WebSquare.net.paramObj 로 대체 가능//== pjgutils.urlparams();
psputils.urlparams = function(key) {
	/*
	const params = new Proxy(new URLSearchParams(window.location.search), {
		  get: (searchParams, prop) => searchParams.get(prop),
	});
	*/
	var urlSearchParams = new URLSearchParams(window.location.search);
	var params = Object.fromEntries(urlSearchParams.entries());
	if ( undefined==key || ""==key ) {
		return params;
	}
	return params[key];
}

//json (데이터)객체를 쿼리스트링 문자열로 변환. 2차원이상의 객체이면 prefix로 연결함 (예) { k1 : v1, k2 : {key2: val2} } == k1=k2&k2.key2=val2 (재귀)
psputils.serialize = function(obj, prefix) {
	var str = [], p;
	for (p in obj) {
		if (obj.hasOwnProperty(p)) {
		var k = prefix ? prefix + "." + p : p,
			v = obj[p];
			str.push((v !== null && typeof v === "object") ?
					psputils.serialize(v, k) :
					encodeURIComponent(k) + "=" + encodeURIComponent(v))
			;
		}
	}
	return str.join("&");
}

