 * ============= ============ ==========================
 *  2023.05.09.   안종광       [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.isHide = function(obj) {
    if ( null==obj ) { return null; } //객체가 null이면, null반환
    try {
        if ( 'none' === obj.getStyle('display') ) {
            return true; //스타일이 'none'
        }
        if ( ! obj.getParent() || 'body' == obj._wTagName ) {
            return false;
        }
    }
    catch(e) {
        _warn(`[ut#isHide] errMesg : ${e.message}`);
        _warn(`[ut#isHide] obj.elemnent.tagName : ${obj.element.tagName}`);
    }

    return psputils.isHide( obj.getParent() );
}

/**
 * <pre>
 * 문자열에 한자가 포함되어 있는지 확인
 *
 * </pre>
 *
 * @parameter chnchr(한자가 포함된 문자열): 필수
 * @return boolean(true : 한자포함, false : 한자 미포함)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.05.11.   이석원         [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.isChnchr = function(chnchr) {
	for (var i = 0; i < chnchr.length; i++) {
		if ((chnchr.charCodeAt(i) <= 0x9FA5 && chnchr.charCodeAt(i) >= 0x4E00)
				|| (chnchr.charCodeAt(i) <= 0xFA0B && chnchr.charCodeAt(i) >= 0xF900)) {
			return true;
		}
	}
	return false;
};

