/**
 * <pre>
 * 날짜 형식 체크
 *
 * @param {String|Number} 형식을 체크할 값
 * @return {msg} 검증 결과 메시지 리턴
 * @example
 * psputils.validateDate("20230101");
 *</pre>
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.11.13.   손수영       [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.validateDate = function(str) {
	if ( null==str || undefined==str || str.length!=8 ) { // W_1002: "[<%s>] 항목은 최소 <%s>자 이상 입력하세요.",
		return scutilo.getMsg(pspmsg.PSP.W_1002, "날짜", "8");
	}
	//var thedate = new Date('19'+str.substring(0,2), str.substring(2,4), str.substring(4)); //Date parse 는 검증안됨.
	var m = str.substring(4,6);
	if ( !isFinite(m) || parseInt(m)>12 || 1>parseInt(m) ) {
		return scutilo.getMsg(pspmsg.PSP.W_1011, "날짜", "(월)"); //W_1011: "[<%s>] 정보를 정확히 입력하세요. <%s>",
	}
	var d = str.substring(6);
	if ( !isFinite(d) || parseInt(d)>31 || 1>parseInt(d) ) {
		return scutilo.getMsg(pspmsg.PSP.W_1011, "날짜", "(일)");
	}
	switch( parseInt(m) ) {
	case 2 : if ( parseInt(d)>29 ) { return scutilo.getMsg(pspmsg.PSP.W_1011, "날짜", "(일)"); } break;
	case 4 :
	case 6 :
	case 9 :
	case 11 : if ( parseInt(d)>30 ) { return scutilo.getMsg(pspmsg.PSP.W_1011, "날짜", "(일)"); } break;
	default : break;
	}
	return null;
}


/**
 * byte를 받아 MB 인경우 MB로 KB 인경우 KB로 반환한다.
 *
 * ex) cfFileSizeNm("1125112") = "1.07MB"
 *     cfFileSizeNm("86016")   = "84,0KB"
 *
 * @param  {Object} obj         변환대한 파일사이즈
 * @return {Object} fileSizeNm  변환된 파일 사이즈
 * @see cfFileSizeNm
 *</pre>
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.29.   황은관       [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.cfFileSizeNm = function (obj) {

  var fileSizeNm = "";

  try {

    if (obj != null && obj != "") {
      if ((parseInt(obj) / 1024 / 1024) >= 1) {
        fileSizeNm = (Math.round((obj / 1024 / 1024) * 100) / 100) + "MB";
      } else {
        fileSizeNm = (Math.round((obj / 1024) * 10) / 10) + "KB";
      }
    } else if (obj <= 0) {
      fileSizeNm = 0 +"KB";
    }

    return fileSizeNm;

  } catch(e) {
    throw e;
  }
};

/**
 * 파일경로에서 파일명을 추출
 *
 * @param  sFilePath  파일경로 또는 파일명자체 (예) "C:\\Users\\usr\\Documents\\첨부파일예제\\첨부파일 업로드 테스트 hwp 파일 01.hwp" (or) "첨부파일 업로드 테스트 hwp 파일 01.hwp"
 * @return 파일명 (예) "첨부파일 업로드 테스트 hwp 파일 01.hwp"
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.11.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.getFileName = function(sFilePath) {
	var lastIdx = sFilePath.lastIndexOf('\\');
	if ( 0>lastIdx ) {
		lastIdx = sFilePath.lastIndexOf('/');
	}
	return 0>lastIdx ? sFilePath : sFilePath.substring(1 + lastIdx);
}
// 파일확장자를 제외한 파일명을 반환 (예) "첨부파일 업로드 테스트 hwp 파일 01.hwp" 이면 [첨부파일 업로드 테스트 hwp 파일 01] 반환
psputils.getFileNameOnly = function(sFilePath) {
	var filename = psputils.getFileName(sFilePath);
	var lastIdx  = filename.lastIndexOf(".");
	return 0>lastIdx ? filename : filename.substring(0, lastIdx);
}
//파일확장자를 반환(소문자) (예) "첨부파일 업로드 테스트 hwp 파일 01.HWP" 이면 [hwp] 반환
psputils.getFileExt = function(sFilePath) {
	var filename = psputils.getFileName(sFilePath);
	var lastIdx  = filename.lastIndexOf(".");
	return 0>lastIdx ? "" : filename.substring(1 + lastIdx).toLowerCase();
}

/**
 * pdf 확장자인 파일명으로 변환하여 반환
 *
 * @param  sFileName  (예) "첨부파일 업로드 테스트 hwp 파일 01.hwp"
 * @return pdf 확장자인 파일명  (예) "첨부파일 업로드 테스트 hwp 파일 01.pdf"
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.22.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.getPdfFileName = function(sFileName, doReplaceWhitespace) {
	var lastIdx = sFileName.lastIndexOf('.');
	var fileExt = sFileName.substring(1 + lastIdx).toLowerCase();
	if ( "pdf"==fileExt ) {
		return sFileName;
	}
	var pdfFileName = sFileName.substring(0, lastIdx) + "." + "pdf";
	return undefined!=doReplaceWhitespace && false===doReplaceWhitespace ? pdfFileName : pdfFileName.replace(/\s/g, '_');
}


/**
 * Blob를 Base64로 변경
 *
 * @param  blob             Blob
 * @param  filename         첨부파일명
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.08.07.   우근석        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.BlobToBase64 = function(blob, filename) {
    var reader = new FileReader();
    reader.readAsDataURL(blob);
    reader.onloadend = function() {
        var base64Data  = reader.result;
        if(scutilo.isEmpty(base64Data)) {
             scutilo.showMsg(scglblo.MSG.ERROR, "다운로드하려는 파일에 문제가 있습니다.", function() {});
        }
        else {
            $h.common.downloadFile(() => {
//                console.log('===============> succ');
            }, {  "fileName" : filename
                , "data"     : base64Data });
        }
    };
};

/**
