/**
 * (smko를 통해) 업로드된 첨부파일을 EDMS에 등록 처리후 결과를 반환, 또는 콜백함수에 결과정보를 전달하여 호출
 *
 * @param  elpUserId      첨부파일 등록한 사용자ID(또는 세션사용자ID)
 * @param  oFileInfo      (smko를 통해) 업로드된 첨부파일 정보 (1건객체 또는 배열객체 가능)
 * @param  callback       EDMS에 등록결과 DataList (참고) dlt_registerFilesRes
 * @return
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.07.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.regEdms = function(elpUserId, oFileInfo, callback, fnErr) {

    if ( scutilo.isEmpty(elpUserId) ) {
        //elpUserId = "anonymous";
        _error("[u#regEdms] 로그인 정보 없음!");
        var msg = scutilo.getMsg(pspmsg.PSP.W_0328, "파일을 EDMS에 등록할 수 없습니다.\n\n먼저 로그인"); //W_0328: "<%s> 하시기 바랍니다."
        scutilo.showMsg(scglblo.MSG.ERROR, msg, function(r) {
            if ( null!=callback && 'function' == typeof callback ) {
                callback.call(null, null);
            }
        });
        return null;
    }
    if ( null==oFileInfo || 'object' != typeof oFileInfo ) {
        _error("[u#regEdms] 파일정보 없음.");
        return null;
    }


    if(fnErr === undefined ) {
        var fnErr = function () {
            scutilo.showMsg(scglblo.MSG.ERROR, scutilo.getMsg(pspmsg.PSP.E_0400, "첨부파일 등록")); //처리중오류가 발생하였습니다.
            dltObj.removeAll();
        }
    }
    var sDocNm = null;
    var regfiles = [];
    var compSzie = 0;

    if ( $.isArray(oFileInfo) ) {
