/**
 * 프레임아이디를 웹스퀘어 scope 문자열로 반환
 * (용도) 이후 함수명 문자열을 더하여 eval(scope문자열 + 함수명) 로 함수객체를 구하기 위함.
 *
 * (사용예)
 * (1) "mf_pfwork_wfm_tab02_wfm_bndLst" =▷ "$p.top().pfwork.scope.wfm_tab02.scope.wfm_bndLst.scope"
 * (2)           "wfm_tab02_wfm_bndLst" =▷ "$p.top().pfwork.scope.wfm_tab02.scope.wfm_bndLst.scope"
 * (3)                      "wfm_csBas" =▷ "$p.top().pfwork.scope.wfm_csBas.scope"
 * (4)            "wfm_csBas_wfm_tab01" =▷ "$p.top().pfwork.scope.wfm_csBas.scope.wfm_tab01.scope"
 *
 * @param	sFrameId	프레임ID(문자열)
 * @return	해당 프레임의 스코프 문자열
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.toScopeString = function(sFrameId) {
	if ( scutilo.isEmpty(sFrameId) ) {
		return psputils.DEFAULT_SCOPE; // "$p.top().pfwork.scope"; //디폴트 scope 문자열
	}
	var scopeString = psputils.DEFAULT_SCOPE;

	var prefix = "wfm_";
	var arrFrmId = sFrameId.split(prefix); //(/wfm_/); //(예)  ['mf_pfwork_', 'tab02_', 'bndLst']

	for( var frmId of arrFrmId ) {
		if ( scutilo.isEmpty(frmId) || frmId=='mf_pfwork_' ) {
			continue;
		}
		scopeString += "." + prefix + frmId;
		scopeString = scopeString.replace(/[./_]$/, "") + ".scope"; //(예) tab02_ ==> tab02.scope
	}
	return scopeString;
}


/**
 * 현재 업무화면영역내의 [아코디언패널 내 wframe]에서 해당 제목을 가진 wframe 아이디를 구하여 반환
 * (예) '신청취지'인 프레임아이디를 구함. [mf_pfwork_]wfm_aplyIntntResn
 *
 * @param	sPanelTitle		프레임제목(일치가 아니라 포함으로 체크), 만약 제목을 넘기지 않으면 (, 분리) 전체 프레임아이디
 * @return	해당 제목에 매핑된 프레임아이디
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.09.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.frameIdByTitle = function(sPanelTitle) {
	var frameId = "";
	var frames = WebSquare.util.getChildren($p.top().pfwork, {recursive:true, includePlugin:"wframe"});

	if ( scutilo.isEmpty(sPanelTitle) ) {
		for(let i=0; i<frames.length; i++) {
			frameId += (scutilo.isEmpty(frameId) ? "" : ",") + frames[i].id;
		}
		return frameId;
	}

	var panels = WebSquare.util.getChildren($p.top().pfwork, {recursive:true, includePlugin:"panels"});

	for(let i=0; i<panels.length; i++) {
		if ( panels[i] && panels[i].panelTitle && panels[i].panelTitle.options.label.indexOf(sPanelTitle)>=0 ) {
			frameId = frames[i].id; //'mf_pfwork_wfm_aplyIntntResn'
			break;
		}
	}
	return scutilo.isEmpty(frameId) ? null : frameId.replace(/mf_pfwork_/, '');
}

