psputils.copyClipBoard = function(comObj) {
	if(navigator.clpboard){
		navigator.clipboard.writeText(comObj.render.innerText);
	}else{
	    var content = document.createElement('textarea');
	    content.value = comObj.render.innerText;
	    content.setAttribute('readonly', '');
	    content.style.position='absolute';
	    content.style.left = '9999px';
	    document.body.appendChild(content);
	    content.select();
	    document.execCommand('copy');
	    document.body.removeChild(content);
	}
}

/**
 * 숫자 또는 숫자형문자열에 콤마(,)를 표시 (참고) 빈값 또는 숫자형이 아니면 그대로 반환
 *
 * @param	num		숫자 또는 숫자형 문자열 (예) 1234, 1234.567, '1234567', '1234567.8901'
 * @return	콤마를 추가할 숫자형 문자열 (예) '1,234', '1,234,567.8901'
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.22.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.putComma = function(num)  {
	if ( null==num || true==isNaN(num) || scutilo.isEmpty(num) ) { return num; } //그대로 반환
	var s = ""+num; //문자열로 바꾸어 처리
	var arr = s.replace(/,/g,"").split(".");
	return arr[0].replace(/\d(?=(?:\d{3})+$)/g, '$&,') + ( 2>arr.length ? "" : "."+arr[1] );
};

