/**
 * 문자열, 객체, 배열을 인코딩하여 반환
 *
 * @param   obj         인코딩할 객체등
 * @param   doKeyEnc    객체일 경우, 키를 인코딩할지 여부(디폴트 true)
 * @return  인코딩결과 객체(입력이 객체이면 객체, 배열이면 배열, 나머지는 문자열)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.22.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.encode = function(obj, doKeyEnc=true) {
	if (null==obj) { return null; }
	if ('function'==typeof obj) { return obj; } //함수는 그대로반환
	if ('string'==typeof obj || 'number'==typeof obj || 'boolean'==typeof obj || 'bigint'==typeof obj) { return scutilo.encode(obj); }

	let isArr = scutilo.isArray(obj);
	let objEncoded = isArr ? [] : {};

	try {
		for (let keyOrItem in obj) {
			if ( true===isArr ) {
				objEncoded.push( psputils.encode(obj[keyOrItem], doKeyEnc) );
			}
			else {
				let keyEnc = true==doKeyEnc ? scutilo.encode(keyOrItem) : keyOrItem; //키를 인코딩(true시)
				let valEnc = psputils.encode(obj[keyOrItem]); //값을 인코딩
				objEncoded[keyEnc] = valEnc;
			}
		}
	}
	catch(e) {
		_error("[ut#enc]", e.message);
		objEncoded = obj;
	}
	return objEncoded;
}

/**
 * 인코딩되어 있는 문자열, 객체, 배열을 디코딩하여 반환
 *
 * @param   obj         디코딩할 객체등
 * @param   doKeyEnc    객체일 경우, 키가 인코딩 되어 있는지 여부(디폴트 true)
 * @return  디코딩결과 객체(입력이 객체이면 객체, 배열이면 배열, 나머지는 문자열)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.22.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.decode = function(obj, doKeyEnc=true) {
	if (null==obj) { return null; }
	if ('function'==typeof obj || 'number'==typeof obj || 'boolean'==typeof obj || 'bigint'==typeof obj) { return obj; } //이런 타입은 디코딩시 그대로 반환
	if ('string'==typeof obj) { return 'AA=='==obj ? '' : scutilo.decode(obj); }

	let isArr = scutilo.isArray(obj);
	let objDecoded = isArr ? [] : {};

	try {
		for (let keyOrItem in obj) {
			if ( true===isArr ) {
				objDecoded.push( psputils.decode(obj[keyOrItem], doKeyEnc) );
			}
			else {
				let keyDec = true==doKeyEnc ? scutilo.decode(keyOrItem) : keyOrItem; //키를 디코딩(true시)
				let valDec = psputils.decode(obj[keyOrItem]); //값을 디코딩
				objDecoded[keyDec] = valDec;
			}
		}
	}
	catch(e) {
		_error("[ut#dec]", e.message);
		objDecoded = obj;
	}
	return objDecoded;
}

/**
 * 한국어 조사("은"/"는") 가져오기
 *
 * 함수는 입력된 단어의 마지막 글자를 확인하여 받침이 있는지 판단하여 조사 반환.
 * 만약 단어의 마지막 글자가 받침이 있는 한글 문자라면 "은"을 반환, 그렇지 않으면 "는"을 반환.
 * 한글이 아닌 경우 기본적으로 "는"을 반환.
 *
 * @param {string} word - 조사를 결정할 입력 단어.
 * @returns {string} - 단어의 마지막 글자에 받침이 있으면 "은"을 그렇지 않으면 "는"을 반환.
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.05.29.   백인호        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.getJosa = function(word) {
	// 문자가 아닐 경우 "는" return
	if (!word || typeof word !== 'string') {
		return "는";
	}

	const lastChar = word[word.length - 1];
	const lastCharCode = lastChar.charCodeAt(0);

	// 마지막 문자가 한글인지 확인
	const isHangul = lastCharCode >= 0xAC00 && lastCharCode <= 0xD7A3;
	if (!isHangul) {
		return "는";
	}

	// 한글 유니코드 범위 내에서 마지막 글자의 받침 확인
	const isFinalConsonant = (lastCharCode - 0xAC00) % 28 > 0;

	return isFinalConsonant ? "은" : "는";
}

/**
 * 한국어 조사("을"/"를") 가져오기
 *
 * 함수는 입력된 단어의 마지막 글자를 확인하여 받침이 있는지 판단하여 조사 반환.
