}

psp.env.isMobile = function() { //모바일이면 true
	const _ua_ = navigator.userAgent;
	return  _ua_.indexOf("Mobile") > 0 &&
			( _ua_.indexOf("iPhone") > 0 || _ua_.indexOf("iPad") > 0 || _ua_.indexOf("Android") > 0 );
}

psp.env.isMobileWeb = function() { //모바일웹이면 true
	return psp.env.isMobile() && ! psp.env.isMobileApp(); //PMB 가이드 적용 참조
}

