psp.env.isMobileSize = function() { //모바일 사이즈이면 true
	var windowWidth = window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth;
	return windowWidth < 1024;
}

psp.env.isStdWeb = function() { //일반웹이면 true
	return ! psp.env.isMobileApp() && ! psp.env.isMobile();
}

psp.env.isIPhone = function() { //iPhone이면 true
	return ( navigator.userAgent.indexOf("iPhone") > -1);
}

psp.env.isIPad = function() { //iPad이면 true
	return ( navigator.userAgent.indexOf("iPad") > -1);
}

psp.env.isAndroid = function() { //Android이면 true
	return ( navigator.userAgent.indexOf("Android") > -1);
}

