}
psp.env.isFirefox = function() { //Firefox 브라우저이면 true
	return ( navigator.userAgent.indexOf("Firefox/") > -1); // '~ (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0'
}
psp.env.isEdge = function() { //Firefox 브라우저이면 true
	return ( navigator.userAgent.indexOf("Edg/") > -1); // '~ (Windows NT 10.0; Win64; x64) ~ Chrome/103.0.5060.134 Safari/537.36 Edg/103.0.1264.71'
}
psp.env.isChrome = function() { //Chome 브라우저이면 true
	return !psp.env.isOpera() && !psp.env.isFirefox() && !psp.env.isEdge() &&
			( navigator.userAgent.indexOf("Chrome/") > -1 ); // '~ (Windows NT 10.0; Win64; x64) ~ Chrome/103.0.0.0 Safari/537.36'
}
psp.env.isSafari = function() { //Safari 브라우저이면 true
	return !psp.env.isOpera() && !psp.env.isFirefox() && !psp.env.isEdge() && !psp.env.isChrome() &&
			( navigator.userAgent.indexOf("Mac") > -1 ) && ( navigator.userAgent.indexOf("Safari") > -1 ); // '~ Mozilla/5.0 (iPad; CPU OS 11_0 like Mac OS X) AppleWebKit/604.1.34 (KHTML, like Gecko) Version/11.0 Mobile/15A5341f Safari/604.1'
}
psp.env.isIE = function() { //Internet Explorer 브라우저이면 true
	return ( navigator.userAgent.indexOf("Trident/") > -1); // '~ (Windows NT 10.0; Trident/7.0; rv:11.0) like Gecko'
}
psp.env.getUUID = function() {	//모바일 장치 고유값인 UUID 반환
	let uuid = "";
	if (psp.env.isMobileApp()) {
		uuid = $h.device.getDeviceInfo().uuid;
		if (psp.env.isAndroid()) {
			let deviceId = uuid.toUpperCase();
			uuid = deviceId.substr(0, 8) + "-" + deviceId.substr(8, 4) + "-" + deviceId.substr(12);
		}
	}
	else {
		uuid = "Unknown";
	}
    return uuid;
}

