pspadmin.onMenuClick = function(paramMenuInfo) {
    var menuObj = null;
    var menuInfo = null;
    var menuInfoObj = null;

    try {
        menuObj = WebSquare.util.getComponentById(this.id); //this == menulink 객체 (ex) $("#mf_pfheader_"+"grp_mn1")[0];
        menuInfo = menuObj.getUserData("menuinfo");
