/**
 * <pre>
 * 화면(프로그램)ID로 해당 xml 화면을 작업영역(pfwork)에 로드 처리
 * (참조) PSPLayoutDefault.xml
 *
 * </pre>
 *
 * @param   mPgmId    주화면프로그램ID (예) PSP611M01
 * @param   sPgmId    부화면프로그램ID (예) PSP611M02
 * @param   paramObj  전달할 파라미터(객체)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
pspadmin.load_page = function(mPgmId, sPgmId, paramObj) {
    _trace("[#l_p] <mPID>", mPgmId, "<sPID>", sPgmId, "<param>", paramObj, "");

    var pageinfo = psp.getXmlPath2Load(mPgmId, sPgmId); //this.getXmlPathByPgmId(mPgmId); // scwin.getXmlPathByPrgmId(s);
    _trace("[#l_p] <pageinfo>", pageinfo);

    var menuinfo = pspadmin.getMenuInfo(mPgmId); //로드할 메뉴정보
    var menuname = "" + mPgmId;
    var currMenuinfo = psp.ss.get(pspadmin.LS_KEY_MN_C, true);

    if ( null!=menuinfo ) { //1. 이동할 메뉴 정보가 있음(메뉴 클릭시)
        menuname = menuinfo["menuNm"];
        psp.ss.set(pspadmin.LS_KEY_MN_C, menuinfo); //현재 메뉴(psp_currmenu)에 '로그할 메뉴'로 저장

        if ( null==currMenuinfo || menuinfo.elpMenuSrno == currMenuinfo.elpMenuSrno ) {
        	psp.ss.remove(pspadmin.LS_KEY_MN_P); //이전 메뉴(psp_prevmenu) 정보 삭제
        }
        else {
        	psp.ss.set(pspadmin.LS_KEY_MN_P, currMenuinfo); //이전 메뉴에 '바로전 메뉴'정보 저장
        }
    }
    else { //2. 메뉴정보가 없는 경우
        // (1) 상세페이지로 이동(정상) (2) 잘못된 프로그램ID(오류)
        if ( ! mPgmId.startsWith("PSP9") ) {
        	menuname = "오류가 발생하였습니다!";
        	pageinfo.viewpath = psp.CONTEXT_ROOT + "/ui/pspcom/pferror.xml";
        }
    }

    pageinfo["viewname"] = menuname;
    var ssparam = psp.ss.get(pspadmin.SS_PAGEPARAM, true);
    var dat = {};

    Object.assign(dat, ssparam, paramObj, pageinfo); //Object.assign(dat, pageinfo, paramObj, ssparam);
    _trace("[#l_p] <pageinfo>", pageinfo);
    _trace("[#l_p] <paramObj>", paramObj);
    _trace("[#l_p] <ssparam>", ssparam);
    _trace("[#l_p] <params>", dat);

    var params = {
        "dataObject": {
            "type" : "json",
            "name" : "wframeParam",
            "data" : dat
        }
    };

    // 전달된 파라미터(m,s)의 값으로 해당 페이지를 '작업영역'에 로드
    $p.top().pfwork.setSrc(pageinfo.viewpath, params); //WORK_FRAME_ID = pfwork
};

/**
 * 지정한 주프로그램ID 화면으로 이동처리함.
 *
 * @param  mPgmId      주프로그램ID
 * @param  queryParam  URL 쿼리스트링에 포함하여 전달할 정보(객체) (예) { s=주프로그램ID, debugger=디버그모드 켜기/끄기, 기타 }
 * @param  objParam    해당 주프로그램ID에 전달할 정보(객체) (참고) 이 정보는 sessionStorage에 임시 저장 (예) { 공지사항ID, ... 등 }
 * @param  keepCurrSsParam    현재 ss에 저장중인 파라미터 객체를 유지할지 여부 (true여야 유지)
 */
pspadmin.go_url = function(mPgmId, queryParam, objParam, keepCurrSsParam) {
	//var curUrlParam = WebSquare.net.paramObj;
	var _url = {}
	if ( null!=queryParam ) {
		for (ky in queryParam) { //쿼리스트링으로 전달할 파라미터의 값이 문자열 'null', 'undefined' 이면 키 자체를 제거함.
			if (queryParam.hasOwnProperty(ky)) {
				let val = queryParam[ky];
				if ( "null"===val || "undefined"===val ) {
					delete queryParam[ky];
				}
			}
		}
		Object.assign(_url, queryParam); //디폴트 현재 쿼리스트링을 이동할 쿼리스트링에 추가
	}
	if ( ! scutilo.isEmpty(mPgmId) ) {
		_url["m"] = mPgmId;
	}

	var _param = {};
	if ( null!=keepCurrSsParam && true==keepCurrSsParam ) {
		var ssdata = psp.ss.get(pspadmin.SS_PAGEPARAM, true);
		//var ssdata = JSON.parse(window.sessionStorage.getItem(psp.SS_PAGEPARAM));
		Object.assign(_param, ssdata); //현재 페이지로 전달되었던 param 객체를 유지
	}
	if ( null!=objParam ) {
		Object.assign(_param, objParam); //전달된 param 객체를 병합
	}
	psp.ss.set(pspadmin.SS_PAGEPARAM, _param);

	var querystring = psputils.serialize(_url);

	//$p.url("index.on" + (scutilo.isEmpty(querystring) ? "" : "?"+querystring));
	$p.url("index119.on" + (scutilo.isEmpty(querystring) ? "" : "?"+querystring));
};

/**
 * 페이지 초기화 처리후
 * 웹스퀘어 파라미터(wframeParam)와 추가 파라미터를 합쳐서 반환
 *
 * @param	wsObj		웹스퀘어 오브젝트
 * @param	addParam	추가 파라미터 객체
 * @return	페이지 파라미터(wframeParam)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
pspadmin.getPageInit = function(wsObj, addParam) {

	var frmId = ""; // wsObj == $p
	try {
		frmId = wsObj.getFrame().id; // mf_pfwork (or) mf_pfwork_wfm_csBas (or) mf_pfwork_wfm_csBas_...
	}
	catch(e) {
		frmId = "mf_pfwork";
	}
	_trace("[#getPageInit] frame ID :", frmId);

	if ( "mf_pfwork" != frmId ) {
		return psp.getPageParam(wsObj); //하위 프레임이 로드되면, 전달된 파라미터객체만 전달하면 됨.
	}

	//scglblo.setCtxtPath("/psp");
	var _scmain = scutilo.getSCMain();
	if ( null==_scmain.scglblo.getCtxtPath() ) {
		_scmain.scglblo.setCtxtPath("/psp");
	}

	_trace("[pspadmin.js#getPageInit] (_scmain) context path : " + _scmain.scglblo.getCtxtPath() + "");
	_trace("[pspadmin.js#getPageInit] added param : ", addParam);

	var pageparam = psp.getPageParam(wsObj);
	_trace("[pspadmin.js#getPageInit] page param :", pageparam);

	//1. 페이지타이틀(id = tbx_pagetitle)의 텍스트를 메뉴명으로 교체
	if ( "sub"!=pageparam.viewtype ) {
		var pgTtlComp = psp.componentById("tbx_pagetitle", psp.WORK_FRAME_ID); //==mf_pfwork_tbx_pagetitle
		try {
			pgTtlComp.setValue(pageparam["viewname"]);
		}
		catch(e) {
			_error("[#getPageInit]", "tbx_pagetitle 없음.");
		}
	}

	psp.initPagePrintComponent(pageparam); // 화면출력을 위해 추가함.

	var viewid = null;

	//2. 메뉴경로 표시
	try {
		pspadmin.displayMenuPath(pageparam); //build_screen_path();

		viewid = scutilo.isEmpty(pageparam["viewid"]) ? "" : pageparam["viewid"];

		if ( scutilo.isNotEmpty(viewid) ) {
			//var _url = "index.on?s=" + viewid;
			var _url = "index119.on?s=" + viewid;
			_trace("[pspadmin.js#getPageInit] history :", _url);
			//history.pushState({ data: pageparam }, null, _url);
		}
		//psp.build_screen_path();
	}
	catch(e) {
		_error("[#getPageInit]", "build_screen_path() ", e.description);
	}

	try { //4.2) 메인(Mxx)에서는 프로그램ID를 헤더에 설정함
		scscrno.setScPgmId(pageparam["viewid"]);
	}
	catch(e) {
		_error("[#getPageInit] 기타 처리", e.description);
	}

	return pageparam;
};

/**
 * <pre>
 * 페이징 처리를 위한 정보를 셋팅한다.
 * 클릭되 페이지 이동 후 상세페이지 이동 처리 후 다시 목록으로 돌아올 경우 클릭했던 페이지로 바로 가도록 추가 및 수정 처리
 *
 * @memberOf scutilo
 *
 * @example ex)
 * scutilo.setPagingInfo(dma_pageInfo, pgl_addr, grd_addr);
 *
 * @param {Object} dmaObj - 페이징 처리를 위한 datamap 정보
 * @param {Object} pglObj - 페이징 컴포넌트
 * @param {Object} grdObj - 페이징 처리를 하기위한 gridView
 *
 * </pre>
 */
pspadmin.setPagingInfo = function (dmaObj, pglObj, grdObj) {
	var dataObj = dmaObj.getJSON();

	if(dataObj.totalCnt === 0){
		pglObj.hide();
		return;
	} else {
		pglObj.show();
	}

    var isInit = false;
    var pageSize=0;
    if(dataObj.pageNo == 1){
        isInit = true;
    }

    pageSize = com.util.getPageSize(dataObj.totalCnt, dataObj.pageSize);
    pglObj.setCount( pageSize , !isInit );
    pglObj.setValue(dataObj.pageNo);

    //gridView인덱스가 0부터 시작함
    grdObj.setStartRowNumber(dataObj.startRowNo-1);
    grdObj.setFocusedCell(0, 0);
};





