pspadmin.bindCsYear = function(dcId) {
    var date = new Date();
    var nowYear = date.getFullYear();
    var startYear = 1998;
    var yearCnt = nowYear - startYear;

    for (var i = 0; i <= yearCnt; i++) {
    	dcId.addItem(nowYear-i, nowYear-i);
    }

    dcId.setValue(dcId.setSelectedIndex(0));
};

/**
 * <pre>
 * 화면별 재판사무업무유형코드를 콤보박스에 바인딩한다.
 *
 * 1.dataCollection 생성 ->  ID에  label, value 생성
 * 2.selectBox -> BindItemSet 체크 -> NodeSet:dataCollection Id 선택 -> Label : label 선택 -> Value : value 선택
 *
 * howToUse) pspadmin.bindJdcpcOfcwkTaskTypCd(sbxId[, pgmId, isSync])
 * ex) pspadmin.bindJdcpcOfcwkTaskTypCd("sbx_jdcpcOfcwkTaskTypCd", null, false);
 * </pre>
 *
 * @parameter String {sbxId: 콤보박스ID}
 * @parameter String {pgmId: 프로그램ID}
 * @parameter boolean {isSync: sync여부}
 * @parameter boolean {isCodeAdd: 코드명에코드값추가여부}
 * @return boolean
 * @see (asis) adminCommon.js-cfSelSysCd
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.08.25.    김영범          [NELS] 최초생성
 * ============= ============ ==========================
 */
pspadmin.bindJdcpcOfcwkTaskTypCd = function(sbxId, pgmId, isSync, isCodeAdd) {
	return new Promise((resolve, reject) => {
		if (scutilo.isEmpty(sbxId)) {
			reject(false);
			return false;
		}

		let sbxObj = psp.componentById(sbxId);
		let dcObj = psp.componentById(sbxObj.getDataListInfo().id);

		if (scutilo.isEmpty(dcObj)) {
			reject(false);
			return false;
		}

		if (scutilo.isEmpty(pgmId)) {
			pgmId = "OTHER_PGM";
		}

		let mode = (isSync)? "synchronous" : "asynchronous";
		if(scutilo.isEmpty(isCodeAdd)) isCodeAdd = true;

	    com.executeAjax({
	        action: psp.CONTEXT_ROOT + "/pspadm/selectComCdLst.on",
	        mode: mode,
	        method: "POST",
	        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
	        requestData: JSON.stringify({
	            systmCd: "PSP",
	            cdId: "JDCPC_OFCWK_TASK_TYP_CD"
	        }),
	        success: function(rslt) {
	        	let datLst = rslt.responseJSON.data.result;
	        	let rsltArr = [];
	        	let selectedCdLst = null;

	        	pspadmin.C.JDCPC_OFCWK_TASK_TYP_CD_BY_PGM_ID.forEach(function(val, idx, arr) {
	        		if (val.pgmId == pgmId) {
	        			selectedCdLst = val.jdcpcOfcwkTaskTypCdLst;
	        			return false;
	        		}
	        	});

	        	selectedCdLst.forEach(function(val, idx, arr) {
	        		if ("ALL" == val) {
	        			if(isCodeAdd) rsltArr.push({value: "", label: "-전체-"});
	        			else rsltArr.push({value: "ALL", label: "전체"});
	        			return false;
	        		}
	        	});

	        	datLst.forEach(function(val, idx, arr) {
	        		if (selectedCdLst.includes(val.value)) {
	        			if(isCodeAdd) rsltArr.push({value: val.value, label: "(" + val.value + ") " + val.label});
	        			else rsltArr.push({value: val.value, label: val.label});
	        		}
	        	});

	        	dcObj.setJSON(rsltArr);

	        	return resolve(true);
	        },
	        error: function (e) {
	            alert("error code : " + e.responseStatusCode);
	            reject(false);
	        },
	    });
	});
};

