	        	dcObj.setJSON(datLst);

	        	if (psp.C.PT == jdcpcOfcwkTaskTypCd) {//특허사건의 경우 특허법원을 먼저 보이도록 함
	        		sbxObj.setValue(psp.C.PTBUB);
	        	}

	        	return resolve(true);
	        },
	        error: function (e) {
	            alert("error code : " + e.responseStatusCode);
	            reject(false);
	        },
	    });
