 * ex) pspadmin.bindCsDvsCdByCortCd("sbx_jdcpcOfcwkTaskTypCd", "sbx_cort", "sbx_csDvsCd", false);
 * </pre>
 *
 * @parameter String {jdcpcOfcwkTaskTypCdSbxId: 재판사무업무유형코드콤보박스ID}
 * @parameter String {cortCdSbxId: 법원코드콤보박스ID}
 * @parameter String {csDvsCdSbxId: 사건구분코드콤보박스ID}
 * @parameter boolean {isSync: sync여부}
 * @return boolean
 * @see (asis) adminCommon.js-cfSelBubCommByAdmSys
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.08.28.    김영범          [NELS] 최초생성
 * ============= ============ ==========================
 */
pspadmin.bindCsDvsCdByCortCd = function(jdcpcOfcwkTaskTypCdSbxId, cortCdSbxId, csDvsCdSbxId, isSync) {
	return new Promise((resolve, reject) => {
		if (scutilo.isEmpty(jdcpcOfcwkTaskTypCdSbxId)
		||  scutilo.isEmpty(cortCdSbxId)
		||  scutilo.isEmpty(csDvsCdSbxId)) {
			reject(false);
			return false;
		}

		let jdcpcOfcwkTaskTypCdSbxObj = psp.componentById(jdcpcOfcwkTaskTypCdSbxId);
		let jdcpcOfcwkTaskTypCdDcObj = psp.componentById(jdcpcOfcwkTaskTypCdSbxObj.getDataListInfo().id);
		let cortCdSbxObj = psp.componentById(cortCdSbxId);
		let cortCdDcObj = psp.componentById(cortCdSbxObj.getDataListInfo().id);
		let csDvsCdSbxObj = psp.componentById(csDvsCdSbxId);
		let csDvsCdDcObj = psp.componentById(csDvsCdSbxObj.getDataListInfo().id);

		if (scutilo.isEmpty(jdcpcOfcwkTaskTypCdSbxObj)
		||  scutilo.isEmpty(jdcpcOfcwkTaskTypCdDcObj)
		||  scutilo.isEmpty(cortCdSbxObj)
		||  scutilo.isEmpty(cortCdDcObj)
		||  scutilo.isEmpty(csDvsCdSbxObj)
		||  scutilo.isEmpty(csDvsCdDcObj)) {
			reject(false);
			return false;
		}

		let mode = (isSync)? "synchronous" : "asynchronous";
		let jdcpcOfcwkTaskTypCdLst = [];
		let cortCdLst = [];

		if (scutilo.isEmpty(jdcpcOfcwkTaskTypCdSbxObj.getValue())) { //전체
			jdcpcOfcwkTaskTypCdDcObj.getAllJSON().forEach((val, idx, arr) => {
				if (scutilo.isNotEmpty(val.value)) {
					let dat = {
							jdcpcOfcwkTaskTypCd: val.value
					};

					jdcpcOfcwkTaskTypCdLst.push(dat);
				}
			});
		}
		else {
			let tmpJSON = jdcpcOfcwkTaskTypCdDcObj.getMatchedJSON("value", jdcpcOfcwkTaskTypCdSbxObj.getValue());

			tmpJSON.forEach((val, idx, arr) => {
				let dat = {
						jdcpcOfcwkTaskTypCd: val.value
				};

				jdcpcOfcwkTaskTypCdLst.push(dat);
			});
		}

		if (scutilo.isEmpty(cortCdSbxObj.getValue())) { //전체
			cortCdDcObj.getAllJSON().forEach((val, idx, arr) => {
				if (scutilo.isNotEmpty(val.value)) {
					let dat = {
							cortCd: val.value
					};

					cortCdLst.push(dat);
				}
			});
		}
		else {
			let tmpJSON = cortCdDcObj.getMatchedJSON("value", cortCdSbxObj.getValue());

			tmpJSON.forEach((val, idx, arr) => {
				let dat = {
						cortCd: val.value
				};

				cortCdLst.push(dat);
			});
		}

	    com.executeAjax({
	        action: psp.CONTEXT_ROOT + "/pspadm/selectCsDvsCdLstByCortCd.on",
	        mode: mode,
	        method: "POST",
	        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
	        requestData: JSON.stringify({
	        	jdcpcOfcwkTaskTypCdLst: jdcpcOfcwkTaskTypCdLst,
	        	cortCdLst: cortCdLst
	        }),
	        success: function(rslt) {
	        	let datLst = rslt.responseJSON.data.result;

	        	csDvsCdDcObj.setJSON(datLst);

	            for(var i = 0; i < csDvsCdDcObj.getRowCount(); i++) {
	            	csDvsCdDcObj.setCellAllData(i, "label", "(" + csDvsCdDcObj.getCellData(i, "value") + ") " + csDvsCdDcObj.getCellData(i, "label"));
	            }

	        	resolve(true);
	        },
	        error: function (e) {
	            alert("error code : " + e.responseStatusCode);
	            reject(false);
	        },
	    });

	});
};

